INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91514ffb-c29d-4129-81e1-9d89cc13c7e7', '詠史詩 嶓冢', '詠史诗 嶓冢', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["夏禹崩來一萬秋，水從嶓冢至今流。","當時若訴胼胝苦，更使何人別九州。"]', '["夏禹崩来一万秋，水從嶓冢至今流。","當时若訴胼胝苦，更使何人別九州。"]', '诗', 'shi', '', NULL, '詠史詩 嶓冢 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb0c1ccf-03ad-4af5-96a7-bccd914ad86a', '詠史詩 塗山', '詠史诗 塗山', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["大禹塗山御座開，諸侯玉帛走如雷。","防風謾有專車骨，何事茲辰最後來。"]', '["大禹塗山御座开，諸侯玉帛走如雷。","防风謾有專车骨，何事茲辰最後来。"]', '诗', 'shi', '', NULL, '詠史詩 塗山 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f60a0f37-66a9-4e17-967c-166478938f04', '詠史詩 商郊', '詠史诗 商郊', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["鶯囀商郊百草新，殷湯遺蹟在荒榛。","誰知繼桀爲天子，便是當初祝網人。"]', '["鶯囀商郊百草新，殷湯遺蹟在荒榛。","誰知繼桀爲天子，便是當初祝網人。"]', '诗', 'shi', '', NULL, '詠史詩 商郊 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cd3ed34-34eb-4290-9493-e1c747ba5540', '詠史詩 傅巖', '詠史诗 傅巖', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["巖前版築不求伸，方寸那希據要津。","自是武丁安寢夜，一宵宮裏夢賢人。"]', '["巖前版築不求伸，方寸那希據要津。","自是武丁安寢夜，一宵宮裏梦賢人。"]', '诗', 'shi', '', NULL, '詠史詩 傅巖 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e202e2ce-5825-4c84-b2fd-5f7ebbb28a52', '詠史詩 鉅橋', '詠史诗 鉅橋', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["積粟成塵竟不開，誰知拒諫剖賢才。","武王兵起無人敵，遂作商郊一聚灰。"]', '["積粟成塵竟不开，誰知拒諫剖賢才。","武王兵起無人敵，遂作商郊一聚灰。"]', '诗', 'shi', '', NULL, '詠史詩 鉅橋 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b6a1c60-0a12-44df-8e67-1369bd00c2a1', '詠史詩 首陽山', '詠史诗 首陽山', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["孤竹夷齊恥戰爭，望塵遮道請休兵。","首陽山倒爲平地，應始無人說姓名。"]', '["孤竹夷齊恥戰爭，望塵遮道請休兵。","首陽山倒爲平地，應始無人说姓名。"]', '诗', 'shi', '', NULL, '詠史詩 首陽山 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cf8ce9b-94c2-44c9-b963-ebbf3ddb96ab', '詠史詩 孟津', '詠史诗 孟津', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["秋風颯颯孟津頭，立馬沙邊看水流。","見說武王東渡日，戎衣曾此叱陽侯。"]', '["秋风颯颯孟津头，立马沙邊看水流。","见说武王东渡日，戎衣曾此叱陽侯。"]', '诗', 'shi', '', NULL, '詠史詩 孟津 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bb1c3b5-a04e-47d0-8c1f-649d6aa14548', '詠史詩 流沙', '詠史诗 流沙', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["七雄戈戟亂如麻，四海無人得坐家。","老氏却思天竺住，便將徐甲去流沙。"]', '["七雄戈戟亂如麻，四海無人得坐家。","老氏却思天竺住，便將徐甲去流沙。"]', '诗', 'shi', '', NULL, '詠史詩 流沙 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cae88c2-1d89-4855-9497-8cb441083011', '詠史詩 鄧城', '詠史诗 鄧城', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["鄧侯城壘漢江干，自謂深根百世安。","不用三甥謀楚計，臨危方覺噬臍難。"]', '["鄧侯城壘漢江干，自謂深根百世安。","不用三甥謀楚計，臨危方覺噬臍难。"]', '诗', 'shi', '', NULL, '詠史詩 鄧城 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1084295-a1b0-4098-b207-4cab2e1df049', '詠史詩 召陵', '詠史诗 召陵', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["小白匡周入楚郊，楚王雄霸亦咆哮。","不思管仲爲謀主，爭取言徵縮酒茅。"]', '["小白匡周入楚郊，楚王雄霸亦咆哮。","不思管仲爲謀主，爭取言徵縮酒茅。"]', '诗', 'shi', '', NULL, '詠史詩 召陵 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2915ab6c-a9d3-42a9-85c8-066bffae9c3a', '詠史詩 綿山', '詠史诗 綿山', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["親在要君召不來，亂山重疊使空迴。","如何堅執尤人意，甘向巖前作死灰。"]', '["親在要君召不来，亂山重叠使空迴。","如何堅執尤人意，甘向巖前作死灰。"]', '诗', 'shi', '', NULL, '詠史詩 綿山 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b353d75d-8f32-4b2b-836b-643f2f5a4887', '詠史詩 魯城', '詠史诗 魯城', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["魯公城闕已丘墟，荒草無由認玉除。","因笑臧孫才智少，東門鐘鼓祀鶢鶋。"]', '["魯公城闕已丘墟，荒草無由認玉除。","因笑臧孫才智少，东门鐘鼓祀鶢鶋。"]', '诗', 'shi', '', NULL, '詠史詩 魯城 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86a43dc8-d6dd-4e6f-88ff-637aff6a0e29', '詠史詩 驌驦陂', '詠史诗 驌驦陂', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["行行西至一荒陂，因笑唐公不見機。","莫惜驌驦輸令尹，漢東宮闕早時歸。"]', '["行行西至一荒陂，因笑唐公不见機。","莫惜驌驦輸令尹，漢东宮闕早时归。"]', '诗', 'shi', '', NULL, '詠史詩 驌驦陂 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('314907e2-1a54-48de-b066-ae103b41251b', '詠史詩 夾谷', '詠史诗 夾谷', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["夾谷鶯啼三月天，野花芳草整相鮮。","來時不見侏儒死，空笑齊人失措年。"]', '["夾谷鶯啼三月天，野花芳草整相鲜。","来时不见侏儒死，空笑齊人失措年。"]', '诗', 'shi', '', NULL, '詠史詩 夾谷 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7873bf4-4a85-47a9-bc03-22d8e13572af', '詠史詩 吳宮', '詠史诗 吳宮', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["草長黃池千里餘，歸來宗廟已丘墟。","出師不聽忠臣諫，徒恥窮泉見子胥。"]', '["草长黄池千里餘，归来宗廟已丘墟。","出師不听忠臣諫，徒恥窮泉见子胥。"]', '诗', 'shi', '', NULL, '詠史詩 吳宮 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64af3efc-661d-49d8-a986-42a47d6da98d', '詠史詩 摩笄山', '詠史诗 摩笄山', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["春草綿綿岱日低，山邊立馬看摩笄。","黃鶯也解追前事，來向夫人死處啼。"]', '["春草綿綿岱日低，山邊立马看摩笄。","黄鶯也解追前事，来向夫人死处啼。"]', '诗', 'shi', '', NULL, '詠史詩 摩笄山 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('beb93e81-a237-4a19-ab33-a0870c6f6fae', '詠史詩 房陵', '詠史诗 房陵', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["趙王一旦到房陵，國破家亡百恨增。","魂斷叢臺歸不得，夜來明月爲誰升。"]', '["趙王一旦到房陵，国破家亡百恨增。","魂斷叢台归不得，夜来明月爲誰升。"]', '诗', 'shi', '', NULL, '詠史詩 房陵 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1fce6c1-e0d4-4f93-9d56-d478e48dd351', '詠史詩 濮水', '詠史诗 濮水', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["青春行役思悠悠，一曲汀蒲濮水流。","正見塗中龜曳尾，令人特地感莊周。"]', '["青春行役思悠悠，一曲汀蒲濮水流。","正见塗中龟曳尾，令人特地感莊周。"]', '诗', 'shi', '', NULL, '詠史詩 濮水 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('691edfc0-e4a9-41de-aad7-db757fd69c36', '詠史詩 柏舉', '詠史诗 柏舉', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["野田極目草茫茫，吳楚交兵此路傍。","誰料伍員入郢後，大開陵寢撻平王。"]', '["野田極目草茫茫，吳楚交兵此路傍。","誰料伍員入郢後，大开陵寢撻平王。"]', '诗', 'shi', '', NULL, '詠史詩 柏舉 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2aeef01-bbe1-4e9f-8732-864fcacc25eb', '詠史詩 望夫山', '詠史诗 望夫山', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["一上青山便化身，不知何代怨離人。","古來節婦皆銷朽，獨爾不爲泉下塵。"]', '["一上青山便化身，不知何代怨離人。","古来節婦皆銷朽，独爾不爲泉下塵。"]', '诗', 'shi', '', NULL, '詠史詩 望夫山 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d1d6881-f415-46ec-a606-ba3282ce8b51', '詠史詩 金義嶺', '詠史诗 金義嶺', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["鑿開山嶺引湘波，上去昭回不較多。","無限鵲臨橋畔立，適來天道過天河。"]', '["鑿开山嶺引湘波，上去昭回不較多。","無限鵲臨橋畔立，適来天道過天河。"]', '诗', 'shi', '', NULL, '詠史詩 金義嶺 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0b6fc43-e463-4797-b7d9-03035b1bc914', '詠史詩 云云亭', '詠史诗 云云亭', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["一上高亭日正晡，青山重疊片雲無。","萬年松樹不知數，若箇蚪枝是大夫。"]', '["一上高亭日正晡，青山重叠片云無。","万年松樹不知數，若箇蚪枝是大夫。"]', '诗', 'shi', '', NULL, '詠史詩 云云亭 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b947022-7373-4ec6-b413-8de600ca9d0f', '詠史詩 阿房宮', '詠史诗 阿房宮', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["新建阿房壁未乾，沛公兵已入長安。","帝王苦竭生靈力，大業沙崩固不難。"]', '["新建阿房壁未乾，沛公兵已入长安。","帝王苦竭生靈力，大業沙崩固不难。"]', '诗', 'shi', '', NULL, '詠史詩 阿房宮 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eab4e94b-055d-4c90-9ead-e369fd0a3837', '詠史詩 沙丘', '詠史诗 沙丘', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["年年遊覽不曾停，天下山川欲遍經。","堪笑沙丘纔過處，鑾輿風過鮑魚腥。"]', '["年年游覽不曾停，天下山川欲遍經。","堪笑沙丘纔過处，鑾輿风過鲍鱼腥。"]', '诗', 'shi', '', NULL, '詠史詩 沙丘 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd58fb29-15c0-473f-87cf-773c21a471fc', '詠史詩 咸陽', '詠史诗 咸陽', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["一朝閻樂統羣兇，二世朝廷掃地空。","唯有渭川流不盡，至今猶繞望夷宮。"]', '["一朝閻乐統羣兇，二世朝廷掃地空。","唯有渭川流不尽，至今猶繞望夷宮。"]', '诗', 'shi', '', NULL, '詠史詩 咸陽 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f960b161-be0d-4a26-8621-467f5ad48f8f', '詠史詩 廢丘山', '詠史诗 廢丘山', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["此水雖非禹鑿開，廢丘山下重縈迴。","莫言只解東流去，曾使章邯自殺來。"]', '["此水雖非禹鑿开，廢丘山下重縈迴。","莫言只解东流去，曾使章邯自殺来。"]', '诗', 'shi', '', NULL, '詠史詩 廢丘山 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f357246-459f-4780-87e6-3b981681db26', '詠史詩 廣武山', '詠史诗 廣武山', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["數罪楚師應奪氣，底須多論破深艱。","倉皇鬬智成何語，遺笑當時廣武山。"]', '["數罪楚師應奪氣，底須多論破深艱。","倉皇鬬智成何語，遺笑當时廣武山。"]', '诗', 'shi', '', NULL, '詠史詩 廣武山 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0deed735-e88d-4b59-850f-0f78a6f742e4', '詠史詩 長安', '詠史诗 长安', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["關東新破項王歸，赤幟悠揚日月旗。","從此漢家無敵國，爭教彭越受誅夷。"]', '["关东新破項王归，赤幟悠揚日月旗。","從此漢家無敵国，爭教彭越受誅夷。"]', '诗', 'shi', '', NULL, '詠史詩 長安 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3951f2c3-079d-4680-b351-f8946c6cb906', '詠史詩 鴻門', '詠史诗 鴻门', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["項籍鷹揚六合晨，鴻門開宴賀亡秦。","樽前若取謀臣計，豈作陰陵失路人。"]', '["項籍鷹揚六合晨，鴻门开宴賀亡秦。","樽前若取謀臣計，豈作陰陵失路人。"]', '诗', 'shi', '', NULL, '詠史詩 鴻門 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8e8a4d6-2ff7-4fb0-81de-c74b7a8d358a', '詠史詩 漢中', '詠史诗 漢中', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["荆棘蒼蒼漢水湄，將壇煙草覆餘基。","適來投石空江上，猶似龍顏納諫時。"]', '["荆棘蒼蒼漢水湄，將壇煙草覆餘基。","適来投石空江上，猶似龙顏納諫时。"]', '诗', 'shi', '', NULL, '詠史詩 漢中 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ff4cc76-df94-4c2f-b943-7f857434af41', '詠史詩 泜水', '詠史诗 泜水', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["韓信經營按鏌铘，臨戎叱咤有誰加。","猶疑轉戰逢勍敵，更向軍中問左車。"]', '["韓信經營按鏌铘，臨戎叱咤有誰加。","猶疑轉戰逢勍敵，更向軍中问左车。"]', '诗', 'shi', '', NULL, '詠史詩 泜水 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac96e898-32cf-4b8b-bd49-2464b72a0ae0', '詠史詩 雲夢', '詠史诗 云梦', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["漢祖聽讒不可防，僞遊韓信果罹殃。","十年辛苦平天下，何事生擒入帝鄉。"]', '["漢祖听讒不可防，僞游韓信果罹殃。","十年辛苦平天下，何事生擒入帝乡。"]', '诗', 'shi', '', NULL, '詠史詩 雲夢 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('301228bb-b4a9-4034-9a51-44b0d3060007', '詠史詩 高陽', '詠史诗 高陽', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["路入高陽感酈生，逢時長揖便論兵。","最憐伏軾東遊日，下盡齊王七十城。"]', '["路入高陽感酈生，逢时长揖便論兵。","最怜伏軾东游日，下尽齊王七十城。"]', '诗', 'shi', '', NULL, '詠史詩 高陽 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ce074b4-f73b-4b60-a075-80d2c301e8ac', '詠史詩 四皓廟', '詠史诗 四皓廟', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["四皓忘機飲碧松，石巖雲殿隱高蹤。","不知俱出龍樓後，多在商山第幾重。"]', '["四皓忘機饮碧松，石巖云殿隐高蹤。","不知俱出龙楼後，多在商山第幾重。"]', '诗', 'shi', '', NULL, '詠史詩 四皓廟 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('699d92a4-5707-4dae-96db-24767b82a07c', '詠史詩 霸陵', '詠史诗 霸陵', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["原頭日落雪邊雲，猶放韓盧逐兔羣。","況是四方無事日，霸陵誰識舊將軍。"]', '["原头日落雪邊云，猶放韓盧逐兔羣。","況是四方無事日，霸陵誰識旧將軍。"]', '诗', 'shi', '', NULL, '詠史詩 霸陵 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efbcdbfb-6307-45d0-820c-1d18df752e70', '詠史詩 昆明池', '詠史诗 昆明池', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["欲出昆明萬里師，漢皇習戰此穿池。","如何一面圖攻取，不念生靈氣力疲。"]', '["欲出昆明万里師，漢皇習戰此穿池。","如何一面圖攻取，不念生靈氣力疲。"]', '诗', 'shi', '', NULL, '詠史詩 昆明池 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8c4b9bc-b775-4fa1-b186-ac41d37992b7', '詠史詩 迴中', '詠史诗 迴中', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["武皇無路及昆丘，青鳥西沈隴樹秋。","欲問生前躬祀日，幾煩龍駕到涇州。"]', '["武皇無路及昆丘，青鸟西沈隴樹秋。","欲问生前躬祀日，幾煩龙駕到涇州。"]', '诗', 'shi', '', NULL, '詠史詩 迴中 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98ac4269-52bf-4fd8-b8bf-578e2e7765a9', '詠史詩 東門', '詠史诗 东门', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["何人知足反田廬，玉管東門餞二疏。","豈是不榮天子祿，後賢那使久閑居。"]', '["何人知足反田廬，玉管东门餞二疏。","豈是不榮天子祿，後賢那使久闲居。"]', '诗', 'shi', '', NULL, '詠史詩 東門 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4801c0d9-52d1-4bd3-a263-c3ebbb002599', '詠史詩 射熊館', '詠史诗 射熊館', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["漢帝荒唐不解憂，大誇田獵廢農收。","子雲徒獻長楊賦，肯念高皇沐雨秋。"]', '["漢帝荒唐不解憂，大誇田獵廢農收。","子云徒獻长楊賦，肯念高皇沐雨秋。"]', '诗', 'shi', '', NULL, '詠史詩 射熊館 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd9066c4-64a1-44ea-b9b7-c71b04eaf807', '詠史詩 昆陽', '詠史诗 昆陽', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["師克由來在協和，蕭王兵馬固無多。","誰知大敵昆陽敗，却笑前朝困楚歌。"]', '["師克由来在協和，蕭王兵马固無多。","誰知大敵昆陽敗，却笑前朝困楚歌。"]', '诗', 'shi', '', NULL, '詠史詩 昆陽 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25e28997-3e96-4c7b-bec4-6a0c7b5361eb', '詠史詩 七里灘', '詠史诗 七里灘', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["七里青灘映碧層，九天星象感嚴陵。","釣魚臺上無絲竹，不是高人誰解登。"]', '["七里青灘映碧層，九天星象感嚴陵。","釣鱼台上無絲竹，不是高人誰解登。"]', '诗', 'shi', '', NULL, '詠史詩 七里灘 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7932689a-6c71-4120-838f-b1233f5f959d', '詠史詩 潁川', '詠史诗 潁川', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["古賢高尚不爭名，行止由來動杳冥。","今日浪爲千里客，看花慙上德星亭。"]', '["古賢高尚不爭名，行止由来动杳冥。","今日浪爲千里客，看花慙上德星亭。"]', '诗', 'shi', '', NULL, '詠史詩 潁川 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5302460c-2666-4f95-96b5-3c76e4a1497b', '詠史詩 江夏', '詠史诗 江夏', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["黃祖才非長者儔，禰衡珠碎此江頭。","今來鸚鵡洲邊過，惟有無情碧水流。"]', '["黄祖才非长者儔，禰衡珠碎此江头。","今来鸚鵡洲邊過，惟有無情碧水流。"]', '诗', 'shi', '', NULL, '詠史詩 江夏 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0d2b11b-73ed-41d6-adab-de9ac7d5e227', '詠史詩 官渡', '詠史诗 官渡', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["本初屈指定中華，官渡相持勒虎牙。","若使許攸財用足，山河爭得屬曹家。"]', '["本初屈指定中华，官渡相持勒虎牙。","若使許攸財用足，山河爭得屬曹家。"]', '诗', 'shi', '', NULL, '詠史詩 官渡 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b68b35df-a8e0-4f72-b82b-051b09958349', '詠史詩 灞岸', '詠史诗 灞岸', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["長安城外白雲秋，蕭索悲風灞水流。","因想漢朝離亂日，仲宣從此向荆州。"]', '["长安城外白云秋，蕭索悲风灞水流。","因想漢朝離亂日，仲宣從此向荆州。"]', '诗', 'shi', '', NULL, '詠史詩 灞岸 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c9c5f7c-00fe-4d24-a95c-aa09b963ef79', '詠史詩 濡須橋', '詠史诗 濡須橋', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["徒向濡須欲受降，英雄才略獨無雙。","天心不與金陵便，高步何由得渡江。"]', '["徒向濡須欲受降，英雄才略独無雙。","天心不與金陵便，高步何由得渡江。"]', '诗', 'shi', '', NULL, '詠史詩 濡須橋 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b27ab6de-7501-4cc2-987b-afddf703bfd6', '詠史詩 豫州', '詠史诗 豫州', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["策馬行行到豫州，祖生寂寞水空流。","當時更有三年壽，石勒尋爲關下囚。"]', '["策马行行到豫州，祖生寂寞水空流。","當时更有三年壽，石勒尋爲关下囚。"]', '诗', 'shi', '', NULL, '詠史詩 豫州 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c10fc0e5-1f53-4be8-8806-8b4f502137a9', '詠史詩 八公山', '詠史诗 八公山', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["苻堅舉國出西秦，東晉危如累卵晨。","誰料此山諸草木，盡能排難化爲人。"]', '["苻堅舉国出西秦，东晉危如累卵晨。","誰料此山諸草木，尽能排难化爲人。"]', '诗', 'shi', '', NULL, '詠史詩 八公山 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a78f81c-6a0a-438a-8c5e-cd331e1efa4d', '下第', '下第', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["翰苑何時休嫁女，文昌早晚罷生兒。","上林新桂年年發，不許平人折一枝。"]', '["翰苑何时休嫁女，文昌早晚罷生兒。","上林新桂年年發，不許平人折一枝。"]', '诗', 'shi', '', NULL, '下第 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b440d330-6c31-4e27-ae2b-b1be83d528d1', '贈薛濤', '贈薛濤', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["萬里橋邊女校書，枇杷花下閉門居。","掃眉才子知多少，管領春風總不如。"]', '["万里橋邊女校书，枇杷花下閉门居。","掃眉才子知多少，管領春风總不如。"]', '诗', 'shi', '', NULL, '贈薛濤 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea443c03-ab3d-4119-af2e-88011345610a', '採蓮', '採蓮', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["採蓮女兒避殘熱，隔夜相期侵早發。","指剝春葱腕似雪，畫橈輕撥蒲根月。","蘭舟遲速有輸贏，先到河灣賭何物。","纔到河灣分首去，散在花間不知處。"]', '["採蓮女兒避殘熱，隔夜相期侵早發。","指剝春葱腕似雪，畫橈轻撥蒲根月。","蘭舟遲速有輸贏，先到河灣賭何物。","纔到河灣分首去，散在花间不知处。"]', '诗', 'shi', '', NULL, '採蓮 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f7bd3ff-6c6a-4935-b4e1-bcae3436a9a4', '寄李頻', '寄李頻', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["衆木又搖落，望君還不還。","軒車在何處，雨雪滿前山。","思苦文星動，鄉遙釣渚閑。","明年見名姓，唯我獨何顏。"]', '["衆木又搖落，望君還不還。","軒车在何处，雨雪满前山。","思苦文星动，乡遙釣渚闲。","明年见名姓，唯我独何顏。"]', '诗', 'shi', '', NULL, '寄李頻 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db89ed07-30e2-4bee-a251-524b1e3d56b1', '東溪別業寄吉州段郎中', '东溪別業寄吉州段郎中', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["前山含遠翠，羅列在窗中。","盡日人不到，一尊誰與同。","涼隨蓮葉雨，暑避柳條風。","豈分長岑寂，明時有至公。"]', '["前山含远翠，羅列在窗中。","尽日人不到，一尊誰與同。","涼隨蓮葉雨，暑避柳條风。","豈分长岑寂，明时有至公。"]', '诗', 'shi', '', NULL, '東溪別業寄吉州段郎中 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('216b4a68-f610-4bf3-a613-b4ad905f8682', '懷州客舍', '懷州客舍', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["誤飲覃懷酒，誰知滯去程。","朝昏太行色，坐臥沁河聲。","白道穿秦甸，嚴鼙似戍城。","鄰雞莫相促，遊子自晨征。"]', '["誤饮覃懷酒，誰知滯去程。","朝昏太行色，坐臥沁河声。","白道穿秦甸，嚴鼙似戍城。","鄰雞莫相促，游子自晨征。"]', '诗', 'shi', '', NULL, '懷州客舍 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('912006bc-4b5e-44b5-8725-c284293b7c91', '中路寄喻鳧先輩', '中路寄喻鳧先輩', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["求名如未遂，白首亦難歸。","送我尊前酒，典君身上衣。","寒蕪隨楚盡，落葉渡淮稀。","莫歎干時晚，前心豈便非。"]', '["求名如未遂，白首亦难归。","送我尊前酒，典君身上衣。","寒蕪隨楚尽，落葉渡淮稀。","莫歎干时晚，前心豈便非。"]', '诗', 'shi', '', NULL, '中路寄喻鳧先輩 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88dcf393-efa8-45df-9c79-8987380fc203', '送趙明府還北', '送趙明府還北', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["故園終不住，劍鶴在扁舟。","盡室無餘俸，還家得白頭。","鐘催吳岫曉，月遶渭河流。","曾是棲安邑，恩期異日酬。"]', '["故园終不住，劍鹤在扁舟。","尽室無餘俸，還家得白头。","鐘催吳岫晓，月遶渭河流。","曾是棲安邑，恩期異日酬。"]', '诗', 'shi', '', NULL, '送趙明府還北 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('282c33b7-cfce-4c95-9204-c01fb7745b2c', '過朱協律故山', '過朱協律故山', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["地下無餘恨，人間得盛名。","殘篇續大雅，稚子托諸生。","度日山空暮，緣溪鶴自鳴。","難收故交意，寒笛一聲聲。"]', '["地下無餘恨，人间得盛名。","殘篇續大雅，稚子托諸生。","度日山空暮，緣溪鹤自鳴。","难收故交意，寒笛一声声。"]', '诗', 'shi', '', NULL, '過朱協律故山 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7814a03b-b322-4816-8227-0340f927d314', '途中寄劉沆', '途中寄劉沆', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["登車誤相遠，談笑亦何因。","路入瀟湘樹，書隨巴蜀人。","歛衣寒犯雪，傾篋病看春。","莫負髫年志，清朝作獻臣。"]', '["登车誤相远，談笑亦何因。","路入瀟湘樹，书隨巴蜀人。","歛衣寒犯雪，傾篋病看春。","莫負髫年志，清朝作獻臣。"]', '诗', 'shi', '', NULL, '途中寄劉沆 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28fc5eea-2f45-454b-9c0f-ab669bfd3c0f', '送班主簿入謁荆南韋常侍', '送班主簿入謁荆南韋常侍', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["束書成遠去，還計莫經春。","倒篋唯求醉，登舟自笑貧。","波移彭蠡月，樹沒漢陵人。","試吏曾趨府，旌幢自可親。"]', '["束书成远去，還計莫經春。","倒篋唯求醉，登舟自笑貧。","波移彭蠡月，樹沒漢陵人。","試吏曾趨府，旌幢自可親。"]', '诗', 'shi', '', NULL, '送班主簿入謁荆南韋常侍 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e9708d4-3043-4daf-9177-4a7bea0a21d6', '夏日登靈隱寺後峰', '夏日登靈隐寺後峰', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["絕頂無煩暑，登臨三伏中。","深蘿難透日，喬木更含風。","山疊雲霞際，川傾世界東。","那知茲夕興，不與古人同。"]', '["絕頂無煩暑，登臨三伏中。","深蘿难透日，喬木更含风。","山叠云霞際，川傾世界东。","那知茲夕兴，不與古人同。"]', '诗', 'shi', '', NULL, '夏日登靈隱寺後峰 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('537c1a86-c967-41d8-a11e-aec849d9bb43', '聽新蟬寄張晝', '听新蟬寄張晝', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["細聲頻斷續，審聽亦難分。","髣髴應移處，從容却不聞。","蘭棲朝咽露，樹隱暝吟雲。","莫遣鄉愁起，吾懷祗是君。"]', '["細声頻斷續，審听亦难分。","髣髴應移处，從容却不闻。","蘭棲朝咽露，樹隐暝吟云。","莫遣乡愁起，吾懷祗是君。"]', '诗', 'shi', '', NULL, '聽新蟬寄張晝 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ea9b609-5f2d-4983-b566-9748ed50076e', '送喻坦之下第還江東', '送喻坦之下第還江东', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["文戰偶未勝，無令移壯心。","風塵辭帝里，舟檝到家林。","過楚寒方盡，浮淮月正沈。","持杯話來日，不聽洞庭砧。"]', '["文戰偶未勝，無令移壯心。","风塵辞帝里，舟檝到家林。","過楚寒方尽，浮淮月正沈。","持杯話来日，不听洞庭砧。"]', '诗', 'shi', '', NULL, '送喻坦之下第還江東 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c6d015a-9fe2-49c4-83f1-56718c7ce894', '送姚舒下第遊蜀', '送姚舒下第游蜀', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["蜀路何迢遞，憐君獨去遊。","風煙連北虜，山水似東甌。","九折盤荒坂，重江遶漢州。","臨邛一壺酒，能遣長卿愁。"]', '["蜀路何迢遞，怜君独去游。","风煙連北虜，山水似东甌。","九折盤荒坂，重江遶漢州。","臨邛一壺酒，能遣长卿愁。"]', '诗', 'shi', '', NULL, '送姚舒下第遊蜀 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ab7d88d-bb22-4137-a4c4-3ef6ffa2fee7', '旅次錢塘', '旅次錢塘', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["此地似鄉國，堪爲朝夕吟。","雲藏吳相廟，樹引越山禽。","潮落海人散，鐘遲秋寺深。","我來無舊識，誰見寂寥心。"]', '["此地似乡国，堪爲朝夕吟。","云藏吳相廟，樹引越山禽。","潮落海人散，鐘遲秋寺深。","我来無旧識，誰见寂寥心。"]', '诗', 'shi', '', NULL, '旅次錢塘 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33fddbd6-5437-4c79-bd4c-58fcdb7d244e', '別喻鳧', '別喻鳧', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["知心似古人，歲久分彌親。","離別波濤闊，留連槐柳新。","蟆陵寒貰酒，漁浦夜垂綸。","自此星居後，音書豈厭頻。"]', '["知心似古人，歲久分彌親。","離別波濤闊，留連槐柳新。","蟆陵寒貰酒，漁浦夜垂綸。","自此星居後，音书豈厭頻。"]', '诗', 'shi', '', NULL, '別喻鳧 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6649093-93d8-4ebb-a384-5cfd06f2aa86', '送相里燭', '送相里燭', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["相逢未作期，相送定何之。","不得長年少，那堪遠別離。","泛湖乘月早，踐雪過山遲。","永望多時立，翻如在夢思。"]', '["相逢未作期，相送定何之。","不得长年少，那堪远別離。","泛湖乘月早，踐雪過山遲。","永望多时立，翻如在梦思。"]', '诗', 'shi', '', NULL, '送相里燭 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9df3fe52-6f0b-4e28-9009-924934ad580b', '君不來', '君不来', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["閑花未零落，心緒已紛紛。","久客無人見，新禽何處聞？","舟隨一水遠，路出萬山分。","夜月生愁望，孤光必照君。"]', '["闲花未零落，心緒已紛紛。","久客無人见，新禽何处闻？","舟隨一水远，路出万山分。","夜月生愁望，孤光必照君。"]', '诗', 'shi', '', NULL, '君不來 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7423aa8-a14c-403d-9dc0-cdbff5feffe9', '將謁商州呂郎中道出楚州留獻章中丞', '將謁商州呂郎中道出楚州留獻章中丞', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["江流盤復直，浮棹出家林。","商洛路猶遠，山陽春已深。","青雲應有望，白髮未相侵。","才小知難薦，終勞許郭心。"]', '["江流盤复直，浮棹出家林。","商洛路猶远，山陽春已深。","青云應有望，白髮未相侵。","才小知难薦，終勞許郭心。"]', '诗', 'shi', '', NULL, '將謁商州呂郎中道出楚州留獻章中丞 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa40e360-14cf-4b65-a7dd-54f4b17de13c', '金州客舍', '金州客舍', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["卷箔羣峰暮，蕭條未掩關。","江流嶓[冢]雨，路入漢家山。","落葉欹眠後，孤砧倚望間。","此情偏耐醉，難遣酒罍閑。"]', '["卷箔羣峰暮，蕭條未掩关。","江流嶓[冢]雨，路入漢家山。","落葉欹眠後，孤砧倚望间。","此情偏耐醉，难遣酒罍闲。"]', '诗', 'shi', '', NULL, '金州客舍 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06b8584f-8aba-4c65-b082-f2fb23694ab1', '途中逢孫輅因得李頻消息', '途中逢孫輅因得李頻消息', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["灞上寒仍在，柔條亦自新。","山河雖度臘，雨雪未知春。","正憶同袍者，堪逢共國人。","銜杯益無語，與爾轉相親。"]', '["灞上寒仍在，柔條亦自新。","山河雖度臘，雨雪未知春。","正憶同袍者，堪逢共国人。","銜杯益無語，與爾轉相親。"]', '诗', 'shi', '', NULL, '途中逢孫輅因得李頻消息 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('988873f6-5213-41bc-aefa-b82a2610326c', '送從兄郜', '送從兄郜', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["道路本無限，又應何處逢？","流年莫虛擲，華髪不相容。","野渡波搖月，空城雨翳鐘。","此心隨去馬，迢遞過千峰。"]', '["道路本無限，又應何处逢？","流年莫虛擲，华髪不相容。","野渡波搖月，空城雨翳鐘。","此心隨去马，迢遞過千峰。"]', '诗', 'shi', '', NULL, '送從兄郜 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e948e721-0489-4665-b340-a65e258c8c80', '送許溫', '送許溫', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["壯歲分冞切，少年心正同。","當聞千里去，難遣一尊空。","翳燭蒹葭雨，吹帆橘柚風。","明年見親族，盡集在懷中。"]', '["壯歲分冞切，少年心正同。","當闻千里去，难遣一尊空。","翳燭蒹葭雨，吹帆橘柚风。","明年见親族，尽集在懷中。"]', '诗', 'shi', '', NULL, '送許溫 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c02dd15a-1ca1-4d58-8dca-7905382a5a20', '鏡中別業二首 一', '镜中別業二首 一', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["寒山壓鏡心，此處是家林。","梁燕窺春醉，嵒猿學夜吟。","雲連平地起，月向白波沈。","猶自聞鐘角，棲身可在深。"]', '["寒山壓镜心，此处是家林。","梁燕窺春醉，嵒猿学夜吟。","云連平地起，月向白波沈。","猶自闻鐘角，棲身可在深。"]', '诗', 'shi', '', NULL, '鏡中別業二首 一 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0910975-76bf-4a43-aec8-ab2898d6f05c', '鏡中別業二首 二', '镜中別業二首 二', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["世人如不容，吾自縱天慵。","落葉憑風掃，香秔倩水舂。","花朝連郭霧，雪夜隔湖鐘。","身外無能事，頭宜白此峰。"]', '["世人如不容，吾自縱天慵。","落葉憑风掃，香秔倩水舂。","花朝連郭霧，雪夜隔湖鐘。","身外無能事，头宜白此峰。"]', '诗', 'shi', '', NULL, '鏡中別業二首 二 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a25656f-290c-497a-b5d7-670022ecd9ae', '經周處士故居', '經周处士故居', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["愁吟與獨行，何事不傷情。","久立釣魚處，唯聞啼鳥聲。","山蔬和草嫩，海樹入籬生。","吾在茲溪上，懷君恨不平。"]', '["愁吟與独行，何事不傷情。","久立釣鱼处，唯闻啼鸟声。","山蔬和草嫩，海樹入籬生。","吾在茲溪上，懷君恨不平。"]', '诗', 'shi', '', NULL, '經周處士故居 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e11586ae-a259-416a-a0e9-6dd2835066f2', '贈喻鳧', '贈喻鳧', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["所得非衆語，衆人那得知。","纔吟五字句，又白幾莖髭。","月閣欹眠夜，霜軒正坐時。","沈思心更苦，恐作滿頭絲。"]', '["所得非衆語，衆人那得知。","纔吟五字句，又白幾莖髭。","月閣欹眠夜，霜軒正坐时。","沈思心更苦，恐作满头絲。"]', '诗', 'shi', '', NULL, '贈喻鳧 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37d6d80a-b183-4fbc-8d1f-bc7da73bb3bc', '早發洞庭', '早發洞庭', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["長天接廣澤，二氣共含秋。","舉目無平地，何心戀直鉤。","孤鐘鳴大岸，片月落中流。","却憶鴟夷子，當時此泛舟。"]', '["长天接廣澤，二氣共含秋。","舉目無平地，何心戀直鉤。","孤鐘鳴大岸，片月落中流。","却憶鴟夷子，當时此泛舟。"]', '诗', 'shi', '', NULL, '早發洞庭 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08ff2f82-8894-4219-96b7-d5b5500ad123', '貽錢塘縣路明府', '貽錢塘縣路明府', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["志業不得力，到今猶苦吟。","唫成五字句，用破一生心。","世路屈聲遠，寒溪怨氣深。","前賢多晚達，莫怕鬢霜侵。"]', '["志業不得力，到今猶苦吟。","唫成五字句，用破一生心。","世路屈声远，寒溪怨氣深。","前賢多晚達，莫怕鬢霜侵。"]', '诗', 'shi', '', NULL, '貽錢塘縣路明府 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70d1abe4-fd20-446e-bb56-340dfed6c886', '湖上言事寄長城喻明府', '湖上言事寄长城喻明府', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["吟霜與臥雲，此興亦甘貧。","吹箭落翠羽，垂絲牽錦鱗。","滿湖風撼月，半日雨藏春。","却笑縈簪組，勞心字遠人。"]', '["吟霜與臥云，此兴亦甘貧。","吹箭落翠羽，垂絲牽錦鱗。","满湖风撼月，半日雨藏春。","却笑縈簪組，勞心字远人。"]', '诗', 'shi', '', NULL, '湖上言事寄長城喻明府 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f20efba0-0932-4f14-8e68-dc4c8f8c6d78', '涵碧亭', '涵碧亭', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["高低竹雜松，積翠復留風。","路極陰溪裏，寒生暑氣中。","閑雲低覆草，片水靜涵空。","方見洋源牧，心侔造化功。"]', '["高低竹杂松，積翠复留风。","路極陰溪裏，寒生暑氣中。","闲云低覆草，片水静涵空。","方见洋源牧，心侔造化功。"]', '诗', 'shi', '', NULL, '涵碧亭 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2910d0ab-6354-4a43-af9d-ecbcf9a977df', '除夜', '除夜', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["永懷難自問，此夕衆愁興。","曉韻侵春角，寒光隔歲燈。","心燃一寸火，淚結兩行冰。","煦育誠非遠，陽和又欲昇。"]', '["永懷难自问，此夕衆愁兴。","晓韻侵春角，寒光隔歲灯。","心燃一寸火，泪結兩行冰。","煦育誠非远，陽和又欲昇。"]', '诗', 'shi', '', NULL, '除夜 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87fe9ca3-ecf3-46b3-9cbe-be9ba6cf3a03', '贈許牘山人', '贈許牘山人', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["才子醉更逸，一吟傾一觴。","支頤忍有得，搖筆便成章。","王粲實可重，禰衡爭不狂。","何時應會面，夢裏是瀟湘。"]', '["才子醉更逸，一吟傾一觴。","支頤忍有得，搖笔便成章。","王粲實可重，禰衡爭不狂。","何时應會面，梦裏是瀟湘。"]', '诗', 'shi', '', NULL, '贈許牘山人 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ec6ad27-5cb4-4979-bb59-e25d2358e790', '贈功成將', '贈功成將', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["定難在明略，何曾勞戰爭。","飛書諭強寇，計日下重城。","深雪移軍夜，寒笳出塞情。","苦心殊易老，新髪早年生。"]', '["定难在明略，何曾勞戰爭。","飞书諭強寇，計日下重城。","深雪移軍夜，寒笳出塞情。","苦心殊易老，新髪早年生。"]', '诗', 'shi', '', NULL, '贈功成將 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1acb0da-22b0-424a-b376-b752b4cf00d0', '白艾原客', '白艾原客', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["原上桑柘瘦，再來還見貧。","滄州幾年隱，白髮一莖新。","敗葉平空塹，殘陽滿近隣。","閑言說知己，半是學禪人。"]', '["原上桑柘瘦，再来還见貧。","滄州幾年隐，白髮一莖新。","敗葉平空塹，殘陽满近隣。","闲言说知己，半是学禪人。"]', '诗', 'shi', '', NULL, '白艾原客 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('446becdb-0cc3-4ef8-8bca-c24e8f2ee3c0', '朔管', '朔管', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["寥寥落何處，一夜過胡天。","送苦秋風外，吹愁白髮邊。","望鄉皆下淚，久戍盡休眠。","寂寞空沙曉，開眸片月懸。"]', '["寥寥落何处，一夜過胡天。","送苦秋风外，吹愁白髮邊。","望乡皆下泪，久戍尽休眠。","寂寞空沙晓，开眸片月懸。"]', '诗', 'shi', '', NULL, '朔管 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98447cde-dbfc-4d23-8e37-367b4c4b3108', '憶故山', '憶故山', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["舊山長繫念，終日臥邊亭。","道路知已遠，夢魂空再經。","秋泉涼好引，乳鶴靜宜聽。","獨上高樓望，蓬身且未寧。"]', '["旧山长繫念，終日臥邊亭。","道路知已远，梦魂空再經。","秋泉涼好引，乳鹤静宜听。","独上高楼望，蓬身且未寧。"]', '诗', 'shi', '', NULL, '憶故山 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56af8751-f431-4937-8723-7028c0b90ae0', '冬夜泊僧舍', '冬夜泊僧舍', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["江東寒近臘，野寺水天昏。","無酒能消夜，隨僧早閉門。","照墻燈焰細，著瓦雨聲繁。","漂泊仍千里，清吟欲斷魂。"]', '["江东寒近臘，野寺水天昏。","無酒能消夜，隨僧早閉门。","照墻灯焰細，著瓦雨声繁。","漂泊仍千里，清吟欲斷魂。"]', '诗', 'shi', '', NULL, '冬夜泊僧舍 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('898d1a7c-c627-428d-8ca9-44741ea4d987', '新秋獨夜寄戴叔倫', '新秋独夜寄戴叔倫', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["遙夜獨不臥，寂寥庭戶中。","河明五陵上，月滿九門東。","萬里親朋散，故園滄海空。","歸懷正南望，此夕起秋風。"]', '["遙夜独不臥，寂寥庭戶中。","河明五陵上，月满九门东。","万里親朋散，故园滄海空。","归懷正南望，此夕起秋风。"]', '诗', 'shi', '', NULL, '新秋獨夜寄戴叔倫 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d92e117-b18e-42b7-ba62-865dd047f58d', '送沛縣司馬丞之任', '送沛縣司马丞之任', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["舉酒一相勸，逢春聊盡歡。","羇遊故交少，遠別後期難。","路上野花發，雨中青草寒。","悠悠兩都夢，小沛與長安。"]', '["舉酒一相勸，逢春聊尽歡。","羇游故交少，远別後期难。","路上野花發，雨中青草寒。","悠悠兩都梦，小沛與长安。"]', '诗', 'shi', '', NULL, '送沛縣司馬丞之任 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b07b91d-182e-4a91-b430-7f0515c4c110', '送盧評事東歸', '送盧評事东归', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["萬里楊柳色，出關隨故人。","輕煙覆流水，落日照行塵。","積夢江湖闊，憶家兄弟貧。","裴回灞亭上，不語共傷春。"]', '["万里楊柳色，出关隨故人。","轻煙覆流水，落日照行塵。","積梦江湖闊，憶家兄弟貧。","裴回灞亭上，不語共傷春。"]', '诗', 'shi', '', NULL, '送盧評事東歸 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('469ebce1-1cc8-4396-b86a-92d2d747c9cf', '清明日送鄧芮還鄉', '清明日送鄧芮還乡', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["鐘鼓喧離室，車徒促夜裝。","曉榆新變火，輕柳暗飛霜。","轉鏡看華髪，傳杯話故鄉。","每嫌兒女淚，今日自沾裳。"]', '["鐘鼓喧離室，车徒促夜裝。","晓榆新变火，轻柳暗飞霜。","轉镜看华髪，傳杯話故乡。","每嫌兒女泪，今日自沾裳。"]', '诗', 'shi', '', NULL, '清明日送鄧芮還鄉 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5349b866-ffbc-45f6-b94d-cd7fd3a5008b', '送崔拾遺出使江東', '送崔拾遺出使江东', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["九門思諫諍，萬里采風謠。","關外逢秋月，天涯過晚潮。","雁飛雲杳杳，木落浦蕭蕭。","空怨他鄉別，回舟暮寂寥。"]', '["九门思諫諍，万里采风謠。","关外逢秋月，天涯過晚潮。","雁飞云杳杳，木落浦蕭蕭。","空怨他乡別，回舟暮寂寥。"]', '诗', 'shi', '', NULL, '送崔拾遺出使江東 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b81fee60-8250-47f6-b541-7442dac7a613', '重陽日送洛陽李丞之任', '重陽日送洛陽李丞之任', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["爲文通絕境，從宦及良辰。","洛下知名早，腰邊結綬新。","且傾浮菊酒，聊拂染衣塵。","獨恨滄州侶，愁來別故人。"]', '["爲文通絕境，從宦及良辰。","洛下知名早，腰邊結綬新。","且傾浮菊酒，聊拂染衣塵。","独恨滄州侶，愁来別故人。"]', '诗', 'shi', '', NULL, '重陽日送洛陽李丞之任 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('614337bb-d830-451e-ae52-2dd6d7b87ed6', '江州送李侍御歸東洛', '江州送李侍御归东洛', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["獨乘驄馬去，不並旅人還。","中外名卿貴，田園高步閑。","暮春經楚縣，新月上淮山。","道路空瞻望，軒車不敢攀。"]', '["独乘驄马去，不並旅人還。","中外名卿貴，田园高步闲。","暮春經楚縣，新月上淮山。","道路空瞻望，軒车不敢攀。"]', '诗', 'shi', '', NULL, '江州送李侍御歸東洛 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2ae6fc3-2b66-4f79-b8b3-37748ee60dd7', '送郭太祝歸江東', '送郭太祝归江东', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["鄉人去欲盡，北雁又南飛。","京洛風塵久，江淮音信稀。","舊山知獨往，一醉莫相違。","未得解羇旅，無勞問是非。"]', '["乡人去欲尽，北雁又南飞。","京洛风塵久，江淮音信稀。","旧山知独往，一醉莫相違。","未得解羇旅，無勞问是非。"]', '诗', 'shi', '', NULL, '送郭太祝歸江東 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('971f3450-5edd-4da1-8b4a-820be76cfb69', '送李恬及第後還貝州', '送李恬及第後還貝州', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["成名年少日，就業聖人書。","擢桂誰相比，籝金已不如。","東城送歸客，秋日待征車。","若到清潭畔，儒風變里閭。"]', '["成名年少日，就業聖人书。","擢桂誰相比，籝金已不如。","东城送归客，秋日待征车。","若到清潭畔，儒风变里閭。"]', '诗', 'shi', '', NULL, '送李恬及第後還貝州 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('195db8dd-0613-4715-81e4-585888488b56', '收兩京後還上都兼訪一二親故', '收兩京後還上都兼訪一二親故', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["離堂千里客，歸騎五陵人。","路轉函關晚，煙開上苑新。","天涯將野服，闕下見鄉親。","問得存亡事，裁詩寄海濱。"]', '["離堂千里客，归騎五陵人。","路轉函关晚，煙开上苑新。","天涯將野服，闕下见乡親。","问得存亡事，裁诗寄海濱。"]', '诗', 'shi', '', NULL, '收兩京後還上都兼訪一二親故 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('550f1927-69d1-46e2-b74c-1e4277b576f5', '送汶上王明府之任', '送汶上王明府之任', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["何時到故鄉，歸去佩銅章。","親友移家盡，閭閻百戰傷。","背關餘草木，出塞足風霜。","遺老應相賀，知君不下堂。"]', '["何时到故乡，归去佩銅章。","親友移家尽，閭閻百戰傷。","背关餘草木，出塞足风霜。","遺老應相賀，知君不下堂。"]', '诗', 'shi', '', NULL, '送汶上王明府之任 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f91ab51-a47a-44fb-9b6d-5a57cdea3db3', '湖南使院遣情送江夏賀侍郎', '湖南使院遣情送江夏賀侍郎', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["雲雨一消散，悠悠關復河。","俱從泛舟役，遂隔洞庭波。","楚水去不盡，秋風今更過。","無由得相見，却恨寄書多。"]', '["云雨一消散，悠悠关复河。","俱從泛舟役，遂隔洞庭波。","楚水去不尽，秋风今更過。","無由得相见，却恨寄书多。"]', '诗', 'shi', '', NULL, '湖南使院遣情送江夏賀侍郎 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2f4ad5f-7fc4-4038-a17c-4a124bf9e937', '過申州作', '過申州作', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["萬人曾死戰，幾戶免刀兵。","井邑初安堵，兒童未長成。","涼風吹古木，野火燒殘營。","寥落千餘里，山高水復清。"]', '["万人曾死戰，幾戶免刀兵。","井邑初安堵，兒童未长成。","涼风吹古木，野火燒殘營。","寥落千餘里，山高水复清。"]', '诗', 'shi', '', NULL, '過申州作 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98ab4706-5c35-4616-a758-587cdce03600', '汝南過訪田評事', '汝南過訪田評事', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["移家近漢陰，不復問華簪。","買酒宜城遠，燒田夢澤深。","暮山逢鳥入，寒水見魚沈。","與物皆無累，終年愜本心。"]', '["移家近漢陰，不复问华簪。","買酒宜城远，燒田梦澤深。","暮山逢鸟入，寒水见鱼沈。","與物皆無累，終年愜本心。"]', '诗', 'shi', '', NULL, '汝南過訪田評事 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7af4fd9-6339-4c67-8962-16fe5caf52bf', '送道上人遊方', '送道上人游方', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["律儀通外學，詩思入玄關。","煙景隨人別，風姿與物閑。","貫花留靜室，咒水度空山。","誰識浮雲意，悠悠天地間。"]', '["律儀通外学，诗思入玄关。","煙景隨人別，风姿與物闲。","貫花留静室，咒水度空山。","誰識浮云意，悠悠天地间。"]', '诗', 'shi', '', NULL, '送道上人遊方 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('542f3f61-746d-41fb-82ea-47ff0a40f0a2', '送饒州王司法之任兼寄朱處士', '送饒州王司法之任兼寄朱处士', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["莫辭還作吏，且喜速回車。","留醉悲殘歲，含情寄遠書。","共看衰老近，轉覺宦名虛。","遙想清溪畔，幽人得自如。"]', '["莫辞還作吏，且喜速回车。","留醉悲殘歲，含情寄远书。","共看衰老近，轉覺宦名虛。","遙想清溪畔，幽人得自如。"]', '诗', 'shi', '', NULL, '送饒州王司法之任兼寄朱處士 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af31dddf-eee7-445a-8511-3c4c3f1e9bfa', '詹碏山居', '詹碏山居', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["愛此棲心靜，風塵路已賒。","十餘莖野竹，一兩樹山花。","遶石開泉細，穿蘿引徑斜。","無人會幽意，來往在煙霞。"]', '["愛此棲心静，风塵路已賒。","十餘莖野竹，一兩樹山花。","遶石开泉細，穿蘿引徑斜。","無人會幽意，来往在煙霞。"]', '诗', 'shi', '', NULL, '詹碏山居 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23de0fd0-fefe-418a-ac6f-71c62443860b', '曉角', '晓角', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["畫角吹殘月，寒聲發戍樓。","立霜嘶馬怨，攢磧泣兵愁。","燕雁鳴雲畔，胡風冷草頭。","罷聞三會後，天逈曉星流。"]', '["畫角吹殘月，寒声發戍楼。","立霜嘶马怨，攢磧泣兵愁。","燕雁鳴云畔，胡风冷草头。","罷闻三會後，天逈晓星流。"]', '诗', 'shi', '', NULL, '曉角 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2369358-7d9d-49ba-acb1-c7b85ba94e95', '冬日', '冬日', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["燒火掩關坐，窮居客訪稀。","凍雲愁暮色，寒日淡斜暉。","穿牖竹風滿，遶庭雲葉飛。","已嗟周一歲，羇寓尚何依。"]', '["燒火掩关坐，窮居客訪稀。","凍云愁暮色，寒日淡斜暉。","穿牖竹风满，遶庭云葉飞。","已嗟周一歲，羇寓尚何依。"]', '诗', 'shi', '', NULL, '冬日 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b774434-3435-4dbe-b5a5-558913822fab', '殘秋送友', '殘秋送友', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["早爲千里別，況復是秋殘。","木葉怨先老，江雲愁暮寒。","交情如水淡，離酒泛杯寬。","料想還家後，休吟行路難。"]', '["早爲千里別，況复是秋殘。","木葉怨先老，江云愁暮寒。","交情如水淡，離酒泛杯寬。","料想還家後，休吟行路难。"]', '诗', 'shi', '', NULL, '殘秋送友 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28e1801c-e062-4514-bd71-1198dc4a4c62', '客行', '客行', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["藕葉綴爲衣，東西泣路岐。","鄉心日落後，身計酒醒時。","觸目多添感，凝情足所思。","羈愁難盡遣，行坐一低眉。"]', '["藕葉綴爲衣，东西泣路岐。","乡心日落後，身計酒醒时。","觸目多添感，凝情足所思。","羈愁难尽遣，行坐一低眉。"]', '诗', 'shi', '', NULL, '客行 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfc43e14-5ffd-41cf-b444-89f6e3da1e4d', '秋夜', '秋夜', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["度鴻驚睡醒，欹枕已三更。","夢破寂寥思，燈殘零落明。","空窗閑月色，幽壁靜蟲聲。","況是離鄉久，依然無限情。"]', '["度鴻驚睡醒，欹枕已三更。","梦破寂寥思，灯殘零落明。","空窗闲月色，幽壁静蟲声。","況是離乡久，依然無限情。"]', '诗', 'shi', '', NULL, '秋夜 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38f15ae7-30ca-44c5-b4d1-ce74c370c84e', '新月', '新月', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["入夜天西見，蛾[眉]冷素光。","潭魚驚釣落，雲雁怯弓張。","隱隱臨珠箔，微微上粉墻。","更憐三五夕，仙桂滿輪芳。"]', '["入夜天西见，蛾[眉]冷素光。","潭鱼驚釣落，云雁怯弓張。","隐隐臨珠箔，微微上粉墻。","更怜三五夕，仙桂满輪芳。"]', '诗', 'shi', '', NULL, '新月 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('603d1bd2-1966-4bf1-a83d-ac3ec14ca31f', '滁上懷周賀', '滁上懷周賀', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["就枕忽不寐，孤懷興歎初。","南譙收舊曆，上苑絕來書。","暝雪細聲積，晨鐘寒韻疎。","侯門昔彈鋏，曾共食江魚。"]', '["就枕忽不寐，孤懷兴歎初。","南譙收旧曆，上苑絕来书。","暝雪細声積，晨鐘寒韻疎。","侯门昔彈鋏，曾共食江鱼。"]', '诗', 'shi', '', NULL, '滁上懷周賀 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38102412-14f3-414c-9d2d-9ac27471726c', '寄石湓清越上人', '寄石湓清越上人', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["寺處唯高僻，雲生石枕前。","靜吟因得句，獨夜不妨禪。","窗接停猨樹，巖飛浴鶴泉。","相思有書札，俱倩獵人傳。"]', '["寺处唯高僻，云生石枕前。","静吟因得句，独夜不妨禪。","窗接停猨樹，巖飞浴鹤泉。","相思有书札，俱倩獵人傳。"]', '诗', 'shi', '', NULL, '寄石湓清越上人 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3330b9a5-01c5-46e5-8f8b-b88b4c7f7212', '陳式水墨山水', '陳式水墨山水', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["造化有功力，平分歸筆端。","溪如冰後聽，山似燒來看。","立意雪髯出，支頤煙汗乾。","世間從爾後，應覺致名難。"]', '["造化有功力，平分归笔端。","溪如冰後听，山似燒来看。","立意雪髯出，支頤煙汗乾。","世间從爾後，應覺致名难。"]', '诗', 'shi', '', NULL, '陳式水墨山水 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31b2aa54-caed-497d-9062-0b31ff8c26fe', '陳秀才亭際木蘭', '陳秀才亭際木蘭', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["昔見初栽日，今逢成樹時。","存思心更感，遶看步還遲。","蝶舞搖風蘂，鶯啼含露枝。","裴回不忍去，應與醉相宜。"]', '["昔见初栽日，今逢成樹时。","存思心更感，遶看步還遲。","蝶舞搖风蘂，鶯啼含露枝。","裴回不忍去，應與醉相宜。"]', '诗', 'shi', '', NULL, '陳秀才亭際木蘭 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d079a36-af6d-4dcd-b933-d2b6516a7b89', '贈鏡公', '贈镜公', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["幽獨度遙夜，夜清神更閑。","高風吹越樹，細露濕湖山。","月皎微吟後，鐘鳴不寐間。","如教累簪組，此興豈相關。"]', '["幽独度遙夜，夜清神更闲。","高风吹越樹，細露濕湖山。","月皎微吟後，鐘鳴不寐间。","如教累簪組，此兴豈相关。"]', '诗', 'shi', '', NULL, '贈鏡公 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0065a4a9-d0d0-47b6-81c3-f7a2661f9c5e', '登雪竇僧家', '登雪竇僧家', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["登寺尋盤道，人煙遠更微。","石窗秋見海，山靄暮侵衣。","衆木隨僧老，高泉盡日飛。","誰能厭軒冕，來此便忘機。"]', '["登寺尋盤道，人煙远更微。","石窗秋见海，山靄暮侵衣。","衆木隨僧老，高泉尽日飞。","誰能厭軒冕，来此便忘機。"]', '诗', 'shi', '', NULL, '登雪竇僧家 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3db59a4a-6a16-4baa-b7c9-e27b60550c05', '途中逢進士許巢', '途中逢進士許巢', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["聲望去已遠，門人無不知。","義行相識處，貧過少年時。","妨寐夜吟苦，愛閑身達遲。","難求似君者，我去更逢誰。"]', '["声望去已远，门人無不知。","義行相識处，貧過少年时。","妨寐夜吟苦，愛闲身達遲。","难求似君者，我去更逢誰。"]', '诗', 'shi', '', NULL, '途中逢進士許巢 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38c6a382-acaa-4635-8ff6-a1f64a8db1df', '贈瑪瑙山禪者', '贈瑪瑙山禪者', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["芿草不停獸，因師山更靈。","村林朝乞食，風雨夜開扃。","井味兼松粉，雲根着淨瓶。","塵勞如醉夢，對此暫能醒。"]', '["芿草不停獸，因師山更靈。","村林朝乞食，风雨夜开扃。","井味兼松粉，云根着淨瓶。","塵勞如醉梦，对此暫能醒。"]', '诗', 'shi', '', NULL, '贈瑪瑙山禪者 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f0a2210-7ade-4233-bb78-127bd6c5a5f7', '詶故人陳乂都', '詶故人陳乂都', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["遠別那無夢，重遊自有期。","半年鄉信到，兩地赤心知。","坐久吟移調，更長硯結凘。","文人才力薄，終怕阿戎欺。"]', '["远別那無梦，重游自有期。","半年乡信到，兩地赤心知。","坐久吟移調，更长硯結凘。","文人才力薄，終怕阿戎欺。"]', '诗', 'shi', '', NULL, '詶故人陳乂都 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04cb418e-1a3f-487d-b3c3-4b4beb822fda', '閏春', '閏春', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["冪冪復蒼蒼，微和傍早陽。","前春寒已盡，待閏日猶長。","柳變雖因雨，花遲豈爲霜。","自茲延聖曆，誰不駐年光。"]', '["冪冪复蒼蒼，微和傍早陽。","前春寒已尽，待閏日猶长。","柳变雖因雨，花遲豈爲霜。","自茲延聖曆，誰不駐年光。"]', '诗', 'shi', '', NULL, '閏春 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccceb8ba-2faf-41b6-86fe-4cf0d7609dca', '方著作畫竹', '方著作畫竹', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["疊葉與高節，俱從毫末生。","流傳千古譽，研鍊十年情。","向月本無影，臨風疑有聲。","吾家釣臺畔，似此兩三莖。"]', '["叠葉與高節，俱從毫末生。","流傳千古譽，研鍊十年情。","向月本無影，臨风疑有声。","吾家釣台畔，似此兩三莖。"]', '诗', 'shi', '', NULL, '方著作畫竹 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5705d7d-10e8-422f-945c-e56061f5f416', '題友人山花', '題友人山花', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["平明方發盡，爲待好風吹。","不見移來日，先愁落去時。","濃香薰疊葉，繁朵壓卑枝。","坐看皆終夕，遊蜂似有期。"]', '["平明方發尽，爲待好风吹。","不见移来日，先愁落去时。","濃香薰叠葉，繁朵壓卑枝。","坐看皆終夕，游蜂似有期。"]', '诗', 'shi', '', NULL, '題友人山花 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d8e1226-937d-46b3-83f8-c071463ac5e4', '贈詩僧懷靜', '贈诗僧懷静', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["幾生餘習在，時復作微吟。","坐夏莓苔合，行禪檜柏深。","入山成白首，學道是初心。","心地不移變，徒云寒暑侵。"]', '["幾生餘習在，时复作微吟。","坐夏莓苔合，行禪檜柏深。","入山成白首，学道是初心。","心地不移变，徒云寒暑侵。"]', '诗', 'shi', '', NULL, '贈詩僧懷靜 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2943d552-63b0-456f-9da9-a7cf0735c907', '贈許牘秀才', '贈許牘秀才', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["理論與妙用，皆從人外來。","山河澄正氣，雪月助宏才。","傲世寄漁艇，藏名歸酒杯。","升沈在方寸，即恐起風雷。"]', '["理論與妙用，皆從人外来。","山河澄正氣，雪月助宏才。","傲世寄漁艇，藏名归酒杯。","升沈在方寸，即恐起风雷。"]', '诗', 'shi', '', NULL, '贈許牘秀才 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d1354ef-d056-45b8-b3d0-c571af440158', '送于丹', '送于丹', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["至業是至寶，莫過心自知。","時情如甚暢，天道即無私。","入洛霜霰苦，離家蘭菊衰。","焚舟不回顧，薄暮又何之。"]', '["至業是至寶，莫過心自知。","时情如甚暢，天道即無私。","入洛霜霰苦，離家蘭菊衰。","焚舟不回顧，薄暮又何之。"]', '诗', 'shi', '', NULL, '送于丹 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c9bbf31-a372-4b6d-8c81-36c2b0eb7a66', '送人遊日本國', '送人游日本国', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["滄茫大荒外，風教即難知。","連夜揚帆去，經年到岸遲。","波濤含左界，星斗定東維。","或有歸風便，當爲相見期。"]', '["滄茫大荒外，风教即难知。","連夜揚帆去，經年到岸遲。","波濤含左界，星斗定东維。","或有归风便，當爲相见期。"]', '诗', 'shi', '', NULL, '送人遊日本國 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f9b15c7-c353-48fd-951a-3acc4ee43150', '東溪言事寄于丹', '东溪言事寄于丹', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["日月晝夜轉，年光難駐留。","軒窗才過雨，枕簟即知秋。","草際鳥行出，溪中虹影收。","唯君壯心在，應笑臥滄洲。"]', '["日月晝夜轉，年光难駐留。","軒窗才過雨，枕簟即知秋。","草際鸟行出，溪中虹影收。","唯君壯心在，應笑臥滄洲。"]', '诗', 'shi', '', NULL, '東溪言事寄于丹 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86ed3878-bba1-474c-92c3-f29908bb7bb9', '暮發七里灘夜泊嚴光臺下', '暮發七里灘夜泊嚴光台下', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["一瞬即七里，箭馳猶是難。","檣邊走嵐翠，枕底失風湍。","但訝猨鳥定，不知霜月寒。","前賢竟何益，此地誤垂竿。"]', '["一瞬即七里，箭驰猶是难。","檣邊走嵐翠，枕底失风湍。","但訝猨鸟定，不知霜月寒。","前賢竟何益，此地誤垂竿。"]', '诗', 'shi', '', NULL, '暮發七里灘夜泊嚴光臺下 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('330e085f-4b9e-413e-9281-e4753fc5a4b3', '處州洞溪', '处州洞溪', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["氣象四時清，無人畫得成。","衆山寒疊翠，兩派綠分聲。","坐月何曾夜，聽松不似晴。","混元融結後，便有此溪名。"]', '["氣象四时清，無人畫得成。","衆山寒叠翠，兩派綠分声。","坐月何曾夜，听松不似晴。","混元融結後，便有此溪名。"]', '诗', 'shi', '', NULL, '處州洞溪 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('520556ce-3f7f-41f5-98fe-7a66e6e7227b', '稱心寺中島', '稱心寺中島', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["水木深不極，似將星漢連。","中州唯此地，上界別無天。","雪折停猨樹，花藏浴鶴泉。","師爲終老意，日日復年年。"]', '["水木深不極，似將星漢連。","中州唯此地，上界別無天。","雪折停猨樹，花藏浴鹤泉。","師爲終老意，日日复年年。"]', '诗', 'shi', '', NULL, '稱心寺中島 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32fdf308-96cd-4f85-9759-81c2500d4986', '歲晚苦寒', '歲晚苦寒', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["地氣寒不暢，嚴風無定時。","挑燈青燼少，呵筆尺書遲。","白兔沒已久，晨雞僵未知。","竚看開聖曆，喧煦立爲期。"]', '["地氣寒不暢，嚴风無定时。","挑灯青燼少，呵笔尺书遲。","白兔沒已久，晨雞僵未知。","竚看开聖曆，喧煦立爲期。"]', '诗', 'shi', '', NULL, '歲晚苦寒 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ed1226c-2321-4a25-ade8-2929fe0f2c87', '杜鵑花', '杜鵑花', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["未問移栽日，先愁落地時。","疎中從間葉，密處莫燒枝。","郢客教誰探，胡蜂是自知。","周回兩三步，常有醉鄉期。"]', '["未问移栽日，先愁落地时。","疎中從间葉，密处莫燒枝。","郢客教誰探，胡蜂是自知。","周回兩三步，常有醉乡期。"]', '诗', 'shi', '', NULL, '杜鵑花 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7d2a57b-425a-47a7-b2a6-e0e2f18ad089', '山中', '山中', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["散拙亦自遂，麤將猨鳥同。","飛泉高瀉月，獨樹逈含風。","果落盤盂上，雲生篋笥中。","未甘明聖日，終作釣漁翁。"]', '["散拙亦自遂，麤將猨鸟同。","飞泉高瀉月，独樹逈含风。","果落盤盂上，云生篋笥中。","未甘明聖日，終作釣漁翁。"]', '诗', 'shi', '', NULL, '山中 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b610d25-f37d-4ac4-ac2a-7b467aeab436', '路支使小池', '路支使小池', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["兒童戲穿鑿，咫尺見津涯。","蘚岸和纖草，松泉濺淺沙。","光含半牀月，影入一枝花。","到此無醒日，當時有習家。"]', '["兒童戲穿鑿，咫尺见津涯。","蘚岸和纖草，松泉濺淺沙。","光含半牀月，影入一枝花。","到此無醒日，當时有習家。"]', '诗', 'shi', '', NULL, '路支使小池 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00751342-bbcf-49ed-bf65-9959762a06be', '清源標公', '清源標公', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["師爲衆人重，始得衆人師。","年到白頭日，行如新戒時。","缾添放魚澗，窗逈褭猿枝。","此地堪終老，迷癡自不知。"]', '["師爲衆人重，始得衆人師。","年到白头日，行如新戒时。","缾添放鱼澗，窗逈褭猿枝。","此地堪終老，迷癡自不知。"]', '诗', 'shi', '', NULL, '清源標公 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('959dbe2a-b2da-4c33-b668-9df20b9af13c', '題雪竇禪師壁', '題雪竇禪師壁', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["飛泉濺禪石，缾注亦生苔。","海上山不淺，天邊人自來。","長年隨檜柏，獨夜任風雷。","獵者聞疎磬，知師入定迴。"]', '["飞泉濺禪石，缾注亦生苔。","海上山不淺，天邊人自来。","长年隨檜柏，独夜任风雷。","獵者闻疎磬，知師入定迴。"]', '诗', 'shi', '', NULL, '題雪竇禪師壁 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef9c43ce-c331-4ad0-a52a-da9d765271b0', '重寄金山寺僧', '重寄金山寺僧', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["風濤匝山寺，磬韻達漁船。","此處別師久，遠懷無信傳。","月華妨靜燭，鳥語答幽禪。","已見如如理，灰心應不然。"]', '["风濤匝山寺，磬韻達漁船。","此处別師久，远懷無信傳。","月华妨静燭，鸟語答幽禪。","已见如如理，灰心應不然。"]', '诗', 'shi', '', NULL, '重寄金山寺僧 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f3e181f-cc78-47e9-a3d1-a64fcf3b7eb3', '哭胡珪', '哭胡珪', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["才高登上第，孝極歿廬塋。","一命何無定，片言徒有聲。","故園花自發，新塚月初明。","寂寞重泉裏，豈知春物榮。"]', '["才高登上第，孝極歿廬塋。","一命何無定，片言徒有声。","故园花自發，新塚月初明。","寂寞重泉裏，豈知春物榮。"]', '诗', 'shi', '', NULL, '哭胡珪 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('430f8354-f18e-4ad5-bf56-48cb21a7df37', '與清溪趙明府', '與清溪趙明府', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["清規暫趨府，獨立與誰親。","遂性無非酒，求閑却愛貧。","林泉應入夢，印綬莫留人。","王事聞多暇，吟來幾首新。"]', '["清規暫趨府，独立與誰親。","遂性無非酒，求闲却愛貧。","林泉應入梦，印綬莫留人。","王事闻多暇，吟来幾首新。"]', '诗', 'shi', '', NULL, '與清溪趙明府 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0af0a74b-6ea4-4991-a64c-37f452e4105c', '送剡縣陳永秩滿歸越', '送剡縣陳永秩满归越', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["俸祿三年後，程途一月間。","舟中非客路，鏡裏是家山。","密雪霑行袂，離杯變別顏。","古人唯賀滿，今挈解由還。"]', '["俸祿三年後，程途一月间。","舟中非客路，镜裏是家山。","密雪霑行袂，離杯变別顏。","古人唯賀满，今挈解由還。"]', '诗', 'shi', '', NULL, '送剡縣陳永秩滿歸越 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae2b08be-ec91-4d23-8dbc-272e8b814f59', '示鄉叟', '示乡叟', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["暮齒甘衰謝，逢人惜別離。","青山前代業，老樹此身移。","買藥將衣盡，尋方見字遲。","如何鑷殘鬢，覽鏡變成絲。"]', '["暮齒甘衰謝，逢人惜別離。","青山前代業，老樹此身移。","買藥將衣尽，尋方见字遲。","如何鑷殘鬢，覽镜变成絲。"]', '诗', 'shi', '', NULL, '示鄉叟 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a23b415-da76-496d-a249-e827701da499', '遊竹林寺', '游竹林寺', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["得路到深寺，幽虛曾識名。","蘚濃陰砌古，煙起暮香生。","曙月落松翠，石泉流梵聲。","聞僧說真理，煩惱自然輕。"]', '["得路到深寺，幽虛曾識名。","蘚濃陰砌古，煙起暮香生。","曙月落松翠，石泉流梵声。","闻僧说真理，煩惱自然轻。"]', '诗', 'shi', '', NULL, '遊竹林寺 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd73391b-28e2-47d6-98c5-1f0dd512f531', '陸處士別業', '陸处士別業', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["問道遠相訪，無人覺路長。","夜深回釣檝，月影出書林。","蟬噪蓼花發，禽來山果香。","多時欲歸去，西望又斜陽。"]', '["问道远相訪，無人覺路长。","夜深回釣檝，月影出书林。","蟬噪蓼花發，禽来山果香。","多时欲归去，西望又斜陽。"]', '诗', 'shi', '', NULL, '陸處士別業 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2e63615-7b07-4e87-b53e-b02d641f8a6b', '贈中岳僧', '贈中岳僧', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["坐來藂木大，誰見入嵒年。","多病長留藥，無憂亦是禪。","搘牀移片石，舂粟引高泉。","盡願求心法，逢誰即擬傳。"]', '["坐来藂木大，誰见入嵒年。","多病长留藥，無憂亦是禪。","搘牀移片石，舂粟引高泉。","尽願求心法，逢誰即擬傳。"]', '诗', 'shi', '', NULL, '贈中岳僧 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2239a873-dbc7-45d7-a297-1d3aa0f2fe1e', '寄普州賈司倉島', '寄普州賈司倉島', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["亂山重復疊，何路訪先生。","豈料多才者，空垂不世名閑曹猶得醉，薄俸亦勝耕。","莫問吟詩石，年年芳草平。"]', '["亂山重复叠，何路訪先生。","豈料多才者，空垂不世名闲曹猶得醉，薄俸亦勝耕。","莫问吟诗石，年年芳草平。"]', '诗', 'shi', '', NULL, '寄普州賈司倉島 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('128f52c6-06a9-4066-b17e-a1c180217db8', '送鏡空上人遊江南', '送镜空上人游江南', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["去住如雲鶴，飄然不可留。","何山逢後夏，一食在孤舟。","細雨蓮塘晚，疎蟬橘岸秋。","應懷舊溪月，夜過石窗流。"]', '["去住如云鹤，飄然不可留。","何山逢後夏，一食在孤舟。","細雨蓮塘晚，疎蟬橘岸秋。","應懷旧溪月，夜過石窗流。"]', '诗', 'shi', '', NULL, '送鏡空上人遊江南 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64996b37-9d84-497c-9c25-ac280b138765', '新正', '新正', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["篳門惆悵內，時節暗來頻。","每見新正雪，長思故國春。","雲西斜去雁，江上未歸人。","又一年爲客，何媒得到秦。"]', '["篳门惆悵內，时節暗来頻。","每见新正雪，长思故国春。","云西斜去雁，江上未归人。","又一年爲客，何媒得到秦。"]', '诗', 'shi', '', NULL, '新正 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a3f5069-b98e-449b-a61c-59a1db20801c', '夜聽步虛', '夜听步虛', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["寂寂永宮裏，天師朝禮聲。","步虛聞一曲，渾欲到三清。","瑞草秋風起，仙堦夜月明。","多年遠塵意，此地欲鋪平。"]', '["寂寂永宮裏，天師朝禮声。","步虛闻一曲，渾欲到三清。","瑞草秋风起，仙堦夜月明。","多年远塵意，此地欲鋪平。"]', '诗', 'shi', '', NULL, '夜聽步虛 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c894ea12-d454-4e07-bb6b-1c9ceec478a4', '題碧溪山禪老', '題碧溪山禪老', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["師步有雲隨，師情唯鶴知。","蘿迷收{艹/朮}路，雪隔出溪時。","竹狖窺沙井，巖禽停檜枝。","由來傲卿相，臥穩答書遲。"]', '["師步有云隨，師情唯鹤知。","蘿迷收{艹/朮}路，雪隔出溪时。","竹狖窺沙井，巖禽停檜枝。","由来傲卿相，臥穩答书遲。"]', '诗', 'shi', '', NULL, '題碧溪山禪老 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e53c7dfa-6d87-4122-8cd6-261901a57ca6', '寒食宿先天寺無可上人房', '寒食宿先天寺無可上人房', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["雙扉檜下開，寄宿石房苔。","幡北燈花動，城西雪霰來。","收棊想雲夢，罷茗議天台。","同憶前年臘，師初白閣回。"]', '["雙扉檜下开，寄宿石房苔。","幡北灯花动，城西雪霰来。","收棊想云梦，罷茗議天台。","同憶前年臘，師初白閣回。"]', '诗', 'shi', '', NULL, '寒食宿先天寺無可上人房 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c943c10-ea7d-4271-aacc-d33a5b87ce6f', '中秋月', '中秋月', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["涼霄煙靄外，三五玉蟾秋。","列野星辰正，當空鬼魅愁。","泉澄寒魄瑩，露滴冷光浮。","未折青青桂，吟看不忍休。"]', '["涼霄煙靄外，三五玉蟾秋。","列野星辰正，當空鬼魅愁。","泉澄寒魄瑩，露滴冷光浮。","未折青青桂，吟看不忍休。"]', '诗', 'shi', '', NULL, '中秋月 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('582a27dc-0a99-47d2-a859-8a9b95bb7a42', '暮冬書懷呈友人', '暮冬书懷呈友人', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["空爲梁甫吟，誰竟是知音。","風雪生寒夜，鄉園來舊心。","滄江孤棹逈，白閣一鐘深。","君子久忘我，此懷甘自沈。"]', '["空爲梁甫吟，誰竟是知音。","风雪生寒夜，乡园来旧心。","滄江孤棹逈，白閣一鐘深。","君子久忘我，此懷甘自沈。"]', '诗', 'shi', '', NULL, '暮冬書懷呈友人 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4d0cc8b-cb2e-412d-a446-a176ffffe758', '贈江南僧', '贈江南僧', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["忘機室亦空，禪與沃州同。","唯有半庭竹，能生竟日風。","思山海月上，出定印香終。","繼後傳衣者，還須立雪中。"]', '["忘機室亦空，禪與沃州同。","唯有半庭竹，能生竟日风。","思山海月上，出定印香終。","繼後傳衣者，還須立雪中。"]', '诗', 'shi', '', NULL, '贈江南僧 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef0dace3-e56c-4647-8c04-778b3ec84416', '柳', '柳', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["搖曳惹風吹，臨堤軟勝絲。","態濃誰爲識，力弱自難持。","學舞枝翻袖，呈妝葉展眉。","如何一攀折，懷友又題詩。"]', '["搖曳惹风吹，臨堤軟勝絲。","態濃誰爲識，力弱自难持。","学舞枝翻袖，呈妝葉展眉。","如何一攀折，懷友又題诗。"]', '诗', 'shi', '', NULL, '柳 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67cfb00b-b7fb-4f48-824c-e942a27a8bfc', '送姚合員外赴金州', '送姚合員外赴金州', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["受詔從華省，開旗發帝州。","野煙新驛曙，殘照古山秋。","樹勢連巴沒，江聲入楚流。","唯應化行後，吟句上閑樓。"]', '["受詔從华省，开旗發帝州。","野煙新驛曙，殘照古山秋。","樹勢連巴沒，江声入楚流。","唯應化行後，吟句上闲楼。"]', '诗', 'shi', '', NULL, '送姚合員外赴金州 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3766d1a6-b5d4-4f74-ba93-c9fa0a497af1', '送江陰霍明府之任', '送江陰霍明府之任', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["遙遙去舸新，浸郭葦兼蘋。","樹列巢灘鶴，鄉多釣浦人。","虹分陽羨雨，浪隔廣陵春。","知竟三年秩，琴書外是貧。"]', '["遙遙去舸新，浸郭葦兼蘋。","樹列巢灘鹤，乡多釣浦人。","虹分陽羨雨，浪隔廣陵春。","知竟三年秩，琴书外是貧。"]', '诗', 'shi', '', NULL, '送江陰霍明府之任 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a3a597e-db3d-40a3-8927-47550775edf8', '送友及第歸淛東', '送友及第归淛东', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["南行無俗侶，秋雁與寒雲。","野趣自多愜，鄉名人共聞。","吳山中路斷，淛水半江分。","此地登臨慣，攄情一送君。"]', '["南行無俗侶，秋雁與寒云。","野趣自多愜，乡名人共闻。","吳山中路斷，淛水半江分。","此地登臨慣，攄情一送君。"]', '诗', 'shi', '', NULL, '送友及第歸淛東 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c626fcd6-22e5-4865-9a8e-1470243c9386', '山中即事', '山中即事', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["趍世非身事，山中適性情。","野花多異色，幽鳥少凡聲。","樹影搜涼臥，苔光破碧行。","閑尋採藥處，仙路漸分明。"]', '["趍世非身事，山中適性情。","野花多異色，幽鸟少凡声。","樹影搜涼臥，苔光破碧行。","闲尋採藥处，仙路漸分明。"]', '诗', 'shi', '', NULL, '山中即事 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c2723ad-321e-4af7-9aa1-d252731e0d50', '過黃州作', '過黄州作', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["弭節齊安郡，孤城百戰殘。","傍村林有虎，帶郭縣無官。","暮角梅花怨，清江桂影寒。","黍離緣底事，撩我起長歎。"]', '["弭節齊安郡，孤城百戰殘。","傍村林有虎，带郭縣無官。","暮角梅花怨，清江桂影寒。","黍離緣底事，撩我起长歎。"]', '诗', 'shi', '', NULL, '過黃州作 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74a6951a-81f5-427a-b059-be5ad4f56372', '元日', '元日', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["晨雞兩遍報更闌，刁斗無聲曉漏乾。","暖日映山調正氣，東風入樹舞殘寒。","軒車欲識人間感，獻歲須來帝里看。","纔酌屠蘇定年齒，坐中惟笑鬢毛斑。"]', '["晨雞兩遍報更闌，刁斗無声晓漏乾。","暖日映山調正氣，东风入樹舞殘寒。","軒车欲識人间感，獻歲須来帝里看。","纔酌屠蘇定年齒，坐中惟笑鬢毛斑。"]', '诗', 'shi', '', NULL, '元日 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88d93546-b84b-4852-9106-4aa36a944fe0', '別從兄郜', '別從兄郜', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["展翅開帆秪待風，吹噓成事古今同。","已呼斷雁歸行裏，全勝枯鱗在轍中。","若許死前恩少報，終期言下命潛通。","臨岐再拜無餘事，願取文章達聖聰。"]', '["展翅开帆秪待风，吹噓成事古今同。","已呼斷雁归行裏，全勝枯鱗在轍中。","若許死前恩少報，終期言下命潛通。","臨岐再拜無餘事，願取文章達聖聰。"]', '诗', 'shi', '', NULL, '別從兄郜 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('049d78d9-0440-4e3a-9e8c-03351c35c1ec', '寄江陵王少府', '寄江陵王少府', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["分手頻曾變寒暑，迢迢遠意各何如。","波濤一阻兩鄉夢，歲月無過雙鯉魚。","吟處落花藏筆硯，睡時斜雨濕圖書。","此來俗輩皆疎我，唯有故人心不疎。"]', '["分手頻曾变寒暑，迢迢远意各何如。","波濤一阻兩乡梦，歲月無過雙鯉鱼。","吟处落花藏笔硯，睡时斜雨濕圖书。","此来俗輩皆疎我，唯有故人心不疎。"]', '诗', 'shi', '', NULL, '寄江陵王少府 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efec4dcb-35ba-4a3b-8937-15b9cc95f65e', '題睦州烏龍山禪居', '題睦州烏龙山禪居', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["曙後月華猶冷濕，自知坐臥逼天宮。","晨雞未暇鳴山底，早日先來照屋東。","人世驅馳方丈內，海波搖動一杯中。","伴師長住應難住，歸去仍須入俗籠。"]', '["曙後月华猶冷濕，自知坐臥逼天宮。","晨雞未暇鳴山底，早日先来照屋东。","人世驱驰方丈內，海波搖动一杯中。","伴師长住應难住，归去仍須入俗籠。"]', '诗', 'shi', '', NULL, '題睦州烏龍山禪居 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f6a63fc-dea5-420a-98cd-e68f033e6ed3', '寄杭州于郎中', '寄杭州于郎中', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["雖云聖代識賢明，自是山河應數生。","大雅篇章無弟子，高門世業有公卿。","入樓早月中秋色，遶郭寒潮半夜聲。","白屋青雲至懸闊，愚儒肝膽若爲傾。"]', '["雖云聖代識賢明，自是山河應數生。","大雅篇章無弟子，高门世業有公卿。","入楼早月中秋色，遶郭寒潮半夜声。","白屋青云至懸闊，愚儒肝膽若爲傾。"]', '诗', 'shi', '', NULL, '寄杭州于郎中 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e9821fd-2707-408c-a964-9f4a962bf4a9', '寄靈武胡常侍', '寄靈武胡常侍', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["青雲直上路初通，已在明君倚注中。","欲遣爲霖安九有，先令作相贊東宮。","自從忠讜承天睠，更用文篇續國風。","最是何人感恩德，謝敷星下釣漁翁。"]', '["青云直上路初通，已在明君倚注中。","欲遣爲霖安九有，先令作相贊东宮。","自從忠讜承天睠，更用文篇續国风。","最是何人感恩德，謝敷星下釣漁翁。"]', '诗', 'shi', '', NULL, '寄靈武胡常侍 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5eae777f-8dcc-4fbf-8a7e-a49c98f91eba', '上張舍人', '上張舍人', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["海內芳聲誰可竝，承家三代相門深。","剖符已副東人望，援筆曾傳聖主心。","此地清廉惟飲水，四方焦熱待爲霖。","他年莫學鴟夷子，遠泛扁舟用鑄金。"]', '["海內芳声誰可竝，承家三代相门深。","剖符已副东人望，援笔曾傳聖主心。","此地清廉惟饮水，四方焦熱待爲霖。","他年莫学鴟夷子，远泛扁舟用鑄金。"]', '诗', 'shi', '', NULL, '上張舍人 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6fc0aae-c655-4432-9a0e-98a4aa985c3d', '題慈溪張丞壁', '題慈溪張丞壁', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["因君貳邑藍溪上，遣我維舟紅葉時。","共向鄉中非半面，俱驚鬢裏有新絲。","竚看孤潔成三考，應笑愚疎捨一枝。","貌似故人心尚喜，相逢況是舊相知。"]', '["因君貳邑藍溪上，遣我維舟紅葉时。","共向乡中非半面，俱驚鬢裏有新絲。","竚看孤潔成三考，應笑愚疎捨一枝。","貌似故人心尚喜，相逢況是旧相知。"]', '诗', 'shi', '', NULL, '題慈溪張丞壁 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e022ea6-7a91-4af3-aac0-e25f22f753d9', '贈鄰居袁明府', '贈鄰居袁明府', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["隔竹每呼皆得應，二心親熟更如何。","文章鍛鍊猶相似，年齒參差不校多。","雨後卷簾看越嶺，更深欹枕聽湖波。","朝昏幸得同醒醉，遮莫光陰自下坡。"]', '["隔竹每呼皆得應，二心親熟更如何。","文章鍛鍊猶相似，年齒參差不校多。","雨後卷簾看越嶺，更深欹枕听湖波。","朝昏幸得同醒醉，遮莫光陰自下坡。"]', '诗', 'shi', '', NULL, '贈鄰居袁明府 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6ea1d13-938a-4f3e-a1a2-55207b23d391', '孫氏林亭', '孫氏林亭', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["池亭纔有二三畝，風景勝於千萬家。","瑟瑟林排全巷竹，猩猩血染半園花。","竝牀欹枕逢春盡，援筆持杯到日斜。","丱角相知成白首，而今歡笑莫咨嗟。"]', '["池亭纔有二三畝，风景勝於千万家。","瑟瑟林排全巷竹，猩猩血染半园花。","竝牀欹枕逢春尽，援笔持杯到日斜。","丱角相知成白首，而今歡笑莫咨嗟。"]', '诗', 'shi', '', NULL, '孫氏林亭 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd89828b-ef35-48f0-898d-c944feb0a50e', '漳州陽亭言事寄于使君', '漳州陽亭言事寄于使君', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["謝守登城對遠峰，金英泛泛滿金鍾。","樓頭風景八九月，牀下水雲千萬重。","紅斾朝昏雖許近，清才今古定難逢。","鯉魚縱是凡鱗鬣，得在膺門合作龍。"]', '["謝守登城对远峰，金英泛泛满金鍾。","楼头风景八九月，牀下水云千万重。","紅斾朝昏雖許近，清才今古定难逢。","鯉鱼縱是凡鱗鬣，得在膺门合作龙。"]', '诗', 'shi', '', NULL, '漳州陽亭言事寄于使君 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53d6b63f-37b6-45d6-a01f-ae1128cd5770', '別胡中丞', '別胡中丞', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["二年朝夜見雙旌，心魄知恩夢亦驚。","幽賤麤能分菽麥，從容豈合遇公卿。","吹噓若自毫端出，羽翼應從肉上生。","却恨此身唯一死，空將一死報猶輕。"]', '["二年朝夜见雙旌，心魄知恩梦亦驚。","幽賤麤能分菽麦，從容豈合遇公卿。","吹噓若自毫端出，羽翼應從肉上生。","却恨此身唯一死，空將一死報猶轻。"]', '诗', 'shi', '', NULL, '別胡中丞 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e0380b1-949f-495a-b793-965c5590f4fb', '遊張公洞寄陶校書', '游張公洞寄陶校书', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["步步勢穿江底去，此中危滑轉身難。","下蒸陰氣松蘿濕，外制溫風杖屨寒。","數里煙雲方覺異，前程世界更應寬。","由來委曲尋仙路，不似先生換骨丹。"]', '["步步勢穿江底去，此中危滑轉身难。","下蒸陰氣松蘿濕，外制溫风杖屨寒。","數里煙云方覺異，前程世界更應寬。","由来委曲尋仙路，不似先生換骨丹。"]', '诗', 'shi', '', NULL, '遊張公洞寄陶校書 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad92e00b-71d8-4b50-9730-e8c57b455288', '題睦州郡中千峰榭', '題睦州郡中千峰榭', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["豈知平地似天台，朱戶深沈別徑開。","曳響露蟬穿樹去，斜行沙鳥向池來。","窗中早月當琴榻，墻上秋山入酒杯。","何事此中如世外，應緣羊祜是仙才。"]', '["豈知平地似天台，朱戶深沈別徑开。","曳响露蟬穿樹去，斜行沙鸟向池来。","窗中早月當琴榻，墻上秋山入酒杯。","何事此中如世外，應緣羊祜是仙才。"]', '诗', 'shi', '', NULL, '題睦州郡中千峰榭 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b83f6e50-25f4-4bc8-bce6-5c156c0a6024', '登新城縣樓贈蔡明府', '登新城縣楼贈蔡明府', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["楊震東來是宦遊，政成登此自消憂。","草中白道穿村去，樹裏清溪照郭流。","縱目四山宜永日，開襟五月似高秋。","不知縣籍添新戶，但見川原桑柘稠。"]', '["楊震东来是宦游，政成登此自消憂。","草中白道穿村去，樹裏清溪照郭流。","縱目四山宜永日，开襟五月似高秋。","不知縣籍添新戶，但见川原桑柘稠。"]', '诗', 'shi', '', NULL, '登新城縣樓贈蔡明府 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7fc9e84-5406-414d-b84e-d6cfeaf18d2f', '和于中丞登扶風亭', '和于中丞登扶风亭', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["避石攀蘿去不迷，行時舉步似丹梯。","東軒海日已先照，下界晨雞猶未啼。","郭裏雲山全占寺，村前竹樹半藏溪。","謝公吟望多來此，此地應將峴首齊。"]', '["避石攀蘿去不迷，行时舉步似丹梯。","东軒海日已先照，下界晨雞猶未啼。","郭裏云山全占寺，村前竹樹半藏溪。","謝公吟望多来此，此地應將峴首齊。"]', '诗', 'shi', '', NULL, '和于中丞登扶風亭 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23890fc3-a94b-4440-858e-a0e4359cbc09', '贈信州高員外', '贈信州高員外', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["溪勢盤回繞郡流，饒陽春色滿溪樓。","豈唯啼鳥催人醉，更有繁花笑客愁。","蹇拙命中迷直道，仁慈風裏駐扁舟。","膺門若感深恩去，終殺微軀未足酬。"]', '["溪勢盤回繞郡流，饒陽春色满溪楼。","豈唯啼鸟催人醉，更有繁花笑客愁。","蹇拙命中迷直道，仁慈风裏駐扁舟。","膺门若感深恩去，終殺微軀未足酬。"]', '诗', 'shi', '', NULL, '贈信州高員外 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97ffa4ab-cabb-4bc5-804a-d51ea5afdfc5', '漳州于使君罷郡如之任漳南去上國二十四州使君無非親故', '漳州于使君罷郡如之任漳南去上国二十四州使君無非親故', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["漳南罷郡如之任，二十四州相次迎。","泊岸旗幡郵吏拜，連山風雨探人行。","月中倚棹吟漁浦，花底垂鞭醉鳳城。"]', '["漳南罷郡如之任，二十四州相次迎。","泊岸旗幡郵吏拜，連山风雨探人行。","月中倚棹吟漁浦，花底垂鞭醉鳳城。"]', '诗', 'shi', '', NULL, '漳州于使君罷郡如之任漳南去上國二十四州使君無非親故 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdec4fa2-f3a0-4ff0-a2e7-df910aa4d5f8', '送弟子伍秀才赴舉', '送弟子伍秀才赴舉', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["天遣相門延積慶，今同太廟薦嘉賓。","柳條此日同誰折，桂樹明年爲爾春。","倚棹寒吟漁浦月，垂鞭醉入鳳城塵。","由來不要文章得，要且文章出衆人。"]', '["天遣相门延積慶，今同太廟薦嘉賓。","柳條此日同誰折，桂樹明年爲爾春。","倚棹寒吟漁浦月，垂鞭醉入鳳城塵。","由来不要文章得，要且文章出衆人。"]', '诗', 'shi', '', NULL, '送弟子伍秀才赴舉 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed461f61-6556-44c0-a5ef-5495da32eeec', '貽高讜', '貽高讜', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["都緣相府有宗兄，却恐妨君正路行。","石上長松自森秀，雪中孤玉更凝明。","西陵曉月中秋色，北固軍鼙半夜聲。","幸有清才與洪筆，何愁高節不公卿。"]', '["都緣相府有宗兄，却恐妨君正路行。","石上长松自森秀，雪中孤玉更凝明。","西陵晓月中秋色，北固軍鼙半夜声。","幸有清才與洪笔，何愁高節不公卿。"]', '诗', 'shi', '', NULL, '貽高讜 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b730dd33-0194-4192-ba53-6fd2400e3ad8', '題長洲陳明府小亭', '題长洲陳明府小亭', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["坐看孤峭却勞神，還是微吟到日曛。","松鶴認名呼得下，沙蟬飛處聽猶聞。","夜闌亦似深山月，雨後唯關滿屋雲。","便此逍遙應不易，朱衣紅斾未容君。"]', '["坐看孤峭却勞神，還是微吟到日曛。","松鹤認名呼得下，沙蟬飞处听猶闻。","夜闌亦似深山月，雨後唯关满屋云。","便此逍遙應不易，朱衣紅斾未容君。"]', '诗', 'shi', '', NULL, '題長洲陳明府小亭 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('beb07467-6eed-45ec-bc9d-d7d5b25d3786', '送朱二十赴漣水', '送朱二十赴漣水', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["到縣却應嫌水闊，離家終是見山疎。","笙歌不駐難辭酒，舟檝將行負擔書。","爲政必能安楚老，向公猶可釣淮魚。","鸞凰取便多如此，掠地斜飛上太虛。"]', '["到縣却應嫌水闊，離家終是见山疎。","笙歌不駐难辞酒，舟檝將行負擔书。","爲政必能安楚老，向公猶可釣淮鱼。","鸾凰取便多如此，掠地斜飞上太虛。"]', '诗', 'shi', '', NULL, '送朱二十赴漣水 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51229c91-cca0-47c8-a852-df998ee7bc06', '德政上睦州胡中丞', '德政上睦州胡中丞', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["上德由來合動天，旌旗到日是豐年。","羣書已熟無人似，五字研成舉世傳。","莫道政聲同宇宙，須知紫氣滿山川。","豈唯里巷皆蘇息，猶有恩波及釣船。"]', '["上德由来合动天，旌旗到日是豐年。","羣书已熟無人似，五字研成舉世傳。","莫道政声同宇宙，須知紫氣满山川。","豈唯里巷皆蘇息，猶有恩波及釣船。"]', '诗', 'shi', '', NULL, '德政上睦州胡中丞 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34a43b74-4edd-44bb-ae10-2f9e13dc7730', '袁明府以家醖寄余余以山梅答贈非唯四韻兼亦雙關', '袁明府以家醖寄余余以山梅答贈非唯四韻兼亦雙关', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["封匏寄酒提攜遠，織籠盛梅答贈遲。","九度攪和誰用法，四邊窺摘自攀枝。","罇罍泛蟻堪嘗日，童稚驅禽欲熟時。","畢卓醉狂潘氏少，傾來擲去恰相宜。"]', '["封匏寄酒提携远，织籠盛梅答贈遲。","九度攪和誰用法，四邊窺摘自攀枝。","罇罍泛蟻堪嘗日，童稚驱禽欲熟时。","畢卓醉狂潘氏少，傾来擲去恰相宜。"]', '诗', 'shi', '', NULL, '袁明府以家醖寄余余以山梅答贈非唯四韻兼亦雙關 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85ae6a7f-804d-4e56-9530-46037811b29d', '上杭州姚郎中', '上杭州姚郎中', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["能除疾瘼似良醫，一郡鄉風當日移。","身貴久離行藥伴，才高獨作後人師。","春遊下馬皆成醼，吏散看山即有詩。","借問公方與文道，而今中夏更傳誰。"]', '["能除疾瘼似良醫，一郡乡风當日移。","身貴久離行藥伴，才高独作後人師。","春游下马皆成醼，吏散看山即有诗。","借问公方與文道，而今中夏更傳誰。"]', '诗', 'shi', '', NULL, '上杭州姚郎中 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d9229ab-880d-442a-bb15-0f3766fdbefa', '送葉秀才赴舉兼呈呂少監', '送葉秀才赴舉兼呈呂少監', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["君辭舊里一年期，藝至心身亦自知。","尊盡離人看北斗，月寒驚鵲繞南枝。","書迴冊市砧應絕，棹出村潭菊未衰。","與爾相逢終不遠，昨聞秘監在台墀。"]', '["君辞旧里一年期，藝至心身亦自知。","尊尽離人看北斗，月寒驚鵲繞南枝。","书迴冊市砧應絕，棹出村潭菊未衰。","與爾相逢終不远，昨闻秘監在台墀。"]', '诗', 'shi', '', NULL, '送葉秀才赴舉兼呈呂少監 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3aaf758-19a6-407d-b2e8-37be27d5c577', '自縉雲赴郡溪流百里輕棹一發曾不崇朝敘事四韻寄獻段郎中', '自縉云赴郡溪流百里轻棹一發曾不崇朝敘事四韻寄獻段郎中', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["激箭溪湍勢莫憑，飄然一葉若爲乘。","仰瞻青壁開天罅，斗轉寒灣避石稜。","巢鳥夜驚離島樹，啼猿晝怯下巖藤。","此中明日尋知己，恐似龍門不易登。"]', '["激箭溪湍勢莫憑，飄然一葉若爲乘。","仰瞻青壁开天罅，斗轉寒灣避石稜。","巢鸟夜驚離島樹，啼猿晝怯下巖藤。","此中明日尋知己，恐似龙门不易登。"]', '诗', 'shi', '', NULL, '自縉雲赴郡溪流百里輕棹一發曾不崇朝敘事四韻寄獻段郎中 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65a418eb-3ed3-4581-8772-7c5d32023d24', '胡中丞早梅', '胡中丞早梅', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["不獨閑花不共時，一株寒豔尚參差。","凌晨未噴含霜朵，應候先開亞水枝。","芬郁合將蘭竝茂，凝明應與雪相宜。","謝公吟賞愁飄落，可得更拈長笛吹。"]', '["不独闲花不共时，一株寒豔尚參差。","凌晨未噴含霜朵，應候先开亞水枝。","芬郁合將蘭竝茂，凝明應與雪相宜。","謝公吟賞愁飄落，可得更拈长笛吹。"]', '诗', 'shi', '', NULL, '胡中丞早梅 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f175f8d-0a34-47c7-aaf5-6851c06cac2a', '牡丹', '牡丹', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["借問庭芳早晚栽，座中疑展畫屏開。","花分淺淺臙脂臉，葉墮殷殷膩粉腮。","紅砌不須誇芍藥，白蘋何用逞重臺。","慇懃爲報看花客，莫學遊蜂日日來。"]', '["借问庭芳早晚栽，座中疑展畫屏开。","花分淺淺臙脂臉，葉墮殷殷膩粉腮。","紅砌不須誇芍藥，白蘋何用逞重台。","慇懃爲報看花客，莫学游蜂日日来。"]', '诗', 'shi', '', NULL, '牡丹 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f535e3b-37eb-4733-9014-658a90e965c4', '觀項信水墨', '观項信水墨', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["險峭雖從筆下成，精能皆自意中生。","倚雲孤檜知無朽，挂壁高泉似有聲。","轉扇驚波連岸動，迴燈落日向山明。","小年師祖過今祖，異域應傳項信名。"]', '["險峭雖從笔下成，精能皆自意中生。","倚云孤檜知無朽，挂壁高泉似有声。","轉扇驚波連岸动，迴灯落日向山明。","小年師祖過今祖，異域應傳項信名。"]', '诗', 'shi', '', NULL, '觀項信水墨 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4af061fd-f83e-4f62-954c-0c43a1a52d40', '書桃花塢周處士壁', '书桃花塢周处士壁', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["醉吟雪月思深苦，思苦神勞華髪生。","自學古賢修靜節，唯應野鶴識高情。","細泉出石飛難盡，孤燭和雲濕不明。","何事嬾於嵇叔夜，更無書札答公卿。"]', '["醉吟雪月思深苦，思苦神勞华髪生。","自学古賢修静節，唯應野鹤識高情。","細泉出石飞难尽，孤燭和云濕不明。","何事嬾於嵇叔夜，更無书札答公卿。"]', '诗', 'shi', '', NULL, '書桃花塢周處士壁 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ef6063d-a846-408a-8bd0-03b414728b00', '題桐廬謝逸人江居', '題桐廬謝逸人江居', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["少小高眠無一事，五侯勳盛欲如何。","湖邊倚仗寒吟苦，石上橫琴夜醉多。","鳥自樹梢隨果落，人從窗外卸帆過。","由來朝市爲真隱，可要棲身向薜蘿。"]', '["少小高眠無一事，五侯勳盛欲如何。","湖邊倚仗寒吟苦，石上橫琴夜醉多。","鸟自樹梢隨果落，人從窗外卸帆過。","由来朝市爲真隐，可要棲身向薜蘿。"]', '诗', 'shi', '', NULL, '題桐廬謝逸人江居 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bd00edd-4bb4-4361-91ec-5d936ba754eb', '敘雪寄喻鳧', '敘雪寄喻鳧', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["密片無聲急復遲，紛紛猶勝落花時。","從容不覺藏苔逕，宛轉偏宜傍柳絲。","透室虛明非月照，滿空迴散是風吹。","高人坐臥才方逸，援筆應成六出詞。"]', '["密片無声急复遲，紛紛猶勝落花时。","從容不覺藏苔逕，宛轉偏宜傍柳絲。","透室虛明非月照，满空迴散是风吹。","高人坐臥才方逸，援笔應成六出词。"]', '诗', 'shi', '', NULL, '敘雪寄喻鳧 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0013efd8-546f-4eaa-8152-876fbad71de5', '又敘雪寄喻鳧', '又敘雪寄喻鳧', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["密片繁聲旋不銷，縈風雜霰轉飄颻。","澄江莫蔽長流色，衰柳難黏自動條。","濕氣添寒酤酒夜，素花迎曙卷簾朝。","此時明逕無行跡，唯望徽之問寂寥。"]', '["密片繁声旋不銷，縈风杂霰轉飄颻。","澄江莫蔽长流色，衰柳难黏自动條。","濕氣添寒酤酒夜，素花迎曙卷簾朝。","此时明逕無行跡，唯望徽之问寂寥。"]', '诗', 'shi', '', NULL, '又敘雪寄喻鳧 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('580d7c16-f26c-4682-b843-92dc7227880d', '哭秘書姚少監', '哭秘书姚少監', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["寒空此夜落文星，星落文留萬古名。","入室幾人成弟子，爲儒是處哭先生。","家無諫草逢明代，國有遺篇續正聲。","曉向平原陳葬禮，悲風吹雨濕銘旌。"]', '["寒空此夜落文星，星落文留万古名。","入室幾人成弟子，爲儒是处哭先生。","家無諫草逢明代，国有遺篇續正声。","晓向平原陳葬禮，悲风吹雨濕銘旌。"]', '诗', 'shi', '', NULL, '哭秘書姚少監 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55c08e91-b311-45bc-b944-4fb7d5edbe43', '送人宰永泰', '送人宰永泰', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["北人雖泛南流水，稱意南行莫恨賒。","道路先經毛竹嶺，風煙漸近刺桐花。","舟停漁浦猶爲客，縣入樵溪似到家。","下馬政聲王事少，應容閑吏日高衙。"]', '["北人雖泛南流水，稱意南行莫恨賒。","道路先經毛竹嶺，风煙漸近刺桐花。","舟停漁浦猶爲客，縣入樵溪似到家。","下马政声王事少，應容闲吏日高衙。"]', '诗', 'shi', '', NULL, '送人宰永泰 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49a003d9-bac0-4745-9dc2-58fb0c2fb266', '旅次洋州寓居郝氏林亭', '旅次洋州寓居郝氏林亭', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["舉目縱然非我有，思量似在故山時。","鶴盤遠勢投孤嶼，蟬曳殘聲過別枝。","涼月照窗欹枕倦，澄泉遶石泛觴遲。","青雲未得平行去，夢到江南身旅羇。"]', '["舉目縱然非我有，思量似在故山时。","鹤盤远勢投孤嶼，蟬曳殘声過別枝。","涼月照窗欹枕倦，澄泉遶石泛觴遲。","青云未得平行去，梦到江南身旅羇。"]', '诗', 'shi', '', NULL, '旅次洋州寓居郝氏林亭 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d14107ed-9502-4b0e-ab11-ffa35978b7a9', '茅山贈洪拾遺', '茅山贈洪拾遺', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["聖代諫臣停諫舌，求歸故里傲雲霞。","溪頭講樹纜漁艇，篋裏朝衣輸酒家。","但愛身閑辭祿俸，那嫌歲計在桑麻。","我來幸與諸生異，問答時容近絳紗。"]', '["聖代諫臣停諫舌，求归故里傲云霞。","溪头講樹纜漁艇，篋裏朝衣輸酒家。","但愛身闲辞祿俸，那嫌歲計在桑麻。","我来幸與諸生異，问答时容近絳紗。"]', '诗', 'shi', '', NULL, '茅山贈洪拾遺 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e5d4e6e-dd62-4def-8857-9a7a1bf525e6', '睦州呂郎中郡中環溪亭', '睦州呂郎中郡中环溪亭', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["爲是仙才登望處，風光便似武陵春。","閑花半落猶迷蝶，白鳥雙飛不避人。","樹影興餘侵枕簟，荷香坐久著衣巾。","暫來此地非多日，明主那容借寇恂。"]', '["爲是仙才登望处，风光便似武陵春。","闲花半落猶迷蝶，白鸟雙飞不避人。","樹影兴餘侵枕簟，荷香坐久著衣巾。","暫来此地非多日，明主那容借寇恂。"]', '诗', 'shi', '', NULL, '睦州呂郎中郡中環溪亭 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('698985e5-f06c-4ea2-af3e-599b9e7ca958', '贈華陰隱者', '贈华陰隐者', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["少微夜夜當仙掌，更有何人在此居。","花月舊應看浴鶴，松蘿本自伴刪書。","素琴醉去經宵枕，衰髪寒來向日梳。","故國多年歸未遂，因逢此地憶君廬。"]', '["少微夜夜當仙掌，更有何人在此居。","花月旧應看浴鹤，松蘿本自伴刪书。","素琴醉去經宵枕，衰髪寒来向日梳。","故国多年归未遂，因逢此地憶君廬。"]', '诗', 'shi', '', NULL, '贈華陰隱者 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e4e4ba5-3431-47b0-ae7f-cf18fb9b02a3', '上杭州杜中丞', '上杭州杜中丞', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["昔用雄才登上第，今將重德合明君。","苦心多爲安民術，援筆皆成出世文。","寒角細吹孤嶠月，秋濤橫卷半江雲。","掠天逸勢應非久，一鶚那棲衆鳥羣。"]', '["昔用雄才登上第，今將重德合明君。","苦心多爲安民術，援笔皆成出世文。","寒角細吹孤嶠月，秋濤橫卷半江云。","掠天逸勢應非久，一鶚那棲衆鸟羣。"]', '诗', 'shi', '', NULL, '上杭州杜中丞 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d049c01-a2b0-4d7e-bda5-6fa098dd100f', '贈處州段郎中', '贈处州段郎中', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["幸見仙才領郡初，郡城孤峭似仙居。","杉蘿色裏遊亭榭，瀑布聲中閱簿書。","德重自將天子合，情高元與世人疎。","寒潭是處清連底，賓席何心望食魚。"]', '["幸见仙才領郡初，郡城孤峭似仙居。","杉蘿色裏游亭榭，瀑布声中閱簿书。","德重自將天子合，情高元與世人疎。","寒潭是处清連底，賓席何心望食鱼。"]', '诗', 'shi', '', NULL, '贈處州段郎中 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf0fab86-68e7-439a-a314-53db63afebe6', '書法華寺上方禪壁', '书法华寺上方禪壁', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["砌下松巔有鶴棲，孤猿亦在鶴邊啼。","臥聞雷雨歸巖早，坐見星辰去地低。","一逕穿緣應就郭，千花掩映似無溪。","是非生死多憂惱，此日蒙師爲破迷。"]', '["砌下松巔有鹤棲，孤猿亦在鹤邊啼。","臥闻雷雨归巖早，坐见星辰去地低。","一逕穿緣應就郭，千花掩映似無溪。","是非生死多憂惱，此日蒙師爲破迷。"]', '诗', 'shi', '', NULL, '書法華寺上方禪壁 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64f0f921-339b-4608-9b43-830a0b49f218', '書吳道隱林亭', '书吳道隐林亭', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["蘚榭莎亭蘿篠陰，依稀氣象似山林。","橘枝亞路黃苞重，井脈牽湖碧甃深。","稚子遮門留熟客，驚蟬入座避遊禽。","四鄰不見孤高處，翻笑騰騰只醉吟。"]', '["蘚榭莎亭蘿篠陰，依稀氣象似山林。","橘枝亞路黄苞重，井脈牽湖碧甃深。","稚子遮门留熟客，驚蟬入座避游禽。","四鄰不见孤高处，翻笑腾腾只醉吟。"]', '诗', 'shi', '', NULL, '書吳道隱林亭 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0b41f5a-e7c8-48c7-bf5d-9ec3c8d713d9', '陪王大夫泛湖', '陪王大夫泛湖', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["去去凌晨迴見星，木蘭舟穩畫橈輕。","白波潭上魚龍氣，紅樹林中雞犬聲。","蜜炬燒殘銀漢昃，羽觴飛急玉山傾。","此時檢點諸名士，却是漁翁無姓名。"]', '["去去凌晨迴见星，木蘭舟穩畫橈轻。","白波潭上鱼龙氣，紅樹林中雞犬声。","蜜炬燒殘銀漢昃，羽觴飞急玉山傾。","此时檢点諸名士，却是漁翁無姓名。"]', '诗', 'shi', '', NULL, '陪王大夫泛湖 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11bba374-5127-4853-9eae-e243cb86d54d', '贈會稽張少府', '贈會稽張少府', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["高節何曾似任官，藥苗香潔備常餐。","一分酒戶添猶得，五字詩名隱即難。","笑我無媒生鶴髪，知君有意憶漁竿。","明年莫便還家去，鏡裏雲山且共看。"]', '["高節何曾似任官，藥苗香潔備常餐。","一分酒戶添猶得，五字诗名隐即难。","笑我無媒生鹤髪，知君有意憶漁竿。","明年莫便還家去，镜裏云山且共看。"]', '诗', 'shi', '', NULL, '贈會稽張少府 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dad56060-a0a2-4084-8b52-d172fd264080', '送鄭台處士歸絳巖', '送鄭台处士归絳巖', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["榮啓先生挾琴去，厭尋靈勝憶巖栖。","白猿垂樹窗邊月，紅鯉驚鉤竹外溪。","慣採藥苗供野饌，曾書蕉葉寄新題。","古賢猶愴河梁別，未可怱怱便解攜。"]', '["榮啓先生挾琴去，厭尋靈勝憶巖栖。","白猿垂樹窗邊月，紅鯉驚鉤竹外溪。","慣採藥苗供野饌，曾书蕉葉寄新題。","古賢猶愴河梁別，未可怱怱便解携。"]', '诗', 'shi', '', NULL, '送鄭台處士歸絳巖 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de86f00f-9cb8-416f-bfd8-1587f7a44a8f', '因話天台勝異仍送羅道士', '因話天台勝異仍送羅道士', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["積翠千層一徑開，遙盤山腹到瓊臺。","藕花飄落前巖去，桂子流從別洞來。","石上叢林礙星斗，窗邊瀑布走風雷。","縱云孤鶴無留滯，定恐煙蘿不放迴。"]', '["積翠千層一徑开，遙盤山腹到瓊台。","藕花飄落前巖去，桂子流從別洞来。","石上叢林礙星斗，窗邊瀑布走风雷。","縱云孤鹤無留滯，定恐煙蘿不放迴。"]', '诗', 'shi', '', NULL, '因話天台勝異仍送羅道士 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01c487bc-5775-4c13-8a61-3216b4bbbc63', '哭喻鳧先輩', '哭喻鳧先輩', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["日夜役神多損壽，先生下世未中年。","撰碑縱託登龍伴，營奠應支賣鶴錢。","孤壠陰風吹細草，空窗濕氣漬殘篇。","人間別更無冤事，到此誰能與問天。"]', '["日夜役神多損壽，先生下世未中年。","撰碑縱託登龙伴，營奠應支賣鹤錢。","孤壠陰风吹細草，空窗濕氣漬殘篇。","人间別更無冤事，到此誰能與问天。"]', '诗', 'shi', '', NULL, '哭喻鳧先輩 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('314bd64b-c7d2-40e5-8c72-3c5677414ef2', '湖北有茅齋湖西有松島輕棹往返頗諧素心因成四韻', '湖北有茅斋湖西有松島轻棹往返頗諧素心因成四韻', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["湖北湖西往復還，朝昏只處自由間。","暑天移榻就深竹，月夜乘舟歸淺山。","遶砌紫鱗欹枕釣，垂簷野果隔窗攀。","古賢暮齒方如此，多笑愚儒鬢未斑。"]', '["湖北湖西往复還，朝昏只处自由间。","暑天移榻就深竹，月夜乘舟归淺山。","遶砌紫鱗欹枕釣，垂簷野果隔窗攀。","古賢暮齒方如此，多笑愚儒鬢未斑。"]', '诗', 'shi', '', NULL, '湖北有茅齋湖西有松島輕棹往返頗諧素心因成四韻 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d5603e7-c931-48b0-a94b-3be81dbda988', '鑑湖西島言事', '鑑湖西島言事', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["慵拙幸便荒僻地，縱聽猨鳥亦何愁。","偶斟藥酒欺梅雨，却著寒衣過麥秋。","歲計有時添橡實，生涯一半在漁舟。","世人若便無知己，應向此溪成白頭。"]', '["慵拙幸便荒僻地，縱听猨鸟亦何愁。","偶斟藥酒欺梅雨，却著寒衣過麦秋。","歲計有时添橡實，生涯一半在漁舟。","世人若便無知己，應向此溪成白头。"]', '诗', 'shi', '', NULL, '鑑湖西島言事 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86eb8fc6-f33d-44a3-850a-2d879467406f', '山中言事', '山中言事', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["欹枕亦吟行亦醉，臥吟行醉更何營。","貧來猶有故琴在，老去不過新髪生。","山鳥踏枝紅果落，家童引釣白魚驚。","潛夫自有孤雲侶，可要王侯知姓名。"]', '["欹枕亦吟行亦醉，臥吟行醉更何營。","貧来猶有故琴在，老去不過新髪生。","山鸟踏枝紅果落，家童引釣白鱼驚。","潛夫自有孤云侶，可要王侯知姓名。"]', '诗', 'shi', '', NULL, '山中言事 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8aca568e-ef41-4db0-b1c0-7489e5640c45', '贈蕭山彭少府', '贈蕭山彭少府', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["作尉孜孜更寒苦，操心至癖不爲清。","雖將劍鶴支殘債，猶有歌篇取盛名。","盡擬勤求爲弟子，皆將疑義問先生。","與君相識因儒術，歲月彌多別有情。"]', '["作尉孜孜更寒苦，操心至癖不爲清。","雖將劍鹤支殘債，猶有歌篇取盛名。","尽擬勤求爲弟子，皆將疑義问先生。","與君相識因儒術，歲月彌多別有情。"]', '诗', 'shi', '', NULL, '贈蕭山彭少府 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03368df1-771c-489b-964f-a094084d86ab', '贈式上人', '贈式上人', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["縱居鼙角喧闐處，亦共雲溪邃僻同。","萬慮全離方寸內，一生多在五言中。","芰荷葉上難停雨，松檜枝間自有風。","莫笑旅人終日醉，吾將大醉與禪通。"]', '["縱居鼙角喧闐处，亦共云溪邃僻同。","万慮全離方寸內，一生多在五言中。","芰荷葉上难停雨，松檜枝间自有风。","莫笑旅人終日醉，吾將大醉與禪通。"]', '诗', 'shi', '', NULL, '贈式上人 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('698608ee-0eff-4d41-9fd5-57bbd7991016', '贈錢塘湖上唐處士', '贈錢塘湖上唐处士', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["我愛君家似洞庭，衝灣潑岸夜波聲。","蟾蜍影裏清吟苦，舴艋舟中白髮生。","常共酒杯爲侶伴，復聞紗帽見公卿。","莫言舉世無知己，自有孤雲識此情。"]', '["我愛君家似洞庭，衝灣潑岸夜波声。","蟾蜍影裏清吟苦，舴艋舟中白髮生。","常共酒杯爲侶伴，复闻紗帽见公卿。","莫言舉世無知己，自有孤云識此情。"]', '诗', 'shi', '', NULL, '贈錢塘湖上唐處士 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e788505-144a-49bf-a394-5fdc3fd76a6f', '山中言事', '山中言事', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["日與村家事漸同，燒松啜茗學鄰翁。","池塘月撼芙蕖浪，窗戶涼生薜荔風。","書幌晝昏嵐氣裏，巢枝俯折雪聲中。","山陰釣叟無知己，窺鏡撏多鬢欲空。"]', '["日與村家事漸同，燒松啜茗学鄰翁。","池塘月撼芙蕖浪，窗戶涼生薜荔风。","书幌晝昏嵐氣裏，巢枝俯折雪声中。","山陰釣叟無知己，窺镜撏多鬢欲空。"]', '诗', 'shi', '', NULL, '山中言事 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('219840bc-43a1-4319-b302-8ee40a49b3c5', '題陶詳校書陽羨隱居', '題陶詳校书陽羨隐居', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["芸香署裏從容步，陽羨山中嘯傲情。","竿底紫鱗輸釣伴，花邊白犬吠流鶯。","長潭五月含冰氣，孤檜中宵學雨聲。","便泛扁舟應未得，鴟夷棄相始垂名。"]', '["芸香署裏從容步，陽羨山中嘯傲情。","竿底紫鱗輸釣伴，花邊白犬吠流鶯。","长潭五月含冰氣，孤檜中宵学雨声。","便泛扁舟應未得，鴟夷棄相始垂名。"]', '诗', 'shi', '', NULL, '題陶詳校書陽羨隱居 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2f87f2a-df54-481f-9c30-f42de1929152', '秋晚林中寄賓幕', '秋晚林中寄賓幕', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["八月蕭條九月時，沙蟬海燕各分飛。","杯盂未稱嘗生酒，砧杵先催試熟衣。","泉漱玉聲衝石竇，橘垂朱實壓荆扉。","無過縱有家山思，印綬留連爭得歸。"]', '["八月蕭條九月时，沙蟬海燕各分飞。","杯盂未稱嘗生酒，砧杵先催試熟衣。","泉漱玉声衝石竇，橘垂朱實壓荆扉。","無過縱有家山思，印綬留連爭得归。"]', '诗', 'shi', '', NULL, '秋晚林中寄賓幕 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a79294e3-38ff-4617-bb89-b0ddbcc62ef0', '與鄉人鑒休上人別', '與乡人鑒休上人別', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["此日因師話鄉里，故鄉風土我偏諳。","一枝竹葉如溪北，半樹梅花似嶺南。","山夜獵徒多信犬，雨天村舍未催蠶。","如今休作還家意，兩鬚垂絲已不堪。"]', '["此日因師話乡里，故乡风土我偏諳。","一枝竹葉如溪北，半樹梅花似嶺南。","山夜獵徒多信犬，雨天村舍未催蠶。","如今休作還家意，兩鬚垂絲已不堪。"]', '诗', 'shi', '', NULL, '與鄉人鑒休上人別 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bdd79ba-21f7-467d-96a0-a6201acfc39c', '送王霖赴舉', '送王霖赴舉', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["自古主司看薦士，明年應是不參差。","須憑吉夢爲先兆，必恐長才偶盛時。","北闕上書衝雪早，西陵中酒趂潮遲。","郄詵可要真消息，只向春前便得知。"]', '["自古主司看薦士，明年應是不參差。","須憑吉梦爲先兆，必恐长才偶盛时。","北闕上书衝雪早，西陵中酒趂潮遲。","郄詵可要真消息，只向春前便得知。"]', '诗', 'shi', '', NULL, '送王霖赴舉 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d0bd591-16cb-4cbb-8082-517f3c5ef211', '思越中舊遊寄友', '思越中旧游寄友', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["甸外山川無越國，依稀只似劍門西。","鏡中疊浪搖星斗，城上繁花咽鼓鼙。","斷臂青猿啼玉笥，成行白鳥下耶溪。","此中曾是同遊處，迢遞尋君夢不迷。"]', '["甸外山川無越国，依稀只似劍门西。","镜中叠浪搖星斗，城上繁花咽鼓鼙。","斷臂青猿啼玉笥，成行白鸟下耶溪。","此中曾是同游处，迢遞尋君梦不迷。"]', '诗', 'shi', '', NULL, '思越中舊遊寄友 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93e8fe54-0498-46a2-8564-59cf7b27ea50', '陪胡中丞泛湖', '陪胡中丞泛湖', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["仙舟仙藥醉行春，上界稀逢下界人。","綺繡峰前聞野鶴，旌旗影裏見遊鱗。","澄潭徹底齊心鏡，雜樹含芳讓錦茵。","凡許從容誰不幸，就中光顯是州民。"]', '["仙舟仙藥醉行春，上界稀逢下界人。","綺繡峰前闻野鹤，旌旗影裏见游鱗。","澄潭徹底齊心镜，杂樹含芳讓錦茵。","凡許從容誰不幸，就中光显是州民。"]', '诗', 'shi', '', NULL, '陪胡中丞泛湖 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2c3b930-6ef4-4548-8dd8-f544f2381e79', '敘雪獻員外', '敘雪獻員外', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["紛紜宛轉更堪看，壓竹摧巢井徑漫。","風柳細條粘不得，春溪綠色蔽應難。","清輝直認中庭月，濕氣偏添半夜寒。","謝守來吟才更逸，郢詞先至彩毫端。"]', '["紛紜宛轉更堪看，壓竹摧巢井徑漫。","风柳細條粘不得，春溪綠色蔽應难。","清輝直認中庭月，濕氣偏添半夜寒。","謝守来吟才更逸，郢词先至彩毫端。"]', '诗', 'shi', '', NULL, '敘雪獻員外 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e08d19b-a0bb-48dc-b561-1ec365edbf2f', '王將軍', '王將軍', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["大志無心守章句，終懷上畧致殊功。","保寧帝業青萍在，投棄儒書絳帳空。","密雪曙連葱嶺道，青松夜起柳營風。","將星依舊當文座，應念愚儒命未通。"]', '["大志無心守章句，終懷上畧致殊功。","保寧帝業青萍在，投棄儒书絳帳空。","密雪曙連葱嶺道，青松夜起柳營风。","將星依旧當文座，應念愚儒命未通。"]', '诗', 'shi', '', NULL, '王將軍 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19118f03-caa0-4c76-9dcf-582138961a18', '陽亭言事獻漳州于使君', '陽亭言事獻漳州于使君', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["重疊山前對酒罇，騰騰兀兀度朝昏。","平明疎磬白雲寺，遙夜孤砧紅葉村。","去鳥豈知煙樹遠，驚魚應覺露荷翻。","旅人寄食逢黃菊，每見故人思故園。"]', '["重叠山前对酒罇，腾腾兀兀度朝昏。","平明疎磬白云寺，遙夜孤砧紅葉村。","去鸟豈知煙樹远，驚鱼應覺露荷翻。","旅人寄食逢黄菊，每见故人思故园。"]', '诗', 'shi', '', NULL, '陽亭言事獻漳州于使君 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba970512-e02b-48c0-bf95-d18e3a2bc599', '海石榴', '海石榴', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["亭際夭妍日日看，每朝顏色一般般。","滿枝猶待春風力，數朵先欺臘雪寒。","舞蝶似隨歌拍轉，遊人只怕酒杯乾。","久長年少應難得，忍不叢邊到夜觀。"]', '["亭際夭妍日日看，每朝顏色一般般。","满枝猶待春风力，數朵先欺臘雪寒。","舞蝶似隨歌拍轉，游人只怕酒杯乾。","久长年少應难得，忍不叢邊到夜观。"]', '诗', 'shi', '', NULL, '海石榴 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f77afa59-211a-41fc-9f77-3f4b5823b370', '嘉興許明府', '嘉兴許明府', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["檇李轉聞風教好，重門夜不上重關。","腰懸墨綬三年外，身去青雲一步間。","勤苦字人酬帝力，從容對客問家山。","升沈路別情猶在，不忘鄉中舊往還。"]', '["檇李轉闻风教好，重门夜不上重关。","腰懸墨綬三年外，身去青云一步间。","勤苦字人酬帝力，從容对客问家山。","升沈路別情猶在，不忘乡中旧往還。"]', '诗', 'shi', '', NULL, '嘉興許明府 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18450793-5eda-461d-8116-5d6d6ee367b5', '再題路支使南亭', '再題路支使南亭', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["行處避松兼礙石，即須門徑落斜開。","愛邀舊友看漁釣，貪聽新禽駐酒杯。","樹影不隨明月去，溪聲常送落花來。","睡時分得江淹夢，五色毫端弄逸才。"]', '["行处避松兼礙石，即須门徑落斜开。","愛邀旧友看漁釣，貪听新禽駐酒杯。","樹影不隨明月去，溪声常送落花来。","睡时分得江淹梦，五色毫端弄逸才。"]', '诗', 'shi', '', NULL, '再題路支使南亭 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0ca1ce6-b3b0-419e-96b8-1cee5eb75a66', '路支使小池', '路支使小池', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["廣狹偶然非製定，猶將方寸像滄溟。","一泓春水無多浪，數尺晴天幾箇星。","露滿玉盤當半夜，匣開金鏡在中庭。","主人垂釣常來此，雖把魚竿醉未醒。"]', '["廣狹偶然非製定，猶將方寸像滄溟。","一泓春水無多浪，數尺晴天幾箇星。","露满玉盤當半夜，匣开金镜在中庭。","主人垂釣常来此，雖把鱼竿醉未醒。"]', '诗', 'shi', '', NULL, '路支使小池 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7e0d0d6-2063-4b07-bafd-01bc247f209f', '哭江西處士陳陶', '哭江西处士陳陶', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["壽盡天年命不通，釣溪吟月便成翁。","雖云掛劍來墳上，亦恐藏書在壁中。","巢父精靈歸大夜，客兒才調振遺風。","南華至理須齊物，生死即應無異同。"]', '["壽尽天年命不通，釣溪吟月便成翁。","雖云掛劍来墳上，亦恐藏书在壁中。","巢父精靈归大夜，客兒才調振遺风。","南华至理須齊物，生死即應無異同。"]', '诗', 'shi', '', NULL, '哭江西處士陳陶 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9813c7bf-4e9f-4077-8c55-51a920e30c98', '越中言事二首 一', '越中言事二首 一', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["異術閑和合聖明，湖光浩氣共澄清。","郭中雲吐啼猿寺，山上花藏調角城。","香起荷灣停棹飲，絲垂柳陌約鞭行。","遊人今日又明日，不覺鏡中新髪生。"]', '["異術闲和合聖明，湖光浩氣共澄清。","郭中云吐啼猿寺，山上花藏調角城。","香起荷灣停棹饮，絲垂柳陌約鞭行。","游人今日又明日，不覺镜中新髪生。"]', '诗', 'shi', '', NULL, '越中言事二首 一 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b945626-9876-42b1-aaf5-604eef9071ec', '越中言事二首 二', '越中言事二首 二', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["雲霞水木共蒼蒼，元化分功秀一方。","百里湖波輕撼月，五更軍角慢吹霜。","沙邊賈客喧魚市，島上潛夫醉笋莊。","終歲逍遙仁術內，無名甘老買臣鄉。"]', '["云霞水木共蒼蒼，元化分功秀一方。","百里湖波轻撼月，五更軍角慢吹霜。","沙邊賈客喧鱼市，島上潛夫醉笋莊。","終歲逍遙仁術內，無名甘老買臣乡。"]', '诗', 'shi', '', NULL, '越中言事二首 二 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb219c41-8710-4792-9e73-33a0b4f27527', '題龍瑞觀兼呈徐尊師', '題龙瑞观兼呈徐尊師', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["或雨或雲常不定，地靈雲雨自無時。","世人莫識神方字，仙鳥偏棲藥樹枝。","遠壑度年如晦暝，陰溪入夏有凌澌。","此中唯有師知我，未得尋師即夢師。"]', '["或雨或云常不定，地靈云雨自無时。","世人莫識神方字，仙鸟偏棲藥樹枝。","远壑度年如晦暝，陰溪入夏有凌澌。","此中唯有師知我，未得尋師即梦師。"]', '诗', 'shi', '', NULL, '題龍瑞觀兼呈徐尊師 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bd0bb5a-d305-4afc-80f0-d842dbdf023d', '送陳秀才將遊霅上便議北歸', '送陳秀才將游霅上便議北归', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["婆娑戀酒山花盡，繞繚還家水路通。","轉檝擬從青草岸，吹帆猶是白蘋風。","淮邊欲暝軍鼙急，洛下先寒苑樹空。","詩句因余更孤峭，書題不合忘江東。"]', '["婆娑戀酒山花尽，繞繚還家水路通。","轉檝擬從青草岸，吹帆猶是白蘋风。","淮邊欲暝軍鼙急，洛下先寒苑樹空。","诗句因余更孤峭，书題不合忘江东。"]', '诗', 'shi', '', NULL, '送陳秀才將遊霅上便議北歸 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e7eb93e-9294-474c-b83b-257898357a45', '送吳彥融赴舉', '送吳彥融赴舉', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["用心精至自無疑，千萬人中似汝稀。","上國纔將五字去，全家便待一枝歸。","西陵柳路搖鞭盡，北固潮程掛席飛。","想見明年榜前事，當時分散著來衣。"]', '["用心精至自無疑，千万人中似汝稀。","上国纔將五字去，全家便待一枝归。","西陵柳路搖鞭尽，北固潮程掛席飞。","想见明年榜前事，當时分散著来衣。"]', '诗', 'shi', '', NULL, '送吳彥融赴舉 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b68f064-cd74-4b78-867a-165b29488e28', '同蕭山陳長官縣樓登望', '同蕭山陳长官縣楼登望', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["坐看南北與西東，遠近無非禮義中。","一縣繁花香送雨，五株垂柳綠牽風。","寒濤背海喧還靜，驛路穿林斷復通。","仲叔受恩多感戀，裴回却怕酒壺空。"]', '["坐看南北與西东，远近無非禮義中。","一縣繁花香送雨，五株垂柳綠牽风。","寒濤背海喧還静，驛路穿林斷复通。","仲叔受恩多感戀，裴回却怕酒壺空。"]', '诗', 'shi', '', NULL, '同蕭山陳長官縣樓登望 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f9172b0-4e23-4bd3-8a8e-5de0ef6ad17b', '送何道者', '送何道者', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["何事忽來還忽去，孤雲不定鶴情高。","真經與術添年壽，靈藥分功入鬢毛。","必擬一身生羽翼，終看陸地作波濤。","遍尋巖洞求仙者，即恐無人似爾曹。"]', '["何事忽来還忽去，孤云不定鹤情高。","真經與術添年壽，靈藥分功入鬢毛。","必擬一身生羽翼，終看陸地作波濤。","遍尋巖洞求仙者，即恐無人似爾曹。"]', '诗', 'shi', '', NULL, '送何道者 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ee88668-70ec-4e83-866c-5f458783fc23', '酬將作于少監', '酬將作于少監', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["由來至寶出毫端，五色炎光照室寒。","仰望孤峰知聳峻，前臨積水見波瀾。","冰絲織絡經心久，瑞玉雕磨措手難。","不是散齋兼拭目，尋常未便借人看。"]', '["由来至寶出毫端，五色炎光照室寒。","仰望孤峰知聳峻，前臨積水见波瀾。","冰絲织絡經心久，瑞玉雕磨措手难。","不是散斋兼拭目，尋常未便借人看。"]', '诗', 'shi', '', NULL, '酬將作于少監 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('448178d2-a4fd-4881-80d6-dbbae17f5f88', '雪中寄殷道士', '雪中寄殷道士', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["大片紛紛小片輕，雨和風擊更縱橫。","園林入夜寒光動，窗戶凌晨濕氣生。","蔽野吞村飄未歇，摧巢壓竹密無聲。","山陰道士吟多興，六出花邊五字成。"]', '["大片紛紛小片轻，雨和风擊更縱橫。","园林入夜寒光动，窗戶凌晨濕氣生。","蔽野吞村飄未歇，摧巢壓竹密無声。","山陰道士吟多兴，六出花邊五字成。"]', '诗', 'shi', '', NULL, '雪中寄殷道士 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6da6fa2f-1363-47fa-bc30-f4e58f4c2118', '宋從事', '宋從事', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["出衆仙才是謫仙，裁霞曳繡一篇篇。","雖將潔白酬知己，自有風流助少年。","欹枕臥吟荷葉雨，持杯坐醉菊花天。","冥搜太苦神應乏，心在虛無更那邊。"]', '["出衆仙才是謫仙，裁霞曳繡一篇篇。","雖將潔白酬知己，自有风流助少年。","欹枕臥吟荷葉雨，持杯坐醉菊花天。","冥搜太苦神應乏，心在虛無更那邊。"]', '诗', 'shi', '', NULL, '宋從事 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38e4dc8c-ad08-42b7-ad37-f567ca0e0104', '出山寄蘇從事', '出山寄蘇從事', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["寸心似火頻求薦，兩鬢如霜始息機。","隔岸雞鳴春耨去，鄰家犬吠夜漁歸。","倚松長嘯宜疎拙，拂石欹眠絕是非。","多謝元瑜憐野賤，時迴車馬發光輝。"]', '["寸心似火頻求薦，兩鬢如霜始息機。","隔岸雞鳴春耨去，鄰家犬吠夜漁归。","倚松长嘯宜疎拙，拂石欹眠絕是非。","多謝元瑜怜野賤，时迴车马發光輝。"]', '诗', 'shi', '', NULL, '出山寄蘇從事 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9db8c539-b088-4546-89fd-6a8b06278601', '送杭州李員外', '送杭州李員外', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["政成何用滿三年，上界羣仙待謫仙。","便赴新恩歸紫禁，還從舊路上青天。","笙歌怨咽當離席，更漏丁東在畫船。","必恐駐班留立位，前程一步是爐煙。"]', '["政成何用满三年，上界羣仙待謫仙。","便赴新恩归紫禁，還從旧路上青天。","笙歌怨咽當離席，更漏丁东在畫船。","必恐駐班留立位，前程一步是爐煙。"]', '诗', 'shi', '', NULL, '送杭州李員外 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d49094f-55f8-4c88-ba18-2aabc71e7130', '贈李支使', '贈李支使', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["藥成平地是寥天，三十人中最少年。","白雪振聲來輦下，青雲開路到牀前。","公卿位近應翹足，荀宋才微可拍肩。","一等孔門爲弟子，愚儒獨自賦歸田。"]', '["藥成平地是寥天，三十人中最少年。","白雪振声来輦下，青云开路到牀前。","公卿位近應翹足，荀宋才微可拍肩。","一等孔门爲弟子，愚儒独自賦归田。"]', '诗', 'shi', '', NULL, '贈李支使 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f390f8db-8215-45fe-900e-b2b3f728a0ba', '盧卓山人畫水', '盧卓山人畫水', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["常聞畫石不畫水，畫水至難君得名。","海色未將藍汁染，筆鋒猶傍墨花行。","散吞高下應無岸，斜蹙東南勢欲傾。","坐久神迷不能決，却疑身在小蓬瀛。"]', '["常闻畫石不畫水，畫水至难君得名。","海色未將藍汁染，笔鋒猶傍墨花行。","散吞高下應無岸，斜蹙东南勢欲傾。","坐久神迷不能決，却疑身在小蓬瀛。"]', '诗', 'shi', '', NULL, '盧卓山人畫水 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e622114b-9dec-44cd-9335-d0aa5c5d37d2', '廢宅', '廢宅', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["主人何處獨裴回，流水自流花自開。","若見故交皆散去，即應新燕不歸來。","入門繚繞穿荒竹，坐石逡巡染綠苔。","應是曾經惡風雨，修桐半折損琴材。"]', '["主人何处独裴回，流水自流花自开。","若见故交皆散去，即應新燕不归来。","入门繚繞穿荒竹，坐石逡巡染綠苔。","應是曾經惡风雨，修桐半折損琴材。"]', '诗', 'shi', '', NULL, '廢宅 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9713e138-57fe-4bae-a364-8f38cd449bf6', '題寶林山禪院', '題寶林山禪院', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["山捧亭臺郭遶山，遙盤蒼翠到山巔。","嵒中古井雖通海，窟裏陰雲不上天。","羅列衆星依木末，周迴萬室在簷前。","我來可要歸禪老，一寸寒灰已達玄。"]', '["山捧亭台郭遶山，遙盤蒼翠到山巔。","嵒中古井雖通海，窟裏陰云不上天。","羅列衆星依木末，周迴万室在簷前。","我来可要归禪老，一寸寒灰已達玄。"]', '诗', 'shi', '', NULL, '題寶林山禪院 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('805df95b-c30d-4773-ac47-68f6574f6d81', '題越州袁秀才林亭', '題越州袁秀才林亭', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["清邃林亭指畫開，幽巖別派像天台。","坐牽蕉葉題詩句，醉觸藤花落酒杯。","白鳥不歸山裏去，紅鱗多自鏡中來。","終年此地爲吟伴，早起尋君薄暮迴。"]', '["清邃林亭指畫开，幽巖別派像天台。","坐牽蕉葉題诗句，醉觸藤花落酒杯。","白鸟不归山裏去，紅鱗多自镜中来。","終年此地爲吟伴，早起尋君薄暮迴。"]', '诗', 'shi', '', NULL, '題越州袁秀才林亭 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81f683ef-6473-46a1-bb41-7d1888aaad58', '題龜山穆上人院', '題龟山穆上人院', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["修持百法過半百，日往月來心更堅。","牀上水雲隨坐夏，林西山月伴行禪。","寒蜩遠韻來窗裏，白鳥斜行起砌邊。","我愛尋師師訪我，只應尋訪是因緣。"]', '["修持百法過半百，日往月来心更堅。","牀上水云隨坐夏，林西山月伴行禪。","寒蜩远韻来窗裏，白鸟斜行起砌邊。","我愛尋師師訪我，只應尋訪是因緣。"]', '诗', 'shi', '', NULL, '題龜山穆上人院 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08db89b6-4d7c-4074-8bd6-3b33ebbde829', '贈美人四首 一', '贈美人四首 一', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["直緣多藝用心勞，心路玲瓏格調高。","舞袖低徊真蛺蝶，朱唇深淺假櫻桃。","粉胸半掩疑晴雪，醉眼斜迴小樣刀。","才會雨雲須別去，語慙不及琵琶槽。"]', '["直緣多藝用心勞，心路玲瓏格調高。","舞袖低徊真蛺蝶，朱唇深淺假櫻桃。","粉胸半掩疑晴雪，醉眼斜迴小樣刀。","才會雨云須別去，語慙不及琵琶槽。"]', '诗', 'shi', '', NULL, '贈美人四首 一 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d9deda2-45b5-48e1-87df-5ac40d378827', '贈美人四首 二', '贈美人四首 二', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["嚴冬忽作看花日，盛暑翻爲見雪時。","坐上弄嬌聲不轉，尊前掩笑意難知。","含歌媚盼如桃葉，妙舞輕盈似柳枝。","年幾未多猶怯在，些些私語怕人疑。"]', '["嚴冬忽作看花日，盛暑翻爲见雪时。","坐上弄嬌声不轉，尊前掩笑意难知。","含歌媚盼如桃葉，妙舞轻盈似柳枝。","年幾未多猶怯在，些些私語怕人疑。"]', '诗', 'shi', '', NULL, '贈美人四首 二 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('205e4696-114f-411a-b878-207f4252123d', '贈美人四首 三', '贈美人四首 三', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["酒蘊天然自性靈，人間有藝總關情。","剝葱十指轉籌疾，舞柳細腰隨拍輕。","常恐胸前春雪釋，惟愁座上慶雲生。","若教梅尉無仙骨，爭得仙娥駐玉京。"]', '["酒蘊天然自性靈，人间有藝總关情。","剝葱十指轉籌疾，舞柳細腰隨拍轻。","常恐胸前春雪釋，惟愁座上慶云生。","若教梅尉無仙骨，爭得仙娥駐玉京。"]', '诗', 'shi', '', NULL, '贈美人四首 三 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05b510f0-bbe5-4fc3-b5eb-aadb25008942', '贈美人四首 四', '贈美人四首 四', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["昔日仙人今玉人，深冬相見亦如春。","倍酬金價微含笑，纔發歌聲早動塵。","昔歲曾爲蕭史伴，今朝應作宋家鄰。","百年別後知誰在，須遣丹青畫取真。"]', '["昔日仙人今玉人，深冬相见亦如春。","倍酬金價微含笑，纔發歌声早动塵。","昔歲曾爲蕭史伴，今朝應作宋家鄰。","百年別後知誰在，須遣丹青畫取真。"]', '诗', 'shi', '', NULL, '贈美人四首 四 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ac33c00-bd81-45a3-a893-f18aa9617e71', '聽段處士彈琴', '听段处士彈琴', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["幾年調弄七條絲，元化分功十指知。","泉迸幽音離石底，松含細韻在霜枝。","窗中顧兔初圓夜，竹上寒蟬盡散時。","唯有此時心更靜，聲聲可作後人師。"]', '["幾年調弄七條絲，元化分功十指知。","泉迸幽音離石底，松含細韻在霜枝。","窗中顧兔初圓夜，竹上寒蟬尽散时。","唯有此时心更静，声声可作後人師。"]', '诗', 'shi', '', NULL, '聽段處士彈琴 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7062bbc-428a-46cc-a9da-a03c3fece818', '初歸鏡中寄陳端公', '初归镜中寄陳端公', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["去歲離家今歲歸，孤帆夢向鳥前飛。","必知蘆笋侵沙井，兼被藤花占石磯。","雲島採茶常失路，雪龕中酒不關扉。","故交若問逍遙事，玄冕何曾勝葦衣。"]', '["去歲離家今歲归，孤帆梦向鸟前飞。","必知蘆笋侵沙井，兼被藤花占石磯。","云島採茶常失路，雪龕中酒不关扉。","故交若问逍遙事，玄冕何曾勝葦衣。"]', '诗', 'shi', '', NULL, '初歸鏡中寄陳端公 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13933f4a-f8e9-4914-a2af-8f652a6649cb', '再題龍泉寺上方', '再題龙泉寺上方', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["牛斗正齊羣木末，鳥行橫截衆山腰。","路盤砌下兼穿竹，井在巖頭亦統潮。","海岸四更看日出，石房三月任花燒。","未能割得繁華去，難向此中甘寂寥。"]', '["牛斗正齊羣木末，鸟行橫截衆山腰。","路盤砌下兼穿竹，井在巖头亦統潮。","海岸四更看日出，石房三月任花燒。","未能割得繁华去，难向此中甘寂寥。"]', '诗', 'shi', '', NULL, '再題龍泉寺上方 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('804bd3c9-3828-4e3c-a217-bc1e3995b88b', '于秀才小池', '于秀才小池', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["一泓瀲灧復澄明，半日功夫斸小庭。","占地未過四五尺，浸天唯入兩三星。","鷁舟草際浮霜葉，[漁]火沙邊駐小螢。","纔見規模識方寸，知君立意象滄溟。"]', '["一泓瀲灧复澄明，半日功夫斸小庭。","占地未過四五尺，浸天唯入兩三星。","鷁舟草際浮霜葉，[漁]火沙邊駐小螢。","纔见規模識方寸，知君立意象滄溟。"]', '诗', 'shi', '', NULL, '于秀才小池 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4bb6bb4-0a1a-4ac0-9103-8e34e6a2347d', '敘錢塘異勝', '敘錢塘異勝', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["暖景融融寒景清，越臺風送曉鐘聲。","四郊遠火燒煙月，一道驚波撼郡城。","夜雪未知東岸綠，春風猶放半江晴。","謝公吟處依稀在，千古無人繼盛名。"]', '["暖景融融寒景清，越台风送晓鐘声。","四郊远火燒煙月，一道驚波撼郡城。","夜雪未知东岸綠，春风猶放半江晴。","謝公吟处依稀在，千古無人繼盛名。"]', '诗', 'shi', '', NULL, '敘錢塘異勝 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec3bb929-3cb1-47fe-ab85-27f0f9a04359', '贈中巖王處士', '贈中巖王处士', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["垂楊褭褭草芊芊，氣象清深似洞天。","援筆便成鸚鵡賦，洗花須用桔槔泉。","商於避世堪同日，渭曲逢時必有年。","直恐剛腸閑未得，醉吟爭奈被才牽。"]', '["垂楊褭褭草芊芊，氣象清深似洞天。","援笔便成鸚鵡賦，洗花須用桔槔泉。","商於避世堪同日，渭曲逢时必有年。","直恐剛腸闲未得，醉吟爭奈被才牽。"]', '诗', 'shi', '', NULL, '贈中巖王處士 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecad7cb7-d844-4261-8828-774ea7096f54', '初歸故里獻侯郎中', '初归故里獻侯郎中', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["常思舊里欲歸難，已作歸心即自寬。","此日早知無爵位，當時便合把漁竿。","朝昏入閏春將逼，城邑多山夏却寒。","不是幽愚望榮忝，君侯異禮亦何安。"]', '["常思旧里欲归难，已作归心即自寬。","此日早知無爵位，當时便合把漁竿。","朝昏入閏春將逼，城邑多山夏却寒。","不是幽愚望榮忝，君侯異禮亦何安。"]', '诗', 'shi', '', NULL, '初歸故里獻侯郎中 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b920e66d-5611-4e4a-9050-b93061ca9d08', '歸睦州中路寄侯郎中', '归睦州中路寄侯郎中', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["顏巷蕭條知命後，膺門感激受恩初。","却容鶴髪還蝸舍，猶夢漁竿從隼旟。","新定暮雲吞故國，會稽春草入貧居。","鄉中自古爲儒者，誰得公侯降尺書。"]', '["顏巷蕭條知命後，膺门感激受恩初。","却容鹤髪還蝸舍，猶梦漁竿從隼旟。","新定暮云吞故国，會稽春草入貧居。","乡中自古爲儒者，誰得公侯降尺书。"]', '诗', 'shi', '', NULL, '歸睦州中路寄侯郎中 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf96d9bb-5f35-4d4a-bf12-3d21e39ea74f', '題報恩寺上方', '題報恩寺上方', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["來來先上上方看，眼界無窮世界寬。","巖溜噴空晴似雨，林蘿礙日夏多寒。","衆山迢遞皆相疊，一路高低不記盤。","清峭關心惜歸去，他時夢到亦難判。"]', '["来来先上上方看，眼界無窮世界寬。","巖溜噴空晴似雨，林蘿礙日夏多寒。","衆山迢遞皆相叠，一路高低不記盤。","清峭关心惜归去，他时梦到亦难判。"]', '诗', 'shi', '', NULL, '題報恩寺上方 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cd871a4-1f4a-4295-95a2-54080a243a70', '送永嘉王令之任二首 一', '送永嘉王令之任二首 一', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["定擬孜孜化海邊，須判素髪侮流年。","波濤不應雙溪水，分野長如二月天。","浮客若容開荻地，釣翁應免稅苔田。","前賢未必全堪學，莫讀當時歸去篇。"]', '["定擬孜孜化海邊，須判素髪侮流年。","波濤不應雙溪水，分野长如二月天。","浮客若容开荻地，釣翁應免稅苔田。","前賢未必全堪学，莫读當时归去篇。"]', '诗', 'shi', '', NULL, '送永嘉王令之任二首 一 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c3a79cf-cf6a-4bad-842b-6639ac55b7b1', '送永嘉王令之任二首 二', '送永嘉王令之任二首 二', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["雖展縣圖如到縣，五程猶入縉雲東。","山間閣道盤巖底，海界孤峰在浪中。","禮法未聞離漢制，土宜多說似吳風。","字人若用非常術，唯要旬時便立功。"]', '["雖展縣圖如到縣，五程猶入縉云东。","山间閣道盤巖底，海界孤峰在浪中。","禮法未闻離漢制，土宜多说似吳风。","字人若用非常術，唯要旬时便立功。"]', '诗', 'shi', '', NULL, '送永嘉王令之任二首 二 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55496726-b913-4685-83ea-b40d4ebf677c', '鹽官王長官新創瑞隱亭', '鹽官王长官新創瑞隐亭', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["指畫便分元化力，周迴秀絕自清機。","孤雲戀石尋常住，落絮縈風特地飛。","雛鳥啼花催釀酒，驚魚濺水誤沾衣。","明年秩滿難將去，何似先教畫取歸。"]', '["指畫便分元化力，周迴秀絕自清機。","孤云戀石尋常住，落絮縈风特地飞。","雛鸟啼花催釀酒，驚鱼濺水誤沾衣。","明年秩满难將去，何似先教畫取归。"]', '诗', 'shi', '', NULL, '鹽官王長官新創瑞隱亭 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4f2406a-32f3-4efc-8f56-f827db9647d8', '李戶曹小妓天得善擊越器以成曲章', '李戶曹小妓天得善擊越器以成曲章', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["越器敲來曲調成，腕頭勻滑自輕清。","隨風搖曳有餘韻，測水淺深多泛聲。","晝漏丁當相續滴，寒蟬計會一時鳴。","若教進上梨園去，衆樂無由更擅名。"]', '["越器敲来曲調成，腕头勻滑自轻清。","隨风搖曳有餘韻，測水淺深多泛声。","晝漏丁當相續滴，寒蟬計會一时鳴。","若教進上梨园去，衆乐無由更擅名。"]', '诗', 'shi', '', NULL, '李戶曹小妓天得善擊越器以成曲章 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('421ffaee-2a37-4e56-8383-00732b82ad6c', '歲晚言事寄鄉中親友', '歲晚言事寄乡中親友', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["急景蒼茫晝若昏，夜風乾峭觸前軒。","寒威半入龍蛇窟，暖氣全歸草樹根。","蠟燼凝來多碧焰，香醪滴處有冰痕。","尺書未達年應老，先被新春入故園。"]', '["急景蒼茫晝若昏，夜风乾峭觸前軒。","寒威半入龙蛇窟，暖氣全归草樹根。","蠟燼凝来多碧焰，香醪滴处有冰痕。","尺书未達年應老，先被新春入故园。"]', '诗', 'shi', '', NULL, '歲晚言事寄鄉中親友 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25656d38-a8f4-4aee-9f34-f7a41824f626', '贈孫百篇', '贈孫百篇', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["御題百首思縱橫，半日功夫舉世名。","羽冀便從吟處出，珠璣續向筆頭生。","莫嫌黃綬官資小，必料青雲道路平。","才子風流復年少，無愁高臥不公卿。"]', '["御題百首思縱橫，半日功夫舉世名。","羽冀便從吟处出，珠璣續向笔头生。","莫嫌黄綬官資小，必料青云道路平。","才子风流复年少，無愁高臥不公卿。"]', '诗', 'shi', '', NULL, '贈孫百篇 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c666b67e-ecb4-4aae-a61d-9f8dd0c7558d', '贈夏侯評事', '贈夏侯評事', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["傍窺盛德與高節，緬想應無前後人。","講論參同深到骨，停騰姹女立成銀。","棊功過却楊玄寶，易義精於梅子真。","朱紫侯門猶不見，可知岐路有風塵。"]', '["傍窺盛德與高節，緬想應無前後人。","講論參同深到骨，停腾姹女立成銀。","棊功過却楊玄寶，易義精於梅子真。","朱紫侯门猶不见，可知岐路有风塵。"]', '诗', 'shi', '', NULL, '贈夏侯評事 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20383cfb-ddf1-469f-8393-c419d3902a60', '送鄭端公', '送鄭端公', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["聖主佇知宣室事，豈容才子滯長沙。","隨珠此去方酬德，趙璧當時誤指瑕。","驄馬將離江浦月，繡衣却照禁中花。","應憐寂寞滄洲客，煙漢塵泥相去賒。"]', '["聖主佇知宣室事，豈容才子滯长沙。","隨珠此去方酬德，趙璧當时誤指瑕。","驄马將離江浦月，繡衣却照禁中花。","應怜寂寞滄洲客，煙漢塵泥相去賒。"]', '诗', 'shi', '', NULL, '送鄭端公 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb399434-92aa-4bf0-9efa-722fd23e559e', '題故人廢宅二首 一', '題故人廢宅二首 一', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["舉目淒涼入破門，鮫人一飯尚知恩。","閑花舊識猶含笑，怪石無情更不言。","樵叟和巢伐桃李，牧童兼草踏蘭蓀。","壺觴笑詠隨風去，唯有聲聲蜀帝魂。"]', '["舉目淒涼入破门，鮫人一飯尚知恩。","闲花旧識猶含笑，怪石無情更不言。","樵叟和巢伐桃李，牧童兼草踏蘭蓀。","壺觴笑詠隨风去，唯有声声蜀帝魂。"]', '诗', 'shi', '', NULL, '題故人廢宅二首 一 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46b62c90-24c9-4802-8ef6-2d0f47142173', '題故人廢宅二首 二', '題故人廢宅二首 二', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["寒莎野樹入荒庭，風雨蕭蕭不掩扃。","舊徑已知無孟竹，前溪應不浸荀星。","精靈消散歸寥廓，功業傳留在誌銘。","薄暮停車更悽愴，山陽隣笛若爲聽。"]', '["寒莎野樹入荒庭，风雨蕭蕭不掩扃。","旧徑已知無孟竹，前溪應不浸荀星。","精靈消散归寥廓，功業傳留在誌銘。","薄暮停车更悽愴，山陽隣笛若爲听。"]', '诗', 'shi', '', NULL, '題故人廢宅二首 二 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2afba7f8-a83f-4dc4-9330-1c9351374b8c', '寄于少監', '寄于少監', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["修持清苦振佳聲，衆鳥那知一鶚情。","躡履三千皆後學，摶風九萬即前程。","名將日月同時朽，身是山河應數生。","從此雲泥更懸闊，漁翁不合見公卿。"]', '["修持清苦振佳声，衆鸟那知一鶚情。","躡履三千皆後学，摶风九万即前程。","名將日月同时朽，身是山河應數生。","從此云泥更懸闊，漁翁不合见公卿。"]', '诗', 'shi', '', NULL, '寄于少監 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00e4e11e-d07b-4571-be1c-b7c0a9bae513', '和剡縣陳明府登縣樓', '和剡縣陳明府登縣楼', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["郭裏人家如掌上，簷前樹木映窗櫺。","煙霞若接天台地，分野應侵婺女星。","驛路古今通北闕，仙溪日夜入東溟。","綵衣才子多吟嘯，公退時時見畫屏。"]', '["郭裏人家如掌上，簷前樹木映窗櫺。","煙霞若接天台地，分野應侵婺女星。","驛路古今通北闕，仙溪日夜入东溟。","綵衣才子多吟嘯，公退时时见畫屏。"]', '诗', 'shi', '', NULL, '和剡縣陳明府登縣樓 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a642c7c-869a-461d-94a6-89cb68902bfd', '項洙處士畫水墨釣臺', '項洙处士畫水墨釣台', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["畫石畫松無兩般，猶嫌瀑布畫聲難。","雖云智惠生靈府，要且功夫在筆端。","潑處便連陰洞黑，添來先向朽枝乾。","我家曾寄雙臺下，往往開圖盡日看。"]', '["畫石畫松無兩般，猶嫌瀑布畫声难。","雖云智惠生靈府，要且功夫在笔端。","潑处便連陰洞黑，添来先向朽枝乾。","我家曾寄雙台下，往往开圖尽日看。"]', '诗', 'shi', '', NULL, '項洙處士畫水墨釣臺 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30bc1cb8-87e0-45f3-b373-b743251ebcb3', '贈天台葉尊師', '贈天台葉尊師', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["莫見平明離少室，須知薄暮入天台。","常時愛縮山川去，有夜自攜星月來。","靈藥不知何代得，古松應是長年栽。","先生暗笑看棊者，半局棊邊白髮催。"]', '["莫见平明離少室，須知薄暮入天台。","常时愛縮山川去，有夜自携星月来。","靈藥不知何代得，古松應是长年栽。","先生暗笑看棊者，半局棊邊白髮催。"]', '诗', 'shi', '', NULL, '贈天台葉尊師 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f338a4ab-eef7-43a3-b0f0-d19df1d980c5', '寄台州孫從事百篇', '寄台州孫從事百篇', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["聖世科名酬志業，仙州秀色助神機。","梅真入仕提雄筆，阮瑀從軍著綵衣。","晝寢不知山雪積，春遊應趁夜潮歸。","相思莫訝音書晚，鳥去猶須疊日飛。"]', '["聖世科名酬志業，仙州秀色助神機。","梅真入仕提雄笔，阮瑀從軍著綵衣。","晝寢不知山雪積，春游應趁夜潮归。","相思莫訝音书晚，鸟去猶須叠日飞。"]', '诗', 'shi', '', NULL, '寄台州孫從事百篇 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79ad1634-1d57-4ab5-a78d-608da7ae60c2', '送睦州侯郎中赴闕', '送睦州侯郎中赴闕', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["昔著政聲聞國外，今留儒術化江東。","青雲舊路歸仙掖，白鳳新詞入聖聰。","弦管未知銀燭曉，旌旗已侍錦帆風。","郡人難議酬恩德，徧在三年禮遇中。"]', '["昔著政声闻国外，今留儒術化江东。","青云旧路归仙掖，白鳳新词入聖聰。","弦管未知銀燭晓，旌旗已侍錦帆风。","郡人难議酬恩德，徧在三年禮遇中。"]', '诗', 'shi', '', NULL, '送睦州侯郎中赴闕 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2509435c-6904-417d-95b2-84d7e5a3c746', '朱秀才庭際薔薇', '朱秀才庭際薔薇', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["繡難相似畫難真，明媚鮮妍絕比倫。","露壓盤條方到地，風吹豔色欲燒春。","斷霞轉影侵西壁，濃麝分香入四鄰。","看取後時歸故里，庭花應讓錦衣新。"]', '["繡难相似畫难真，明媚鲜妍絕比倫。","露壓盤條方到地，风吹豔色欲燒春。","斷霞轉影侵西壁，濃麝分香入四鄰。","看取後时归故里，庭花應讓錦衣新。"]', '诗', 'shi', '', NULL, '朱秀才庭際薔薇 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('079f6fcf-4c0e-44f2-a54f-1fed25e11546', '登龍瑞觀北巖', '登龙瑞观北巖', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["縱目下看浮世事，方知峭崿與天通。","湖邊風力歸帆上，嶺頂雲根在雪中。","促韻寒鐘催落照，斜行白鳥入遙空。","前人去後後人至，今古異時登眺同。"]', '["縱目下看浮世事，方知峭崿與天通。","湖邊风力归帆上，嶺頂云根在雪中。","促韻寒鐘催落照，斜行白鸟入遙空。","前人去後後人至，今古異时登眺同。"]', '诗', 'shi', '', NULL, '登龍瑞觀北巖 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5a3986e-b53a-46ac-9775-f3bf5049eec5', '送婺州許錄事', '送婺州許錄事', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["之官便是還鄉路，白日堂堂著錦衣。","八詠遺風資逸興，二溪寒色助清威。","曙星沒盡提綱去，暝角吹殘鏁印歸。","笑我中年更愚僻，醉醒多在釣漁磯。"]', '["之官便是還乡路，白日堂堂著錦衣。","八詠遺风資逸兴，二溪寒色助清威。","曙星沒尽提綱去，暝角吹殘鏁印归。","笑我中年更愚僻，醉醒多在釣漁磯。"]', '诗', 'shi', '', NULL, '送婺州許錄事 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae9241dd-b994-4008-a225-f22ffe3df174', '題龍泉寺絕頂', '題龙泉寺絕頂', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["未明先見海底日，良久遠雞方報晨。","古樹含風長帶雨，寒巖四月始知春。","中天氣爽星河近，下界時豐雷雨勻。","前後登臨思無盡，年年改換去來人。"]', '["未明先见海底日，良久远雞方報晨。","古樹含风长带雨，寒巖四月始知春。","中天氣爽星河近，下界时豐雷雨勻。","前後登臨思無尽，年年改換去来人。"]', '诗', 'shi', '', NULL, '題龍泉寺絕頂 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43991de9-0528-495f-b247-88cdee06973d', '贈上虞胡少府百篇', '贈上虞胡少府百篇', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["求仙不在鍊金丹，輕舉由來別有門。","日晷未移三十刻，風騷已及四千言。","宏才尚遣居卑位，公道何曾雪至冤。","歛板塵中無恨色，應緣利祿副晨昏。"]', '["求仙不在鍊金丹，轻舉由来別有门。","日晷未移三十刻，风騷已及四千言。","宏才尚遣居卑位，公道何曾雪至冤。","歛板塵中無恨色，應緣利祿副晨昏。"]', '诗', 'shi', '', NULL, '贈上虞胡少府百篇 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27a31d0e-4cb3-4640-a12b-2af17e442dcb', '上鄭員外', '上鄭員外', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["爲郡至公兼至察，古今能有幾多人。","憂民一似清吟苦，守節還如未達貧。","利刃從前堪切玉，澄潭到底不容塵。","潛夫豈合干旌斾，甘棹漁舟下釣綸。"]', '["爲郡至公兼至察，古今能有幾多人。","憂民一似清吟苦，守節還如未達貧。","利刃從前堪切玉，澄潭到底不容塵。","潛夫豈合干旌斾，甘棹漁舟下釣綸。"]', '诗', 'shi', '', NULL, '上鄭員外 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28aed5ea-acbe-4f21-b6e3-0b625e92e068', '桐廬江閣', '桐廬江閣', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["風煙百變無定態，緬想畫人虛損心。","卷箔檻前沙鳥散，垂鉤牀下錦鱗沈。","白雲野寺凌晨磬，紅樹孤村遙夜砧。","此地四時拋不得，非唯盛暑事開襟。"]', '["风煙百变無定態，緬想畫人虛損心。","卷箔檻前沙鸟散，垂鉤牀下錦鱗沈。","白云野寺凌晨磬，紅樹孤村遙夜砧。","此地四时拋不得，非唯盛暑事开襟。"]', '诗', 'shi', '', NULL, '桐廬江閣 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2af8215-6ac6-436f-8539-fa1a746b98f0', '題澄聖塔院上方', '題澄聖塔院上方', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["地靈直是饒風雨，杉檜老於雲雨間。","只訝窗中常見海，方知砌下更多山。","遠泉勢曲猶須引，野果枝低可要攀。","若把重門諭玄寂，何妨善閉却無關。"]', '["地靈直是饒风雨，杉檜老於云雨间。","只訝窗中常见海，方知砌下更多山。","远泉勢曲猶須引，野果枝低可要攀。","若把重门諭玄寂，何妨善閉却無关。"]', '诗', 'shi', '', NULL, '題澄聖塔院上方 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9b64065-51f2-4088-a7fc-51d6a9e4c82c', '僧院小泉井', '僧院小泉井', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["亦恐淺深同禹穴，兼云制度象汙罇。","窺尋未見泉來路，緬想應穿石裂痕。","片段似冰猶可把，澄清如鏡不曾昏。","欲知到底無塵染，堪與吾師比性源。"]', '["亦恐淺深同禹穴，兼云制度象汙罇。","窺尋未见泉来路，緬想應穿石裂痕。","片段似冰猶可把，澄清如镜不曾昏。","欲知到底無塵染，堪與吾師比性源。"]', '诗', 'shi', '', NULL, '僧院小泉井 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3ed1da2-fd4b-4ba9-bb69-baa97b3165fb', '過姚監故居', '過姚監故居', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["不敢要君徵亦起，致君全得似唐虞。","讜言昨歎離天聽，新塚今聞入縣圖。","琴鎖壞窗風自觸，鶴歸喬木月難呼。","學書弟子何人在，檢點猶逢諫草無。"]', '["不敢要君徵亦起，致君全得似唐虞。","讜言昨歎離天听，新塚今闻入縣圖。","琴鎖壞窗风自觸，鹤归喬木月难呼。","学书弟子何人在，檢点猶逢諫草無。"]', '诗', 'shi', '', NULL, '過姚監故居 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d78bf863-e246-4cf5-a1a9-d463e9d553ca', '陪李郎中夜[宴]', '陪李郎中夜[宴]', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["間世星郎夜[宴]時，丁丁寒漏滴聲稀。","琵琶弦促千般語，鸚鵡杯深四散飛。","遍請玉容歌白雪，高燒紅蠟照朱衣。","人間有此榮華事，爭遣漁翁戀釣磯。"]', '["间世星郎夜[宴]时，丁丁寒漏滴声稀。","琵琶弦促千般語，鸚鵡杯深四散飞。","遍請玉容歌白雪，高燒紅蠟照朱衣。","人间有此榮华事，爭遣漁翁戀釣磯。"]', '诗', 'shi', '', NULL, '陪李郎中夜[宴] 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97cfa1a4-cd39-4c9d-a9fa-215d20f64d58', '狂寇後上劉尚書', '狂寇後上劉尚书', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["孫武傾心與萬夫，削平妖孽在斯須。","纔施偃月行軍令，便見台星逼座隅。","獨柱搘天寰海正，雄名蓋世古今無。","聖君爭不酬功業，仗下高懸破賊圖。"]', '["孫武傾心與万夫，削平妖孽在斯須。","纔施偃月行軍令，便见台星逼座隅。","独柱搘天寰海正，雄名蓋世古今無。","聖君爭不酬功業，仗下高懸破賊圖。"]', '诗', 'shi', '', NULL, '狂寇後上劉尚書 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14b6191b-91b8-4eb8-ab63-c0b4efdee1c5', '尚書新創敵樓二首 一', '尚书新創敵楼二首 一', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["下馬政成無一事，應須勝地過朝昏。","笙歌引出桃花洞，羅繡擁來金谷園。","十里水雲吞半郭，九秋山月入千門。","常聞大廈堪棲息，燕雀心知不敢言。"]', '["下马政成無一事，應須勝地過朝昏。","笙歌引出桃花洞，羅繡擁来金谷园。","十里水云吞半郭，九秋山月入千门。","常闻大廈堪棲息，燕雀心知不敢言。"]', '诗', 'shi', '', NULL, '尚書新創敵樓二首 一 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fda59d83-9203-463a-b642-10059d281859', '尚書新創敵樓二首 二', '尚书新創敵楼二首 二', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["異境永爲歡樂地，歌鐘夜夜復年年。","平明旭日生牀底，薄暮殘霞落酒邊。","雖向檻前窺下界，不知窗裏是中天。","直須分付丹青手，畫出旌幢遶謫仙。"]', '["異境永爲歡乐地，歌鐘夜夜复年年。","平明旭日生牀底，薄暮殘霞落酒邊。","雖向檻前窺下界，不知窗裏是中天。","直須分付丹青手，畫出旌幢遶謫仙。"]', '诗', 'shi', '', NULL, '尚書新創敵樓二首 二 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9358d8d8-b26e-420b-974a-b10553983866', '贈李郢端公', '贈李郢端公', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["非唯孤峭與世絕，吟處斯須能變通。","物外搜羅歸大雅，毫端剪削有餘功。","山川正氣侵靈府，雪月清輝引思風。","別得人間上昇術，丹霄路在五言中。"]', '["非唯孤峭與世絕，吟处斯須能变通。","物外搜羅归大雅，毫端剪削有餘功。","山川正氣侵靈府，雪月清輝引思风。","別得人间上昇術，丹霄路在五言中。"]', '诗', 'shi', '', NULL, '贈李郢端公 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e81a2e4c-3f09-41da-b6ab-7c9983984962', '送孫百篇遊天台', '送孫百篇游天台', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["東南雲路落斜行，入樹穿村見赤城。","遠近常時皆藥氣，高低無處不泉聲。","映巖日向牀頭沒，濕燭雲從柱底生。","更有仙花與靈鳥，恐君多半未知名。"]', '["东南云路落斜行，入樹穿村见赤城。","远近常时皆藥氣，高低無处不泉声。","映巖日向牀头沒，濕燭云從柱底生。","更有仙花與靈鸟，恐君多半未知名。"]', '诗', 'shi', '', NULL, '送孫百篇遊天台 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57cfd391-5a1e-4f1d-94c3-71ebbda5b2fd', '陸山人畫水', '陸山人畫水', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["毫末用功成一水，水源山脉固難尋。","逡巡便可見波浪，咫尺不能知淺深。","但有片雲生海口，終無明月在潭心。","我來擬學磻溪叟，白首釣璜非陸沈。"]', '["毫末用功成一水，水源山脉固难尋。","逡巡便可见波浪，咫尺不能知淺深。","但有片云生海口，終無明月在潭心。","我来擬学磻溪叟，白首釣璜非陸沈。"]', '诗', 'shi', '', NULL, '陸山人畫水 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a121fdb-d28e-4d93-9aac-1667466c2aea', '郭中山居', '郭中山居', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["莫見一瓢離樹上，猶須四壁在林間。","沈吟不寐先聞角，屈曲登高自有山。","濺石迸泉聽未足，亞窗紅果臥堪攀。","公卿若便遺名姓，却與禽魚作往還。"]', '["莫见一瓢離樹上，猶須四壁在林间。","沈吟不寐先闻角，屈曲登高自有山。","濺石迸泉听未足，亞窗紅果臥堪攀。","公卿若便遺名姓，却與禽鱼作往還。"]', '诗', 'shi', '', NULL, '郭中山居 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22771bdf-fd40-465e-8f76-5addfa25ba95', '雪中寄李知誨判官', '雪中寄李知誨判官', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["聚散聯翩急復遲，解將華髪兩相欺。","雖云竹重先藏路，却訝巢傾不損枝。","入戶便從風起後，照窗翻似月明時。","此時門巷無行跡，塵滿尊罍誰得知。"]', '["聚散聯翩急复遲，解將华髪兩相欺。","雖云竹重先藏路，却訝巢傾不損枝。","入戶便從风起後，照窗翻似月明时。","此时门巷無行跡，塵满尊罍誰得知。"]', '诗', 'shi', '', NULL, '雪中寄李知誨判官 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d9ec426-8ef2-438a-bde2-72fa9fdbb615', '途中言事寄居遠上人', '途中言事寄居远上人', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["舉目時時似故園，鄉心自動向誰言。","白雲曉濕寒山寺，紅葉夜飛明月村。","震澤風帆歸橘岸，錢塘水府抵城根。","羨師了達無牽束，竹徑生苔掩竹門。"]', '["舉目时时似故园，乡心自动向誰言。","白云晓濕寒山寺，紅葉夜飞明月村。","震澤风帆归橘岸，錢塘水府抵城根。","羨師了達無牽束，竹徑生苔掩竹门。"]', '诗', 'shi', '', NULL, '途中言事寄居遠上人 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfa7f9e0-9a85-4346-b652-907c8b520ee0', '雪中寄薛郎中', '雪中寄薛郎中', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["野禽未覺巢枝仄，稚子先憂徑竹摧。","半夜忽明非月午，前庭旋釋被春摧。","碎花若入樽中去，清氣應歸筆底來。","深擁紅爐聽仙樂，忍教愁坐畫寒灰。"]', '["野禽未覺巢枝仄，稚子先憂徑竹摧。","半夜忽明非月午，前庭旋釋被春摧。","碎花若入樽中去，清氣應归笔底来。","深擁紅爐听仙乐，忍教愁坐畫寒灰。"]', '诗', 'shi', '', NULL, '雪中寄薛郎中 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b31b6c47-50de-4e78-ae7d-8320d89688b9', '題盛令新亭', '題盛令新亭', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["舉目豈知新智慧，存思便是小天台。","偶嘗嘉果求枝去，因問名花寄種來。","春物誘才歸健筆，夜歌牽醉入叢杯。","此中難遇逍遙事，計日應爲印綬催。"]', '["舉目豈知新智慧，存思便是小天台。","偶嘗嘉果求枝去，因问名花寄種来。","春物誘才归健笔，夜歌牽醉入叢杯。","此中难遇逍遙事，計日應爲印綬催。"]', '诗', 'shi', '', NULL, '題盛令新亭 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a50192e-1ba5-42dd-81e4-b2c1dd53464f', '贈鄭仁規', '贈鄭仁規', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["一石雄才獨占難，應分二斗借人寰。","澄心不出風騷外，落筆全歸教化間。","蓮幕未來須更聘，桂枝纔去即先攀。","可憐麗句能飛動，荀宋精靈亦厚顏。"]', '["一石雄才独占难，應分二斗借人寰。","澄心不出风騷外，落笔全归教化间。","蓮幕未来須更聘，桂枝纔去即先攀。","可怜丽句能飞动，荀宋精靈亦厚顏。"]', '诗', 'shi', '', NULL, '贈鄭仁規 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c409a740-82cd-4ef4-90c5-c67a1e8eafae', '送縉陵王少府赴舉', '送縉陵王少府赴舉', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["相看不忍盡離觴，五兩牽風速去檣。","遠驛新砧應弄月，初程殘角未吹霜。","越山直下分吳苑，淮水橫流入楚鄉。","珍重郄家好兄弟，明年祿位在何方。"]', '["相看不忍尽離觴，五兩牽风速去檣。","远驛新砧應弄月，初程殘角未吹霜。","越山直下分吳苑，淮水橫流入楚乡。","珍重郄家好兄弟，明年祿位在何方。"]', '诗', 'shi', '', NULL, '送縉陵王少府赴舉 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c91ff71-32c5-4a44-ad8b-854196ce3eee', '路入剡中作', '路入剡中作', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["截灣衝瀨片帆通，高枕微吟到剡中。","掠草並飛憐燕子，停橈獨飲學漁翁。","波濤漫撼長潭月，楊柳斜牽一岸風。","便擬乘槎應去得，仙源直恐接星東。"]', '["截灣衝瀨片帆通，高枕微吟到剡中。","掠草並飞怜燕子，停橈独饮学漁翁。","波濤漫撼长潭月，楊柳斜牽一岸风。","便擬乘槎應去得，仙源直恐接星东。"]', '诗', 'shi', '', NULL, '路入剡中作 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52c21623-9b05-4e06-8935-c7a398165efb', '東山瀑布', '东山瀑布', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["遙夜看來疑月照，平明失去被雲迷。","掛巖遠勢穿松島，擊石殘聲注稻畦。","素色噴成三伏雪，餘波流作萬年溪。","不緣真宰能開決，應向前山雜淤泥。"]', '["遙夜看来疑月照，平明失去被云迷。","掛巖远勢穿松島，擊石殘声注稻畦。","素色噴成三伏雪，餘波流作万年溪。","不緣真宰能开決，應向前山杂淤泥。"]', '诗', 'shi', '', NULL, '東山瀑布 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25bb5111-e17f-4d19-b261-56f76b78714e', '水墨松石', '水墨松石', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["三世精能舉世無，筆端狼籍見功夫。","添來勢逸陰崖黑，潑處痕輕灌木枯。","垂地寒雲吞大漠，過江春雨入全吳。","蘭堂坐久心彌惑，不道山川是畫圖。"]', '["三世精能舉世無，笔端狼籍见功夫。","添来勢逸陰崖黑，潑处痕轻灌木枯。","垂地寒云吞大漠，過江春雨入全吳。","蘭堂坐久心彌惑，不道山川是畫圖。"]', '诗', 'shi', '', NULL, '水墨松石 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6781e418-606e-4b83-8d29-211ccc36fc9d', '獻浙東王大夫二首 一', '獻浙东王大夫二首 一', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["出鎮當時移越俗，致君何日不堯年。","到來唯飲長溪水，歸去應將一箇錢。","吟處美人擎筆硯，行時飛鳥避旌旃。","四方皆是分憂寄，獨有東南戴二天。"]', '["出鎮當时移越俗，致君何日不堯年。","到来唯饮长溪水，归去應將一箇錢。","吟处美人擎笔硯，行时飞鸟避旌旃。","四方皆是分憂寄，独有东南戴二天。"]', '诗', 'shi', '', NULL, '獻浙東王大夫二首 一 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('daf469bc-99b3-4c76-b482-3ff3be76eaf5', '獻浙東王大夫二首 二', '獻浙东王大夫二首 二', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["王臣夷夏仰清名，領鎮猶爲失意行。","已見玉璜曾上釣，何愁金鼎不和羹。","譽將星月同時朽，身應山河滿數生。","泥滓雲霄至懸闊，漁翁不合見公卿。"]', '["王臣夷夏仰清名，領鎮猶爲失意行。","已见玉璜曾上釣，何愁金鼎不和羹。","譽將星月同时朽，身應山河满數生。","泥滓云霄至懸闊，漁翁不合见公卿。"]', '诗', 'shi', '', NULL, '獻浙東王大夫二首 二 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a8c87d6-dc85-4c20-8cd6-6155a1c5cadb', '越州使院竹', '越州使院竹', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["莫見凌風飄粉籜，須知礙石作盤根。","細看枝上蟬吟處，猶是筍時蟲蝕痕。","月送綠陰斜上砌，露凝寒色濕遮門。","列仙終日逍遙地，鳥雀潛來不敢喧。"]', '["莫见凌风飄粉籜，須知礙石作盤根。","細看枝上蟬吟处，猶是筍时蟲蝕痕。","月送綠陰斜上砌，露凝寒色濕遮门。","列仙終日逍遙地，鸟雀潛来不敢喧。"]', '诗', 'shi', '', NULL, '越州使院竹 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f71ae393-d0dc-4627-9ee8-ac96bca1b2be', '題贈李校書', '題贈李校书', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["名場失手一年年，月桂嘗聞到手邊。","誰道高情偏似鶴，自云長嘯不如蟬。","衆花交豔多成實，深井通潮半雜泉。","却是偶然行未到，元來有路上寥天。"]', '["名場失手一年年，月桂嘗闻到手邊。","誰道高情偏似鹤，自云长嘯不如蟬。","衆花交豔多成實，深井通潮半杂泉。","却是偶然行未到，元来有路上寥天。"]', '诗', 'shi', '', NULL, '題贈李校書 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47943bb7-7c60-42ef-bea0-ef8d40d98c88', '送王侍郎浙東入朝', '送王侍郎浙东入朝', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["自將苦節酬清秩，肯要龐眉一箇錢。","恩愛已蘇句踐國，程途却上大羅天。","魚池菊島還公署，沙鶴松栽入畫船。","密奏無非經濟術，從容幾刻在爐煙。"]', '["自將苦節酬清秩，肯要龐眉一箇錢。","恩愛已蘇句踐国，程途却上大羅天。","鱼池菊島還公署，沙鹤松栽入畫船。","密奏無非經濟術，從容幾刻在爐煙。"]', '诗', 'shi', '', NULL, '送王侍郎浙東入朝 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac11e601-295a-4b3c-81e9-70baeebccb82', '贈黃處士', '贈黄处士', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["閉戶先生無是非，竹灣松樹藕苗衣。","愁吟密雪思難盡，醉倒殘花扶不歸。","若出薜蘿迎鶴簡，應拋舴艋別漁磯。","到頭苦節終何益，空改文星作少微。"]', '["閉戶先生無是非，竹灣松樹藕苗衣。","愁吟密雪思难尽，醉倒殘花扶不归。","若出薜蘿迎鹤簡，應拋舴艋別漁磯。","到头苦節終何益，空改文星作少微。"]', '诗', 'shi', '', NULL, '贈黃處士 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b656af9-c728-48b8-861d-8badf693c1c1', '獻王大夫二首 一', '獻王大夫二首 一', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["都緣聲價振皇州，高臥中條不自由。","早副急徵來鳳沼，常陪內宴醉龍樓。","鏘金五字能援筆，釣玉三年信直鉤。","必恐借留終不遂，越人相顧已先愁。"]', '["都緣声價振皇州，高臥中條不自由。","早副急徵来鳳沼，常陪內宴醉龙楼。","鏘金五字能援笔，釣玉三年信直鉤。","必恐借留終不遂，越人相顧已先愁。"]', '诗', 'shi', '', NULL, '獻王大夫二首 一 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb9f4fa3-6155-408c-9b43-d1e06146bc24', '獻王大夫二首 二', '獻王大夫二首 二', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["功成猶自更行春，塞路旌旗十里塵。","只用篇章爲教化，不知夷夏望陶鈞。","金章照耀浮光動，玉面生獰細步勻。","歷任聖朝清峻地，至今依是少年身。"]', '["功成猶自更行春，塞路旌旗十里塵。","只用篇章爲教化，不知夷夏望陶鈞。","金章照耀浮光动，玉面生獰細步勻。","歷任聖朝清峻地，至今依是少年身。"]', '诗', 'shi', '', NULL, '獻王大夫二首 二 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81e7315e-6bd3-47fe-9476-00949dfe7005', '贈五牙山人洗修白', '贈五牙山人洗修白', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["變通唯在片時間，此事全由一粒丹。","若取壽長延至易，如嫌地遠縮何難。","先生闊別能輕舉，弟子纔來學不飡。","篋裏生塵是閑藥，外沾猶可救衰殘。"]', '["变通唯在片时间，此事全由一粒丹。","若取壽长延至易，如嫌地远縮何难。","先生闊別能轻舉，弟子纔来学不飡。","篋裏生塵是闲藥，外沾猶可救衰殘。"]', '诗', 'shi', '', NULL, '贈五牙山人洗修白 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8c32c2f-4e73-4bdb-8006-cfb592495ff3', '處州獻盧員外', '处州獻盧員外', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["纔下軺車即歲豐，方知盛德與天通。","清聲漸出寰瀛外，喜氣全歸教化中。","落地遺金終日在，經年滯獄當時空。","直緣後學無功業，不慮文翁不至公。"]', '["纔下軺车即歲豐，方知盛德與天通。","清声漸出寰瀛外，喜氣全归教化中。","落地遺金終日在，經年滯獄當时空。","直緣後学無功業，不慮文翁不至公。"]', '诗', 'shi', '', NULL, '處州獻盧員外 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2c33488-8414-4cc6-bbad-058da1e31f1a', '石門瀑布', '石门瀑布', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["奔傾漱石亦噴苔，此是便隨元化來。","長片掛巖輕似練，遠聲離洞咽於雷。","氣含松桂千枝潤，勢畫雲霞一道開。","直是銀河分派落，兼聞碎滴濺天台。"]', '["奔傾漱石亦噴苔，此是便隨元化来。","长片掛巖轻似練，远声離洞咽於雷。","氣含松桂千枝潤，勢畫云霞一道开。","直是銀河分派落，兼闻碎滴濺天台。"]', '诗', 'shi', '', NULL, '石門瀑布 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('135370e8-2d7a-41b6-8305-1ec998217c18', '題仙巖瀑布呈陳明府', '題仙巖瀑布呈陳明府', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["方知激蹙與噴飛，直恐古今同一時。","遠壑流來多石脉，寒空撲碎作凌澌。","謝公巖上衝雲去，織女星邊落地遲。","聚向山前更誰測，深沈見底是澄漪。"]', '["方知激蹙與噴飞，直恐古今同一时。","远壑流来多石脉，寒空撲碎作凌澌。","謝公巖上衝云去，织女星邊落地遲。","聚向山前更誰測，深沈见底是澄漪。"]', '诗', 'shi', '', NULL, '題仙巖瀑布呈陳明府 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2533784d-65c8-4d14-9d24-41aa4fb5d0ab', '贈山陰崔明府', '贈山陰崔明府', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["用心何況兩衙間，退食孜孜亦不閑。","壓酒曬書猶檢點，修琴取藥似交關。","笙歌入夜舟中月，花木知春縣裏山。","平叔正堪湯餅試，風流不合問年顏。"]', '["用心何況兩衙间，退食孜孜亦不闲。","壓酒曬书猶檢点，修琴取藥似交关。","笙歌入夜舟中月，花木知春縣裏山。","平叔正堪湯餅試，风流不合问年顏。"]', '诗', 'shi', '', NULL, '贈山陰崔明府 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e83bad8-4fc4-4e9f-9d7b-5be373a9a4f9', '山井', '山井', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["灩灩濕光凌竹樹，寥寥清氣襲衣襟。","不知測穴通潮信，却訝輕漣動鏡心。","夜久即疑星影過，早來猶見石痕深。","轆轤用智終何益，抱甕遺名亦至今。"]', '["灩灩濕光凌竹樹，寥寥清氣襲衣襟。","不知測穴通潮信，却訝轻漣动镜心。","夜久即疑星影過，早来猶见石痕深。","轆轤用智終何益，抱甕遺名亦至今。"]', '诗', 'shi', '', NULL, '山井 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b63aee2-eff3-45ff-a1b9-b40464bf0c3c', '偶作', '偶作', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["直爲篇章非動衆，遂令軒蓋不經過。","未妨溪上泛漁艇，又爲門前張雀羅。","夜學事須憑雪照，朝廚爭奈絕煙何。","若於巖洞求倫類，今古疎愚似我多。"]', '["直爲篇章非动衆，遂令軒蓋不經過。","未妨溪上泛漁艇，又爲门前張雀羅。","夜学事須憑雪照，朝廚爭奈絕煙何。","若於巖洞求倫類，今古疎愚似我多。"]', '诗', 'shi', '', NULL, '偶作 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4993e83-70b4-47e9-8541-b25e2d7be8c8', '賊退後贈劉將軍', '賊退後贈劉將軍', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["非唯吳起與穰苴，今古推排盡不如。","白馬知無髀上肉，黃巾泣向箭頭書。","二年戰地成桑茗，千里荒榛作比閭。","功業更多身轉貴，佇看幢節引戎車。"]', '["非唯吳起與穰苴，今古推排尽不如。","白马知無髀上肉，黄巾泣向箭头书。","二年戰地成桑茗，千里荒榛作比閭。","功業更多身轉貴，佇看幢節引戎车。"]', '诗', 'shi', '', NULL, '賊退後贈劉將軍 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14a97b0b-a66b-421a-ab79-6955ebe37729', '感時三首 一', '感时三首 一', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["不覺年華似箭流，朝看春色暮逢秋。","正嗟新塚垂青草，便見故交梳白頭。","雖道了然皆是夢，應還達者即無愁。","破除生死須齊物，誰向穹蒼問事由。"]', '["不覺年华似箭流，朝看春色暮逢秋。","正嗟新塚垂青草，便见故交梳白头。","雖道了然皆是梦，應還達者即無愁。","破除生死須齊物，誰向穹蒼问事由。"]', '诗', 'shi', '', NULL, '感時三首 一 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d75584fb-20ad-45ff-8bb9-838ff3378ee4', '感時三首 二', '感时三首 二', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["日烏往返無休息，朝出扶桑暮却迴。","夜雨旋驅殘熱去，江風吹送早寒來。","纔憐飲處飛花片，又見書邊聚雪堆。","莫恃少年欺白首，須臾還被老相催。"]', '["日烏往返無休息，朝出扶桑暮却迴。","夜雨旋驱殘熱去，江风吹送早寒来。","纔怜饮处飞花片，又见书邊聚雪堆。","莫恃少年欺白首，須臾還被老相催。"]', '诗', 'shi', '', NULL, '感時三首 二 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ee23327-cced-451e-a830-57d6b05074f8', '感時三首 三', '感时三首 三', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["世途擾擾復憧憧，真恐華夷事亦同。","歲月自消寒暑內，榮枯盡在是非中。","今朝猶作青襟子，明日還成白首翁。","堪笑愚夫足紛競，不知流水去無窮。"]', '["世途擾擾复憧憧，真恐华夷事亦同。","歲月自消寒暑內，榮枯尽在是非中。","今朝猶作青襟子，明日還成白首翁。","堪笑愚夫足紛競，不知流水去無窮。"]', '诗', 'shi', '', NULL, '感時三首 三 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28fbc11a-a99f-4d75-a8db-fa33eaa8cc7c', '牡丹', '牡丹', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["不逢盛暑不衝寒，種子成叢用法難。","醉眼若爲拋去得，狂心更擬折來看。","凌霜烈火吹無豔，裛露陰霞曬不乾。","莫道嬌紅怕風雨，經時猶自未凋殘。"]', '["不逢盛暑不衝寒，種子成叢用法难。","醉眼若爲拋去得，狂心更擬折来看。","凌霜烈火吹無豔，裛露陰霞曬不乾。","莫道嬌紅怕风雨，經时猶自未凋殘。"]', '诗', 'shi', '', NULL, '牡丹 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42d8f044-8f43-45ea-9e11-0ae1cfbfd29d', '贈進士章碣', '贈進士章碣', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["織錦雖云用舊機，抽梭起樣更新奇。","何如且破望中葉，未可便攀低處枝。","藉地落花春半後，打窗斜雪夜深時。","此時才子吟應苦，吟苦鬼神知不知。"]', '["织錦雖云用旧機，抽梭起樣更新奇。","何如且破望中葉，未可便攀低处枝。","藉地落花春半後，打窗斜雪夜深时。","此时才子吟應苦，吟苦鬼神知不知。"]', '诗', 'shi', '', NULL, '贈進士章碣 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e18cb48-d173-479a-9456-c07e99cccc8a', '與桐廬鄭明府', '與桐廬鄭明府', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["字人心苦達神明，何止重門夜不扃。","莫道耕田全種秫，兼聞退食亦逢星。","暎林顧兔停琴望，隔水寒猨駐筆聽。","却恐南山盡無石，南山有石合爲銘。"]', '["字人心苦達神明，何止重门夜不扃。","莫道耕田全種秫，兼闻退食亦逢星。","暎林顧兔停琴望，隔水寒猨駐笔听。","却恐南山尽無石，南山有石合爲銘。"]', '诗', 'shi', '', NULL, '與桐廬鄭明府 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7e428bf-ccee-4e12-8a28-ddaacfede756', '謝王大夫奏表', '謝王大夫奏表', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["非唯言下變榮衰，大海可傾山可移。","如剖夜光歸暗室，似驅春氣入寒枝。","死灰到底翻騰焰，朽骨隨頭却長肥。","便殺微躬復何益，生成恩重報無期。"]', '["非唯言下变榮衰，大海可傾山可移。","如剖夜光归暗室，似驱春氣入寒枝。","死灰到底翻腾焰，朽骨隨头却长肥。","便殺微躬复何益，生成恩重報無期。"]', '诗', 'shi', '', NULL, '謝王大夫奏表 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('837f3760-286c-44d8-b78e-9978ebad20f7', '送道人歸舊巖', '送道人归旧巖', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["舊巖終副却歸期，巖下有人應識師。","目覩嬰孩成老叟，手栽松柏有枯枝。","前山低校無多地，東海淺於初去時。","若把古今相比類，姓丁仙鶴亦如斯。"]', '["旧巖終副却归期，巖下有人應識師。","目覩嬰孩成老叟，手栽松柏有枯枝。","前山低校無多地，东海淺於初去时。","若把古今相比類，姓丁仙鹤亦如斯。"]', '诗', 'shi', '', NULL, '送道人歸舊巖 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a014c5b0-bcea-4487-8d09-07befe112cbf', '送錢特卿赴職天台', '送錢特卿赴職天台', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["路入仙溪氣象清，垂鞭樹石罅中行。","霧昏不見西陵岸，風急先聞瀑布聲。","山下縣寮張樂送，海邊津吏棹舟迎。","詩家弟子無多少，唯只於余別有情。"]', '["路入仙溪氣象清，垂鞭樹石罅中行。","霧昏不见西陵岸，风急先闻瀑布声。","山下縣寮張乐送，海邊津吏棹舟迎。","诗家弟子無多少，唯只於余別有情。"]', '诗', 'shi', '', NULL, '送錢特卿赴職天台 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa7b4e61-d84b-4c84-836f-869cfff353f6', '題新竹', '題新竹', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["青苔斸破植貞堅，細碧竿排鬱眼鮮。","小鳳凰聲吹嫩葉，短蛟龍尾褭輕煙。","節環膩色端勻粉，根拔秋光暗長鞭。","怪得入門肌骨冷，綴風黏月滿庭前。"]', '["青苔斸破植貞堅，細碧竿排鬱眼鲜。","小鳳凰声吹嫩葉，短蛟龙尾褭轻煙。","節环膩色端勻粉，根拔秋光暗长鞭。","怪得入门肌骨冷，綴风黏月满庭前。"]', '诗', 'shi', '', NULL, '題新竹 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c0c764a-86af-48ba-99c1-8732ed9df4d0', '哭王大夫', '哭王大夫', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["俗人皆嫉謝臨川，果中常情□□□。","爲政舊規方利國，降生直性已歸天。","峴亭惋咽知無極，渭曲馨香莫計年。","從此心喪應畢世，忍看墳草讀殘篇。"]', '["俗人皆嫉謝臨川，果中常情□□□。","爲政旧規方利国，降生直性已归天。","峴亭惋咽知無極，渭曲馨香莫計年。","從此心喪應畢世，忍看墳草读殘篇。"]', '诗', 'shi', '', NULL, '哭王大夫 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cd567ae-d63b-4532-b079-d7f6ca0d3cf8', '贈乾素上人', '贈乾素上人', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["苦用貞心傳弟子，即應低眼看公卿。","水中明月無踪跡，風裏浮雲可計程。","庭際孤松隨鶴立，窗間清磬學蟬鳴。","料師多刦長如此，豈筭前生與後生。"]', '["苦用貞心傳弟子，即應低眼看公卿。","水中明月無踪跡，风裏浮云可計程。","庭際孤松隨鹤立，窗间清磬学蟬鳴。","料師多刦长如此，豈筭前生與後生。"]', '诗', 'shi', '', NULL, '贈乾素上人 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1df388d-698e-4896-a337-107d0bb06714', '題應天寺上方兼呈謙上人', '題應天寺上方兼呈謙上人', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["中天坐臥見人寰，峭石垂藤不易攀。","晴卷風雷歸故壑，夜和猿鳥鎖寒山。","勢橫綠野蒼茫外，影落平湖瀲灩間。","師在西巖最高處，路尋之字見禪關。"]', '["中天坐臥见人寰，峭石垂藤不易攀。","晴卷风雷归故壑，夜和猿鸟鎖寒山。","勢橫綠野蒼茫外，影落平湖瀲灩间。","師在西巖最高处，路尋之字见禪关。"]', '诗', 'shi', '', NULL, '題應天寺上方兼呈謙上人 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c431add-bbd2-43f3-83fc-1dd24c527037', '題法華寺絕頂禪家壁', '題法华寺絕頂禪家壁', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["蒼翠岧嶤逼窅冥，下方雷雨上方晴。","飛流便向砌邊挂，片月影從窗外行。","馴鹿不知誰結侶，野禽都是自呼名。","只應禪者無來去，坐看千山白髮生。"]', '["蒼翠岧嶤逼窅冥，下方雷雨上方晴。","飞流便向砌邊挂，片月影從窗外行。","馴鹿不知誰結侶，野禽都是自呼名。","只應禪者無来去，坐看千山白髮生。"]', '诗', 'shi', '', NULL, '題法華寺絕頂禪家壁 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63fcdb63-3899-45d8-a774-7db18bd01156', '春日', '春日', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["春去春來似有期，日高添睡是歸時。","雖將細雨催蘆笋，却用東風染柳絲。","重霧已應吞海色，輕霜猶自剉花枝。","此時野客因花醉，醉臥花間應不知。"]', '["春去春来似有期，日高添睡是归时。","雖將細雨催蘆笋，却用东风染柳絲。","重霧已應吞海色，轻霜猶自剉花枝。","此时野客因花醉，醉臥花间應不知。"]', '诗', 'shi', '', NULL, '春日 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f08bc9e1-6822-4492-8b75-91302a40e3ee', '上越州楊嚴中丞', '上越州楊嚴中丞', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["連枝棣萼世無雙，未秉鴻鈞擁大邦。","折桂早聞推獨步，分憂暫輟過重江。","晴尋鳳沼雲中樹，思遶稽山枕上窗。","試把十年辛苦志，問津求拜碧油幢。"]', '["連枝棣萼世無雙，未秉鴻鈞擁大邦。","折桂早闻推独步，分憂暫輟過重江。","晴尋鳳沼云中樹，思遶稽山枕上窗。","試把十年辛苦志，问津求拜碧油幢。"]', '诗', 'shi', '', NULL, '上越州楊嚴中丞 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29cf0e3c-8138-43a5-9d2a-e42b5591e3c9', '月', '月', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["桂輪秋半出東方，巢鵲驚飛夜未央。","海上風雲搖皓影，空中露氣濕流光。","斜臨戶牖通宵燭，迴照堦墀到曉霜。","庾亮恃才高更逸，方聞墨翰已成章。"]', '["桂輪秋半出东方，巢鵲驚飞夜未央。","海上风云搖皓影，空中露氣濕流光。","斜臨戶牖通宵燭，迴照堦墀到晓霜。","庾亮恃才高更逸，方闻墨翰已成章。"]', '诗', 'shi', '', NULL, '月 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf019d08-f1c8-4368-8c5e-f924caa36589', '早春', '早春', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["運行元化不參差，四極中華共一時。","正氣纔隨灰律變，殘寒便被柳條欺。","冰融大澤朝陽覺，草綠陳根夜雨知。","不信風光疾於箭，年來年去變霜髭。"]', '["運行元化不參差，四極中华共一时。","正氣纔隨灰律变，殘寒便被柳條欺。","冰融大澤朝陽覺，草綠陳根夜雨知。","不信风光疾於箭，年来年去变霜髭。"]', '诗', 'shi', '', NULL, '早春 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f001479c-4b58-402c-a966-d8a6209bc9f6', '對花', '对花', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["清曉入花如步障，戀花行步步遲遲。","含風欲綻中心朵，似火應燒外面枝。","野客須𢬵終日醉，流鶯自有隔年期。","使君坐處笙歌合，便是列仙身不知。"]', '["清晓入花如步障，戀花行步步遲遲。","含风欲綻中心朵，似火應燒外面枝。","野客須𢬵終日醉，流鶯自有隔年期。","使君坐处笙歌合，便是列仙身不知。"]', '诗', 'shi', '', NULL, '對花 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fde664e8-2d5a-47e4-aa2b-7fd3e07b6780', '除夜', '除夜', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["玉漏斯須即達晨，四時吹轉任風輪。","寒燈短燼方燒臘，畫角殘聲已報春。","明日便爲經歲客，昨朝猶是少年人。","新正定數隨年減，浮世惟應百遍新。"]', '["玉漏斯須即達晨，四时吹轉任风輪。","寒灯短燼方燒臘，畫角殘声已報春。","明日便爲經歲客，昨朝猶是少年人。","新正定數隨年減，浮世惟應百遍新。"]', '诗', 'shi', '', NULL, '除夜 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd31e801-564c-4e56-b29e-29e546344153', '題松江驛', '題松江驛', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["便向中流出太陽，兼疑大岸逼浮桑。","門前白道通丹闕，浪裏青山占幾鄉。","帆勢落斜依浦溆，鐘聲斷續在滄茫。","古今悉不知天意，偏把雲霞媚一方。"]', '["便向中流出太陽，兼疑大岸逼浮桑。","门前白道通丹闕，浪裏青山占幾乡。","帆勢落斜依浦溆，鐘声斷續在滄茫。","古今悉不知天意，偏把云霞媚一方。"]', '诗', 'shi', '', NULL, '題松江驛 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cdd5f0b-21e1-45fb-b992-6038553b91eb', '思桐廬舊居便送鑒上人', '思桐廬旧居便送鑒上人', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["莫道東南路不賒，思歸一步是天涯。","林中夜半雙臺月，洲上春深九里花。","綠樹遶村含細雨，寒潮背郭卷平沙。","聞師却到鄉中去，爲我殷勤謝酒家。"]', '["莫道东南路不賒，思归一步是天涯。","林中夜半雙台月，洲上春深九里花。","綠樹遶村含細雨，寒潮背郭卷平沙。","闻師却到乡中去，爲我殷勤謝酒家。"]', '诗', 'shi', '', NULL, '思桐廬舊居便送鑒上人 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c55cafae-4be4-43f2-a912-d07559c60add', '送僧歸日本', '送僧归日本', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["四極雖云共二儀，晦明前後即難知。","西方尚在星辰下，東域已過寅卯時。","大海浪中分國界，扶桑樹底是天涯。","滿帆若有歸風便，到岸猶須隔歲期。"]', '["四極雖云共二儀，晦明前後即难知。","西方尚在星辰下，东域已過寅卯时。","大海浪中分国界，扶桑樹底是天涯。","满帆若有归风便，到岸猶須隔歲期。"]', '诗', 'shi', '', NULL, '送僧歸日本 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7462818-fd04-4963-8a97-10859ebbeefc', '寧國寺', '寧国寺', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["深僻孤高無四鄰，白雲明月自相親。","海中日出山先曉，世上寒輕谷未春。","窗逼野溪聞唳鶴，林通村徑見樵人。","此時惟有雷居士，不厭[籃]輿去住頻。"]', '["深僻孤高無四鄰，白云明月自相親。","海中日出山先晓，世上寒轻谷未春。","窗逼野溪闻唳鹤，林通村徑见樵人。","此时惟有雷居士，不厭[籃]輿去住頻。"]', '诗', 'shi', '', NULL, '寧國寺 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00dca69f-cc9e-4cbe-bcc3-ec039a9728b6', '山中寄吳磻十韻', '山中寄吳磻十韻', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["莫問終休否，林中事已成。","盤餐憐火種，歲計付刀耕。","掬水皆花氣，聽松似雨聲。","書空翹足臥，避險側身行。","果傍閑軒落，蒲連濕岸生。","禪生知見理，妻子笑無名。","更擬教詩苦，何曾待酒清。","石溪魚不大，月樹鵲多驚。","砌下通樵路，窗間見縣城。","雲山任重疊，難隔故交情。"]', '["莫问終休否，林中事已成。","盤餐怜火種，歲計付刀耕。","掬水皆花氣，听松似雨声。","书空翹足臥，避險側身行。","果傍闲軒落，蒲連濕岸生。","禪生知见理，妻子笑無名。","更擬教诗苦，何曾待酒清。","石溪鱼不大，月樹鵲多驚。","砌下通樵路，窗间见縣城。","云山任重叠，难隔故交情。"]', '诗', 'shi', '', NULL, '山中寄吳磻十韻 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca4393f5-a5de-45ed-85f7-561572886837', '嘉興縣內池閣', '嘉兴縣內池閣', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["指畫應心成，周迴氣象清。","牀前沙鳥語，案下錦鱗驚。","細柳風吹旋，新荷露壓傾。","微芳緣岸落，迸笋入波生。","舴艋舟中醉，莓苔徑上行。","高人莫歸去，此處勝蓬瀛。"]', '["指畫應心成，周迴氣象清。","牀前沙鸟語，案下錦鱗驚。","細柳风吹旋，新荷露壓傾。","微芳緣岸落，迸笋入波生。","舴艋舟中醉，莓苔徑上行。","高人莫归去，此处勝蓬瀛。"]', '诗', 'shi', '', NULL, '嘉興縣內池閣 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7900b5e8-5fc0-4896-a1ee-86ec2d0e2721', '鏡湖西島言事寄陶校書', '镜湖西島言事寄陶校书', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["樵獵兩三戶，凋疎是近鄰。","風雷前壑雨，花木後嵒春。","文字不得力，桑麻難救貧。","山禽欺稚子，夜犬吠漁人。","未必聖明代，長將雲水親。","知音不延薦，何路出泥塵。"]', '["樵獵兩三戶，凋疎是近鄰。","风雷前壑雨，花木後嵒春。","文字不得力，桑麻难救貧。","山禽欺稚子，夜犬吠漁人。","未必聖明代，长將云水親。","知音不延薦，何路出泥塵。"]', '诗', 'shi', '', NULL, '鏡湖西島言事寄陶校書 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c7c0898-c714-43b6-8b60-5731f538bbd6', '贈趙崇侍御', '贈趙崇侍御', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["貴達合逢明聖日，風流又及少年時。","才因出衆人皆嫉，勢欲摩霄自不知。","正直早年聞苦節，從容此日見清規。","却教鸚鵡呼桃葉，便遣嬋娟唱竹枝。","閑話篇章停燭久，醉迷歌舞出花遲。","雲鴻別有回翔便，應笑啁啾燕雀卑。"]', '["貴達合逢明聖日，风流又及少年时。","才因出衆人皆嫉，勢欲摩霄自不知。","正直早年闻苦節，從容此日见清規。","却教鸚鵡呼桃葉，便遣嬋娟唱竹枝。","闲話篇章停燭久，醉迷歌舞出花遲。","云鴻別有回翔便，應笑啁啾燕雀卑。"]', '诗', 'shi', '', NULL, '贈趙崇侍御 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c40f8d04-5d8e-4d1e-8176-41c8af345470', '敘龍瑞觀勝異寄于尊師', '敘龙瑞观勝異寄于尊師', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["混元融結致功難，山下平湖湖上山。","萬傾涵虛寒瀲灩，千尋聳翠秀孱顏。","芰荷香入琴棊處，雷雨聲離棟牖間。","但有五雲依鶴嶺，曾無陸路向人寰。","夜溪漱玉常堪聽，仙樹垂珠可要攀。","若棄榮名便居此，自然浮濁不相關。"]', '["混元融結致功难，山下平湖湖上山。","万傾涵虛寒瀲灩，千尋聳翠秀孱顏。","芰荷香入琴棊处，雷雨声離棟牖间。","但有五云依鹤嶺，曾無陸路向人寰。","夜溪漱玉常堪听，仙樹垂珠可要攀。","若棄榮名便居此，自然浮濁不相关。"]', '诗', 'shi', '', NULL, '敘龍瑞觀勝異寄于尊師 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98dc34a9-2116-4899-b68b-1ae883ea90df', '侯郎中新置西湖', '侯郎中新置西湖', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["遠近利民因智力，周迴潤物像心源。","菰蒲縱感生成惠，鱣鮪那占廣大恩。","瀲灩清輝吞半郭，縈紆別派入遙村。","砂泉遶石通山脈，岸木黏萍是浪痕。","已見澄來連鏡底，兼知極處浸雲根。","波濤不起時方泰，舟檝徐行日易昏。","煙霧未應藏島嶼，鳧鷖亦解避旌旛。","雖云桃葉歌還醉，却被荷花笑不言。","孤鶴必應思鳳詔，凡魚豈合在龍門。","能將盛事添元化，一夕機謨萬古存。"]', '["远近利民因智力，周迴潤物像心源。","菰蒲縱感生成惠，鱣鮪那占廣大恩。","瀲灩清輝吞半郭，縈紆別派入遙村。","砂泉遶石通山脈，岸木黏萍是浪痕。","已见澄来連镜底，兼知極处浸云根。","波濤不起时方泰，舟檝徐行日易昏。","煙霧未應藏島嶼，鳧鷖亦解避旌旛。","雖云桃葉歌還醉，却被荷花笑不言。","孤鹤必應思鳳詔，凡鱼豈合在龙门。","能將盛事添元化，一夕機謨万古存。"]', '诗', 'shi', '', NULL, '侯郎中新置西湖 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('648f33a4-c11c-47f9-a0c1-c78ee40fe788', '許員外新陽別業', '許員外新陽別業', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["蘭汀橘島映亭臺，不是經心即手栽。","滿閣白雲隨雨去，一池寒月逐潮來。","小松出屋和巢長，新逕通村避笋開。","柳絮風前欹枕臥，荷花香裏棹舟迴。","園中認葉封林草，簷下攀枝落野梅。","莫恣高情求逸思，須防急詔用長材。","若因螢火終殘卷，便把漁歌送幾杯。","多謝郢中賢太守，常時談笑許追陪。"]', '["蘭汀橘島映亭台，不是經心即手栽。","满閣白云隨雨去，一池寒月逐潮来。","小松出屋和巢长，新逕通村避笋开。","柳絮风前欹枕臥，荷花香裏棹舟迴。","园中認葉封林草，簷下攀枝落野梅。","莫恣高情求逸思，須防急詔用长材。","若因螢火終殘卷，便把漁歌送幾杯。","多謝郢中賢太守，常时談笑許追陪。"]', '诗', 'shi', '', NULL, '許員外新陽別業 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aaaac947-5d82-401f-8d95-48494cd6fb40', '李侍御上虞別業', '李侍御上虞別業', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["滿目亭臺嘉木繁，燕蟬吟語不爲喧。","晝潮勢急吞諸島，暑雨聲迴露半村。","真爲援毫方掩卷，常因按曲便開尊。","若將明月爲儔侶，應把清風遺子孫。","繡羽驚弓離果上，紅鱗見餌出蒲根。","尋君未要先敲竹，且棹漁舟入大門。"]', '["满目亭台嘉木繁，燕蟬吟語不爲喧。","晝潮勢急吞諸島，暑雨声迴露半村。","真爲援毫方掩卷，常因按曲便开尊。","若將明月爲儔侶，應把清风遺子孫。","繡羽驚弓離果上，紅鱗见餌出蒲根。","尋君未要先敲竹，且棹漁舟入大门。"]', '诗', 'shi', '', NULL, '李侍御上虞別業 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ce68366-a582-4fe7-9d07-c350d2a09230', '題懸溜巖隱者居', '題懸溜巖隐者居', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["世人如要問生涯，滿架堆牀是五車。","谷鳥暮蟬聲四散，修篁灌木勢交加。","蒲葵細織團圓扇，薤葉平鋪合遝花。","却用水荷苞綠李，兼將寒井浸甘瓜。","慣緣嶮峭收松粉，常趂芳鮮掇茗芽。","池上樹陰隨浪動，窗前月影被巢遮。","坐雲獨酌杯盤濕，穿竹微吟路徑斜。","見說公卿訪遺逸，逢迎亦是戴烏紗。"]', '["世人如要问生涯，满架堆牀是五车。","谷鸟暮蟬声四散，修篁灌木勢交加。","蒲葵細织團圓扇，薤葉平鋪合遝花。","却用水荷苞綠李，兼將寒井浸甘瓜。","慣緣嶮峭收松粉，常趂芳鲜掇茗芽。","池上樹陰隨浪动，窗前月影被巢遮。","坐云独酌杯盤濕，穿竹微吟路徑斜。","见说公卿訪遺逸，逢迎亦是戴烏紗。"]', '诗', 'shi', '', NULL, '題懸溜巖隱者居 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f685a00-97a9-4faf-a785-7fab7cb57244', '山中言事八韻寄李支使', '山中言事八韻寄李支使', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["豈知經史深相悞，兩鬢垂絲百事休。","受業幾多爲弟子，成名一半作公侯。","前時射鵠徒拋箭，此日求魚未上鉤。","竹裏斷雲來枕上，巖邊片月在牀頭。","過庭急雨和花落，遶舍澄泉帶葉流。","緬想遠書聆鵲喜，窺尋嘉果覺猿偷。","舊詩改處空留韻，新醞嘗來不滿篘。","阮瑀如能問寒餒，風光當日入滄洲。"]', '["豈知經史深相悞，兩鬢垂絲百事休。","受業幾多爲弟子，成名一半作公侯。","前时射鵠徒拋箭，此日求鱼未上鉤。","竹裏斷云来枕上，巖邊片月在牀头。","過庭急雨和花落，遶舍澄泉带葉流。","緬想远书聆鵲喜，窺尋嘉果覺猿偷。","旧诗改处空留韻，新醞嘗来不满篘。","阮瑀如能问寒餒，风光當日入滄洲。"]', '诗', 'shi', '', NULL, '山中言事八韻寄李支使 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fa01f08-2686-4fc1-91d8-bcd83e046010', '山中言事寄贈蘇判官', '山中言事寄贈蘇判官', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["寸心似火頻求薦，兩鬢如霜始息機。","隔岸雞鳴春耨去，鄰家犬吠夜漁歸。","倚松長嘯成疎拙，拂石欹眠絕是非。","執爨縱曾炊橡實，紉針曾解補荷衣。","常憑早月來張燭，亦假清風爲掩扉。","多是元瑜憐野賤，時迴車馬發光輝。"]', '["寸心似火頻求薦，兩鬢如霜始息機。","隔岸雞鳴春耨去，鄰家犬吠夜漁归。","倚松长嘯成疎拙，拂石欹眠絕是非。","執爨縱曾炊橡實，紉針曾解補荷衣。","常憑早月来張燭，亦假清风爲掩扉。","多是元瑜怜野賤，时迴车马發光輝。"]', '诗', 'shi', '', NULL, '山中言事寄贈蘇判官 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a643914-95d2-47b9-acfc-6407687869f6', '獻王大夫', '獻王大夫', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["高情不與俗人知，耻學諸生取桂枝。","荀宋五言行世早，巢由三詔出溪遲。","操心已在精微域，落筆皆成典誥詞。","一鶚難成燕雀伍，非熊本是帝王師。","賢臣雖蘊經邦術，明主終無諫獵時。","莫道百僚憂禮絕，兼聞七郡怕天移。","直緣材力頭頭贍，專被文星步步隨。","不信重言通造化，須臾便可變榮衰。"]', '["高情不與俗人知，耻学諸生取桂枝。","荀宋五言行世早，巢由三詔出溪遲。","操心已在精微域，落笔皆成典誥词。","一鶚难成燕雀伍，非熊本是帝王師。","賢臣雖蘊經邦術，明主終無諫獵时。","莫道百僚憂禮絕，兼闻七郡怕天移。","直緣材力头头贍，專被文星步步隨。","不信重言通造化，須臾便可变榮衰。"]', '诗', 'shi', '', NULL, '獻王大夫 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('159a72c5-31db-4cab-94dd-22f2f7d9cb0d', '淺井', '淺井', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["夜入明河星似少，曙搖澄碧扇風翻。","細泉細脈難來到，應覺添瓶耗舊痕。"]', '["夜入明河星似少，曙搖澄碧扇风翻。","細泉細脈难来到，應覺添瓶耗旧痕。"]', '诗', 'shi', '', NULL, '淺井 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('633aee94-6b17-4f5a-a86d-5bdee4a3e2f9', '與徐溫話別', '與徐溫話別', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["去去何時却見君，悠悠煙水似天津。","明年今夜有明月，不是今年看月人。"]', '["去去何时却见君，悠悠煙水似天津。","明年今夜有明月，不是今年看月人。"]', '诗', 'shi', '', NULL, '與徐溫話別 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d6d84e8-f587-49f1-bc8c-d93371ea50b4', '出東陽道中作', '出东陽道中作', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["馬首寒山黛色濃，一重重盡一重重。","醉醒已在他人界，猶憶東陽昨夜鐘。"]', '["马首寒山黛色濃，一重重尽一重重。","醉醒已在他人界，猶憶东陽昨夜鐘。"]', '诗', 'shi', '', NULL, '出東陽道中作 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cee1c62-0c45-499a-ae02-9b0e491d2ff3', '酬孫發', '酬孫發', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["錦價轉高花更巧，能將舊手弄新梭。","從來一字爲褒貶，二十八言猶太多。"]', '["錦價轉高花更巧，能將旧手弄新梭。","從来一字爲褒貶，二十八言猶太多。"]', '诗', 'shi', '', NULL, '酬孫發 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f00895ae-2266-441d-a715-7ba2dcc4407e', '送鄉中故人', '送乡中故人', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["少小與君情不疎，聽君細話勝家書。","如今若到鄉中去，道我垂鉤不釣魚。"]', '["少小與君情不疎，听君細話勝家书。","如今若到乡中去，道我垂鉤不釣鱼。"]', '诗', 'shi', '', NULL, '送鄉中故人 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22c95d0c-6049-4ba8-ab66-b87621d59739', '思江南', '思江南', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["昨日草枯今日青，羇人又動望鄉情。","夜來有夢登歸路，不到桐廬已及明。"]', '["昨日草枯今日青，羇人又动望乡情。","夜来有梦登归路，不到桐廬已及明。"]', '诗', 'shi', '', NULL, '思江南 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f960de41-6651-45bc-acb7-0be08b65f68c', '題寶林寺禪者壁', '題寶林寺禪者壁', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["邃巖喬木夏藏寒，牀下雲溪枕上看。","臺殿漸多山更重，却令飛去即應難。"]', '["邃巖喬木夏藏寒，牀下云溪枕上看。","台殿漸多山更重，却令飞去即應难。"]', '诗', 'shi', '', NULL, '題寶林寺禪者壁 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('853a59b7-26e1-4644-b3cd-9e619d6e9d51', '過李羣玉故居', '過李羣玉故居', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["訐直上書難遇主，銜冤下世未成翁。","琴尊劍鶴誰將去，惟鎖山齋一樹風。"]', '["訐直上书难遇主，銜冤下世未成翁。","琴尊劍鹤誰將去，惟鎖山斋一樹风。"]', '诗', 'shi', '', NULL, '過李羣玉故居 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25130ef8-2d6d-442f-9107-01d0877c7578', '題玉笥山強處士', '題玉笥山強处士', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["酒裏藏身嵒裏居，刪繁自是一家書。","世人呼爾爲漁叟，爾學釣璜非釣魚。"]', '["酒裏藏身嵒裏居，刪繁自是一家书。","世人呼爾爲漁叟，爾学釣璜非釣鱼。"]', '诗', 'shi', '', NULL, '題玉笥山強處士 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82fe5f24-e534-49e0-b989-4203b2a1b377', '君不來', '君不来', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["遠路東西欲問誰，寒來無處寄寒衣。","去時初種庭前樹，樹已勝巢人未歸。"]', '["远路东西欲问誰，寒来無处寄寒衣。","去时初種庭前樹，樹已勝巢人未归。"]', '诗', 'shi', '', NULL, '君不來 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('628bb385-a964-423e-96c9-559a788be989', '經曠禪師舊院', '經曠禪師旧院', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["谷鳥散啼如有恨，庭花含笑似無情。","更名變皃難休息，去去來來第幾生。"]', '["谷鸟散啼如有恨，庭花含笑似無情。","更名变皃难休息，去去来来第幾生。"]', '诗', 'shi', '', NULL, '經曠禪師舊院 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46d896f1-7fae-48a1-999a-380308a58dbb', '江南聞新曲', '江南闻新曲', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["席上新聲花下杯，一聲聲被拍聲摧。","樂工不識長安道，盡是書中寄曲來。"]', '["席上新声花下杯，一声声被拍声摧。","乐工不識长安道，尽是书中寄曲来。"]', '诗', 'shi', '', NULL, '江南聞新曲 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('094d3e43-ccaf-400f-955e-dbea6ddd133b', '經故侯郎中舊居', '經故侯郎中旧居', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["一朝寂寂與冥冥，壟樹未長墳草青。","高節雄才向何處，夜闌空鎖滿池星。"]', '["一朝寂寂與冥冥，壟樹未长墳草青。","高節雄才向何处，夜闌空鎖满池星。"]', '诗', 'shi', '', NULL, '經故侯郎中舊居 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('287c3446-2875-4ae7-8364-8ee77df5d9d6', '越中逢孫百篇', '越中逢孫百篇', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["上才乘酒到山陰，日日成篇字字金。","鏡水周迴千萬頃，波瀾倒瀉入君心。"]', '["上才乘酒到山陰，日日成篇字字金。","镜水周迴千万頃，波瀾倒瀉入君心。"]', '诗', 'shi', '', NULL, '越中逢孫百篇 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35bffb3a-06bd-40f2-99fa-bac1292cf57f', '寄謝麟', '寄謝麟', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["越國雲溪秀發時，蔣京詞賦謝麟詩。","後來若要知優劣，學圃無過老圃知。"]', '["越国云溪秀發时，蔣京词賦謝麟诗。","後来若要知優劣，学圃無過老圃知。"]', '诗', 'shi', '', NULL, '寄謝麟 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2073d156-f290-402b-94be-ef3c1bcd170a', '與長洲陳子美長官', '與长洲陳子美长官', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["枕上愁多百緒牽，常時睡覺在溪前。","人前盡是交親力，莫道升沈總信天。"]', '["枕上愁多百緒牽，常时睡覺在溪前。","人前尽是交親力，莫道升沈總信天。"]', '诗', 'shi', '', NULL, '與長洲陳子美長官 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c4a9138-88af-431e-a3a0-910d8e665f8b', '新安殷明府家樂方響', '新安殷明府家乐方响', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["葛溪鐵片梨園調，耳底丁東十六聲。","彭澤主人憐妙樂，玉杯春暖許同傾。"]', '["葛溪鐵片梨园調，耳底丁东十六声。","彭澤主人怜妙乐，玉杯春暖許同傾。"]', '诗', 'shi', '', NULL, '新安殷明府家樂方響 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45fed8b0-3d29-4f76-8439-04aa84b8fbca', '別殷明府', '別殷明府', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["許教門館久踟躇，仲叔懷恩對玉壺。","唯有離心欲銷客，空垂雙淚不成珠。"]', '["許教门館久踟躇，仲叔懷恩对玉壺。","唯有離心欲銷客，空垂雙泪不成珠。"]', '诗', 'shi', '', NULL, '別殷明府 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('481df1f9-1f44-4179-894b-fbdc2cdbaa07', '送水墨項處士歸天台', '送水墨項处士归天台', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["仙嶠倍分元化功，揉藍翠色一重重。","還家莫更尋山水，自有雲山在筆峰。"]', '["仙嶠倍分元化功，揉藍翠色一重重。","還家莫更尋山水，自有云山在笔峰。"]', '诗', 'shi', '', NULL, '送水墨項處士歸天台 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6c85766-a521-46c9-a1cd-b36dd6f18c01', '贈會稽楊長官', '贈會稽楊长官', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["直鉤終日竟無魚，鐘鼓聲中與世疎。","若向湖邊訪幽拙，蕭條四壁是閑居。"]', '["直鉤終日竟無鱼，鐘鼓声中與世疎。","若向湖邊訪幽拙，蕭條四壁是闲居。"]', '诗', 'shi', '', NULL, '贈會稽楊長官 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cfaefcb-d34b-44d2-92e7-99d0361aa8dc', '贈申長官', '贈申长官', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["言下隨機見物情，看看獄路草還生。","旅人莫怪無魚食，直爲寒江水至清。"]', '["言下隨機见物情，看看獄路草還生。","旅人莫怪無鱼食，直爲寒江水至清。"]', '诗', 'shi', '', NULL, '贈申長官 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26c81ed8-2fab-4af1-8fc8-865ff7d4fbd7', '將歸湖上留別陳宰', '將归湖上留別陳宰', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["歸去春山逗晚晴，縈迴樹石罅中行。","明時不是無知己，自憶湖邊釣與耕。"]', '["归去春山逗晚晴，縈迴樹石罅中行。","明时不是無知己，自憶湖邊釣與耕。"]', '诗', 'shi', '', NULL, '將歸湖上留別陳宰 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2cc7626-574f-4fac-a509-e1c5c750cf6b', '貽亮上人', '貽亮上人', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["秋水一泓常見底，澗松千尺不生枝。","人間學佛知多少，淨盡心花只有師。"]', '["秋水一泓常见底，澗松千尺不生枝。","人间学佛知多少，淨尽心花只有師。"]', '诗', 'shi', '', NULL, '貽亮上人 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5acd812b-5191-4c13-8c91-ead4eb4524eb', '貽曦上人', '貽曦上人', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["四十年來多少人，一分零落九成塵。","與師猶得重相見，亦是枯株勉強春。"]', '["四十年来多少人，一分零落九成塵。","與師猶得重相见，亦是枯株勉強春。"]', '诗', 'shi', '', NULL, '貽曦上人 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cc788b9-6d65-4d60-9bee-02a7f7dcbae5', '書原上鮑處士屋壁', '书原上鲍处士屋壁', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["水闊坐看千萬里，青蕪蓋地接天津。","禰衡莫愛山中靜，遶舍山多却礙人。"]', '["水闊坐看千万里，青蕪蓋地接天津。","禰衡莫愛山中静，遶舍山多却礙人。"]', '诗', 'shi', '', NULL, '書原上鮑處士屋壁 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c6d3c94-4d8d-485d-b69b-46f23ebbffac', '別孫蜀', '別孫蜀', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["吳越思君意易傷，別君添我鬢邊霜。","由來淛水偏堪恨，截斷千山作兩鄉。"]', '["吳越思君意易傷，別君添我鬢邊霜。","由来淛水偏堪恨，截斷千山作兩乡。"]', '诗', 'shi', '', NULL, '別孫蜀 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03006024-21d5-4dcc-812a-d47bcfc1a457', '贈江上老人', '贈江上老人', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["潭底錦鱗多識釣，未投香餌即先知。","欲教魚目無分別，須學揉藍染釣絲。"]', '["潭底錦鱗多識釣，未投香餌即先知。","欲教鱼目無分別，須学揉藍染釣絲。"]', '诗', 'shi', '', NULL, '贈江上老人 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64e41cf9-d05d-4fa0-b49d-92dc4167c1c2', '贈東溪貧道', '贈东溪貧道', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["非唯劍鶴獨難留，觸事皆聞被債收。","賴是豪家念寒餒，却還漁島與漁舟。"]', '["非唯劍鹤独难留，觸事皆闻被債收。","賴是豪家念寒餒，却還漁島與漁舟。"]', '诗', 'shi', '', NULL, '贈東溪貧道 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec5a29ea-1295-4e5c-a8c4-191b2aed3524', '詠花', '詠花', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["狂心醉眼共裴回，一半先開笑未開。","此日不能偷折去，胡蜂直恐趂人來。"]', '["狂心醉眼共裴回，一半先开笑未开。","此日不能偷折去，胡蜂直恐趂人来。"]', '诗', 'shi', '', NULL, '詠花 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba075193-c062-4f98-a3c8-bc502543b62b', '路入金州江中作', '路入金州江中作', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["棹尋椒岸縈迴去，數里時逢一兩家。","知是從來貢金處，江邊牧豎亦披沙。"]', '["棹尋椒岸縈迴去，數里时逢一兩家。","知是從来貢金处，江邊牧豎亦披沙。"]', '诗', 'shi', '', NULL, '路入金州江中作 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('147f8ac8-6bc9-4068-895b-8a5286efa9ec', '夜會鄭氏昆季林亭', '夜會鄭氏昆季林亭', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["卷簾圓月照方塘，坐久尊空竹有霜。","白犬吠風驚雁起，猶能一一旋成行。"]', '["卷簾圓月照方塘，坐久尊空竹有霜。","白犬吠风驚雁起，猶能一一旋成行。"]', '诗', 'shi', '', NULL, '夜會鄭氏昆季林亭 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e171648-38bf-4919-9909-529e07e37301', '題黃山人庭前孤桂', '題黄山人庭前孤桂', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["映窗孤桂非手植，子落月中聞落時。","仙客此時頭不白，看來看去有枯枝。"]', '["映窗孤桂非手植，子落月中闻落时。","仙客此时头不白，看来看去有枯枝。"]', '诗', 'shi', '', NULL, '題黃山人庭前孤桂 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('daa99ddf-9c05-456a-b83c-3f57d4a509be', '送僧南遊', '送僧南游', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["三秋萬里五溪行，風裏孤雲不計程。","若念猩猩解言語，放生先合放猩猩。"]', '["三秋万里五溪行，风裏孤云不計程。","若念猩猩解言語，放生先合放猩猩。"]', '诗', 'shi', '', NULL, '送僧南遊 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('298e06a4-2baf-4d6f-85de-4eb392a50bcf', '惜花', '惜花', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["可憐妍豔正當時，剛被狂風一夜吹。","今日流鶯來舊處，百般言語殢空枝。"]', '["可怜妍豔正當时，剛被狂风一夜吹。","今日流鶯来旧处，百般言語殢空枝。"]', '诗', 'shi', '', NULL, '惜花 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8632c4e-eafb-4de2-9100-b471d05d2528', '題天柱觀魚尊師舊院', '題天柱观鱼尊師旧院', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["早識吾師頻到此，芝童藥犬亦相迎。","今師一去無來日，花洞石壇空月明。"]', '["早識吾師頻到此，芝童藥犬亦相迎。","今師一去無来日，花洞石壇空月明。"]', '诗', 'shi', '', NULL, '題天柱觀魚尊師舊院 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfd3313f-62c8-4328-803f-b01c019ec77f', '東陽道中作', '东陽道中作', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["百花香氣傍行人，花底垂鞭日易醺。","野父不知寒食節，穿林轉壑自燒雲。"]', '["百花香氣傍行人，花底垂鞭日易醺。","野父不知寒食節，穿林轉壑自燒云。"]', '诗', 'shi', '', NULL, '東陽道中作 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad181c40-a014-43b7-9325-2b1e7ca4231e', '題畫建溪圖', '題畫建溪圖', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["六幅輕綃畫建溪，刺桐花下路高低。","分明記得曾行處，祗欠猿聲與鳥啼。"]', '["六幅轻綃畫建溪，刺桐花下路高低。","分明記得曾行处，祗欠猿声與鸟啼。"]', '诗', 'shi', '', NULL, '題畫建溪圖 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bb37279-2f68-4f24-a7e4-91ed086ac8cf', '蜀中', '蜀中', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["遊子去遊多不歸，春風酒味勝餘時。","閑來却伴巴兒醉，荳蔲花邊唱竹枝。"]', '["游子去游多不归，春风酒味勝餘时。","闲来却伴巴兒醉，荳蔲花邊唱竹枝。"]', '诗', 'shi', '', NULL, '蜀中 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('752e8458-d475-451a-8d6c-346f48c48542', '衢州別李秀才', '衢州別李秀才', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["千山紅樹萬山雲，把酒相看日又曛。","一曲離歌兩行淚，更知何地再逢君。"]', '["千山紅樹万山云，把酒相看日又曛。","一曲離歌兩行泪，更知何地再逢君。"]', '诗', 'shi', '', NULL, '衢州別李秀才 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('029fd96d-bfcb-471d-b212-0b076833e3ce', '題君山', '題君山', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["曾于方外見麻姑，聞說君山自古無。","元是崑崙山頂石，海風吹落洞庭湖。"]', '["曾于方外见麻姑，闻说君山自古無。","元是崑崙山頂石，海风吹落洞庭湖。"]', '诗', 'shi', '', NULL, '題君山 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7857d80c-90b6-4c81-ad52-010baea89c72', '題嚴子陵祠二首 一', '題嚴子陵祠二首 一', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["物色旁求至漢庭，一宵同寢見交情。","先生不入雲臺像，贏得桐江萬古名。"]', '["物色旁求至漢庭，一宵同寢见交情。","先生不入云台像，贏得桐江万古名。"]', '诗', 'shi', '', NULL, '題嚴子陵祠二首 一 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3bb6263d-dc05-4ef4-ae6c-f958a2f714b2', '題嚴子陵祠二首 二', '題嚴子陵祠二首 二', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["蒼翠雲峰開俗眼，泓澄煙水浸塵心。","惟將道業爲芳餌，釣得高名直到今。"]', '["蒼翠云峰开俗眼，泓澄煙水浸塵心。","惟將道業爲芳餌，釣得高名直到今。"]', '诗', 'shi', '', NULL, '題嚴子陵祠二首 二 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('408b99c3-3596-49dd-950d-0164f134a46f', '失題', '失題', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["十六聲中運手輕，一聲聲似自然聲。","不緣精妙過流輩，爭得江南別有名。"]', '["十六声中運手轻，一声声似自然声。","不緣精妙過流輩，爭得江南別有名。"]', '诗', 'shi', '', NULL, '失題 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd9ee4fb-7c6e-4709-b9a3-9be162d4e3cb', '句', '句', '5b832ff7-21a7-43cd-859c-6e60a66d0244', '唐', '["弟子已攀桂，先生猶臥雲。","把得新詩草裏論。","枯井夜聞鄰果落，廢巢寒見別禽來。"]', '["弟子已攀桂，先生猶臥云。","把得新诗草裏論。","枯井夜闻鄰果落，廢巢寒见別禽来。"]', '诗', 'shi', '', NULL, '句 方干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('907c21dd-f8c0-4cb1-9208-812f9d62c36b', '歲仗', '歲仗', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["玉帛朝元萬國來，雞人曉唱五門開。","春排北極迎仙馭，日捧南山入壽杯。","歌舜薰風鏗劒珮，祝堯嘉氣靄樓臺。","可憐四海車書共，重見蕭曹佐漢材。"]', '["玉帛朝元万国来，雞人晓唱五门开。","春排北極迎仙馭，日捧南山入壽杯。","歌舜薰风鏗劒珮，祝堯嘉氣靄楼台。","可怜四海车书共，重见蕭曹佐漢材。"]', '诗', 'shi', '', NULL, '歲仗 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69d87b1e-7b47-4cb9-8522-68896e274626', '牡丹', '牡丹', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["落盡春紅始著花，花時比屋事豪奢。","買栽池館恐無地，看到子孫能幾家。","門倚長衢攢繡轂，幄籠輕日護香霞。","歌鐘滿座爭歡賞，肯信流年鬢有華。"]', '["落尽春紅始著花，花时比屋事豪奢。","買栽池館恐無地，看到子孫能幾家。","门倚长衢攢繡轂，幄籠轻日護香霞。","歌鐘满座爭歡賞，肯信流年鬢有华。"]', '诗', 'shi', '', NULL, '牡丹 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab88c86d-b340-4c1f-9ae0-a788e0f52201', '長城', '长城', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["當時無德御乾坤，廣築徒勞萬古存。","謾役生民防極塞，不知血刃起中原。","珠璣旋見陪陵寢，社稷何曾保子孫。","降虜至今猶自說，冤聲夜夜傍城根。"]', '["當时無德御乾坤，廣築徒勞万古存。","謾役生民防極塞，不知血刃起中原。","珠璣旋见陪陵寢，社稷何曾保子孫。","降虜至今猶自说，冤声夜夜傍城根。"]', '诗', 'shi', '', NULL, '長城 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47e46e33-41a7-4871-9ce9-9519ad774e58', '秋夕寄友人', '秋夕寄友人', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["秋夕蒼茫一雁過，西風白露滿宮莎。","昨來京洛逢歸客，猶說軒車未渡河。","莫把少年空倚賴，須知孤立易蹉跎。","想君懷抱哀吟夜，銅雀臺前皓月多。"]', '["秋夕蒼茫一雁過，西风白露满宮莎。","昨来京洛逢归客，猶说軒车未渡河。","莫把少年空倚賴，須知孤立易蹉跎。","想君懷抱哀吟夜，銅雀台前皓月多。"]', '诗', 'shi', '', NULL, '秋夕寄友人 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1fc353c-ead2-4f94-9245-b8b58d4e4e5e', '冬夕江上言事五首 一', '冬夕江上言事五首 一', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["葉落纔悲草又生，看看少壯是衰形。","關中秋雨書難到，江上春寒酒易醒。","多少繫心身未達，尋思舉目淚堪零。","幾時拋得歸山去，松下看雲讀道經。"]', '["葉落纔悲草又生，看看少壯是衰形。","关中秋雨书难到，江上春寒酒易醒。","多少繫心身未達，尋思舉目泪堪零。","幾时拋得归山去，松下看云读道經。"]', '诗', 'shi', '', NULL, '冬夕江上言事五首 一 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d8701fe-8420-4a91-8ad5-6fe35cc6bf60', '冬夕江上言事五首 二', '冬夕江上言事五首 二', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["喔喔晨雞滿樹霜，喧喧曉渡簇舟航。","數星昨夜寒爐火，一陣誰家臘甕香。","久別羇孤成潦倒，迴看書劒更蒼黃。","逢人舉止皆言命，至竟謀閑可勝忙。"]', '["喔喔晨雞满樹霜，喧喧晓渡簇舟航。","數星昨夜寒爐火，一陣誰家臘甕香。","久別羇孤成潦倒，迴看书劒更蒼黄。","逢人舉止皆言命，至竟謀闲可勝忙。"]', '诗', 'shi', '', NULL, '冬夕江上言事五首 二 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfa27e22-0888-4a02-8764-e2bbb54cec79', '冬夕江上言事五首 三', '冬夕江上言事五首 三', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["野堂吟罷獨行行，點水微微凍不鳴。","十里溪山新雪後，千家襟袖曉寒生。","只宜醉夢依華寢，可稱羸蹄赴宿程。","日苦幾多心下見，那堪歲晏又無成。"]', '["野堂吟罷独行行，点水微微凍不鳴。","十里溪山新雪後，千家襟袖晓寒生。","只宜醉梦依华寢，可稱羸蹄赴宿程。","日苦幾多心下见，那堪歲晏又無成。"]', '诗', 'shi', '', NULL, '冬夕江上言事五首 三 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74d46eeb-c751-4981-a240-8972e4587f3f', '冬夕江上言事五首 四', '冬夕江上言事五首 四', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["僻居多與懶相宜，吟擁寒爐過臘時。","風柳欲生陽面葉，凍梅先綻嶺頭枝。","山川自小拋耕釣，骨肉無因免別離。","賴有陶情一尊酒，愁中相向展愁眉。"]', '["僻居多與懶相宜，吟擁寒爐過臘时。","风柳欲生陽面葉，凍梅先綻嶺头枝。","山川自小拋耕釣，骨肉無因免別離。","賴有陶情一尊酒，愁中相向展愁眉。"]', '诗', 'shi', '', NULL, '冬夕江上言事五首 四 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c905516-4089-4fdd-accc-887af08a78e9', '冬夕江上言事五首 五', '冬夕江上言事五首 五', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["一帶長溪淥浸門，數聲幽鳥啄雲根。","松亭盡日唯空坐，難得儒翁共討論。"]', '["一带长溪淥浸门，數声幽鸟啄云根。","松亭尽日唯空坐，难得儒翁共討論。"]', '诗', 'shi', '', NULL, '冬夕江上言事五首 五 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb07ad37-32ab-4b4c-967d-0f990ef02e9e', '春日宿崇賢里', '春日宿崇賢里', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["柳暗榆飛春日深，水邊門巷獨來尋。","舊山共是經年別，新句相逢竟夕吟。","枕近禁街聞曉鼓，月當高竹見棲禽。","勞歌莫問秋風計，恐起江河垂釣心。"]', '["柳暗榆飞春日深，水邊门巷独来尋。","旧山共是經年別，新句相逢竟夕吟。","枕近禁街闻晓鼓，月當高竹见棲禽。","勞歌莫问秋风計，恐起江河垂釣心。"]', '诗', 'shi', '', NULL, '春日宿崇賢里 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3975bb78-6a18-4c1c-9809-bcc18ca99917', '征人', '征人', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["青樓一別戍金微，力盡秋來破虜圍。","錦字莫辭連夜織，塞鴻常是到春歸。","正憐漢月當空照，不奈胡沙滿眼飛。","唯有夢魂南去日，故鄉山水路依稀。"]', '["青楼一別戍金微，力尽秋来破虜圍。","錦字莫辞連夜织，塞鴻常是到春归。","正怜漢月當空照，不奈胡沙满眼飞。","唯有梦魂南去日，故乡山水路依稀。"]', '诗', 'shi', '', NULL, '征人 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd064c9b-59c3-4bc2-a97d-c1e2f0d298c3', '鶯', '鶯', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["暖辭雲谷背殘陽，飛下東風翅漸長。","却笑金籠是羈絆，豈知瑤草正芬芳。","曉逢溪雨投紅樹，晚囀宮樓泣舊妝。","何事離人不堪聽，灞橋斜日褭垂楊。"]', '["暖辞云谷背殘陽，飞下东风翅漸长。","却笑金籠是羈絆，豈知瑤草正芬芳。","晓逢溪雨投紅樹，晚囀宮楼泣旧妝。","何事離人不堪听，灞橋斜日褭垂楊。"]', '诗', 'shi', '', NULL, '鶯 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d417588-0e6c-438c-93a5-5afab29e5bc4', '槐花', '槐花', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["行宮門外陌銅駝，兩畔分栽此最多。","欲到清秋近時節，爭開金蘂向關河。","層樓寄恨飄珠箔，駿馬憐香撼玉珂。","愁殺江湖隨計者，年年爲爾剩奔波。"]', '["行宮门外陌銅駝，兩畔分栽此最多。","欲到清秋近时節，爭开金蘂向关河。","層楼寄恨飄珠箔，駿马怜香撼玉珂。","愁殺江湖隨計者，年年爲爾剩奔波。"]', '诗', 'shi', '', NULL, '槐花 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d8301fd-9f94-46d0-b981-2d2eb97b18e4', '自蜀入關', '自蜀入关', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["文戰連輸未息機，束書攜劒定前非。","近來從聽事難得，休去且無山可歸。","匹馬出門還悵望，孤雲何處是因依？","斜陽驛路西風緊，遙指人煙宿翠微。"]', '["文戰連輸未息機，束书携劒定前非。","近来從听事难得，休去且無山可归。","匹马出门還悵望，孤云何处是因依？","斜陽驛路西风緊，遙指人煙宿翠微。"]', '诗', 'shi', '', NULL, '自蜀入關 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5c55939-4440-4283-b269-d17a834c9f7e', '上陽宮', '上陽宮', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["春半上陽花滿樓，太平天子昔巡遊。","千門雖對嵩山在，一笑還隨洛水流。","深鎖笙歌巢燕聽，遙瞻金碧路人愁。","翠華却自登仙去，腸斷宮娥望不休。"]', '["春半上陽花满楼，太平天子昔巡游。","千门雖对嵩山在，一笑還隨洛水流。","深鎖笙歌巢燕听，遙瞻金碧路人愁。","翠华却自登仙去，腸斷宮娥望不休。"]', '诗', 'shi', '', NULL, '上陽宮 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91699541-4f7a-48a1-bcc9-ba778bac51c1', '舊侯家', '旧侯家', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["臺閣層層倚半空，遶軒澄碧御溝通。","金鈿座上歌春酒，畫蠟尊前滴曉風。","歲月不知成隙地，子孫誰更繫殊功。","人間若算無榮辱，却是扁舟一釣翁。"]', '["台閣層層倚半空，遶軒澄碧御溝通。","金鈿座上歌春酒，畫蠟尊前滴晓风。","歲月不知成隙地，子孫誰更繫殊功。","人间若算無榮辱，却是扁舟一釣翁。"]', '诗', 'shi', '', NULL, '舊侯家 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd5416bc-02e2-4964-aaf7-916f448a764a', '宿武安山有懷', '宿武安山有懷', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["野店暮來山畔逢，寒蕪漠漠露華濃。","窗間燈在犬驚吠，溪上月沈人罷舂。","遠別只愁添雪鬢，此生何計隱雲峯。","離心却羨南飛翼，獨過吳江更數重。"]', '["野店暮来山畔逢，寒蕪漠漠露华濃。","窗间灯在犬驚吠，溪上月沈人罷舂。","远別只愁添雪鬢，此生何計隐云峯。","離心却羨南飞翼，独過吳江更數重。"]', '诗', 'shi', '', NULL, '宿武安山有懷 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31dde9b8-5b57-43d0-99d5-328625ccc1ee', '謁寗祠', '謁寗祠', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["春生溪嶺雪初開，下馬雲亭酹一杯。","好是精靈偏有感，能於鄉里不爲災。","九江賈客應遙祝，五夜神兵數此來。","盡室唯求多降福，新年歸去便風催。"]', '["春生溪嶺雪初开，下马云亭酹一杯。","好是精靈偏有感，能於乡里不爲災。","九江賈客應遙祝，五夜神兵數此来。","尽室唯求多降福，新年归去便风催。"]', '诗', 'shi', '', NULL, '謁寗祠 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca0d3ec6-2e3e-4554-a7e2-4fb0168230e6', '經故洛城', '經故洛城', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["一片危牆勢恐人，牆邊日日走蹄輪。","築時驅盡千夫力，崩處空爲數里塵。","長恨往來經此地，每嗟興廢欲霑巾。","那堪又向荒城過，錦雉驚飛麥隴春。"]', '["一片危牆勢恐人，牆邊日日走蹄輪。","築时驱尽千夫力，崩处空爲數里塵。","长恨往来經此地，每嗟兴廢欲霑巾。","那堪又向荒城過，錦雉驚飞麦隴春。"]', '诗', 'shi', '', NULL, '經故洛城 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8280e328-d21d-4c8c-bc12-36f1f6fa9aa5', '老將', '老將', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["百戰辛勤歸帝鄉，南班班裏最南行。","弓欺猨臂秋無力，劒泣虯髯曉有霜。","千古恥非書玉帛，一心猶自向河湟。","年年宿衛天顏近，曾把功勳奏建章。"]', '["百戰辛勤归帝乡，南班班裏最南行。","弓欺猨臂秋無力，劒泣虯髯晓有霜。","千古恥非书玉帛，一心猶自向河湟。","年年宿衛天顏近，曾把功勳奏建章。"]', '诗', 'shi', '', NULL, '老將 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfecb565-4671-4fec-9252-3f368c06acbf', '曲江春望', '曲江春望', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["故國東歸澤國遙，曲江晴望憶漁樵。","都緣北闕春先到，不是南山雪易消。","瑞影玉樓開組繡，歡聲丹禁奏雲韶。","雖然未得陪鴛鷺，亦酹金觴祝帝堯。"]', '["故国东归澤国遙，曲江晴望憶漁樵。","都緣北闕春先到，不是南山雪易消。","瑞影玉楼开組繡，歡声丹禁奏云韶。","雖然未得陪鴛鷺，亦酹金觴祝帝堯。"]', '诗', 'shi', '', NULL, '曲江春望 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('851a0abb-fb93-494a-9580-89193160bd7d', '帝里', '帝里', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["喧喧蹄轂走紅塵，南北東西暮與晨。","謾道青雲難得路，何曾紫陌有閑人。","杯傾竹葉侯門月，馬落桃花御水春。","只合詠歌來大國，況逢文景化惟新。"]', '["喧喧蹄轂走紅塵，南北东西暮與晨。","謾道青云难得路，何曾紫陌有闲人。","杯傾竹葉侯门月，马落桃花御水春。","只合詠歌来大国，況逢文景化惟新。"]', '诗', 'shi', '', NULL, '帝里 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8a386a2-41d0-424d-8a7d-700d771115a9', '新安城', '新安城', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["若筭防邊久遠名，新安豈更勝長城。","謾興他役悲荒壘，何似從今實取兵。","聖德便應同險固，人心自不向忠貞。","但將死節酬堯禹，版築無勞寇已平。"]', '["若筭防邊久远名，新安豈更勝长城。","謾兴他役悲荒壘，何似從今實取兵。","聖德便應同險固，人心自不向忠貞。","但將死節酬堯禹，版築無勞寇已平。"]', '诗', 'shi', '', NULL, '新安城 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5ed514b-2c25-4b04-9a1a-48fefddc930d', '自遣', '自遣', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["四十年來詩酒徒，一生緣興滯江湖。","不愁世上無人識，唯怕村中沒酒沽。","春巷摘桑喧姹女，江船吹笛舞蠻奴。","焚魚酌醴醉堯代，吟向席門聊自娛。"]', '["四十年来诗酒徒，一生緣兴滯江湖。","不愁世上無人識，唯怕村中沒酒沽。","春巷摘桑喧姹女，江船吹笛舞蠻奴。","焚鱼酌醴醉堯代，吟向席门聊自娛。"]', '诗', 'shi', '', NULL, '自遣 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5031e420-3ead-447a-aa5e-4997510d1168', '流水', '流水', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["漾漾悠悠幾派分，中浮短艇與鷗羣。","天街帶雨淹芳草，玉洞飄花下白雲。","靜稱一竿持處見，急宜孤館覺來聞。","隋家柳畔偏堪恨，東入長淮日又曛。"]', '["漾漾悠悠幾派分，中浮短艇與鷗羣。","天街带雨淹芳草，玉洞飄花下白云。","静稱一竿持处见，急宜孤館覺来闻。","隋家柳畔偏堪恨，东入长淮日又曛。"]', '诗', 'shi', '', NULL, '流水 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('976b5330-60d9-4800-83f8-e5bf26a563f5', '送張逸人', '送張逸人', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["自說歸山人事賒，素琴丹竈是生涯。","牀頭殘藥鼠偷盡，溪上破門風擺斜。","石井晴垂青葛葉，竹籬荒映白茅花。","遙知此去應稀出，獨臥晴窗夢曉霞。"]', '["自说归山人事賒，素琴丹竈是生涯。","牀头殘藥鼠偷尽，溪上破门风擺斜。","石井晴垂青葛葉，竹籬荒映白茅花。","遙知此去應稀出，独臥晴窗梦晓霞。"]', '诗', 'shi', '', NULL, '送張逸人 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12660670-9084-4177-9ede-75e8ebfdebd7', '春晚渡河有懷', '春晚渡河有懷', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["煙收綠野遠連空，戍壘依稀入望中。","萬里山河星拱北，百年人事水歸東。","扁舟晚濟桃花浪，走馬晴嘶柳絮風。","鄉思正多羈思苦，不須迴首問漁翁。"]', '["煙收綠野远連空，戍壘依稀入望中。","万里山河星拱北，百年人事水归东。","扁舟晚濟桃花浪，走马晴嘶柳絮风。","乡思正多羈思苦，不須迴首问漁翁。"]', '诗', 'shi', '', NULL, '春晚渡河有懷 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cb66e64-c34a-4ecf-8e44-917e7e72f660', '春望梁石頭城', '春望梁石头城', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["柳碧桑黃破國春，殘陽微雨望歸人。","江山不改興亡地，冠蓋自爲前後塵。","帆勢掛風輕若翅，浪聲吹岸疊如鱗。","六朝無限悲愁事，欲下荒城迴首頻。"]', '["柳碧桑黄破国春，殘陽微雨望归人。","江山不改兴亡地，冠蓋自爲前後塵。","帆勢掛风轻若翅，浪声吹岸叠如鱗。","六朝無限悲愁事，欲下荒城迴首頻。"]', '诗', 'shi', '', NULL, '春望梁石頭城 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb06b620-a3e1-45f3-a323-2c4bf4e22a4e', '早發宜陵即事', '早發宜陵即事', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["霜白山村月落時，一聲雞後又登岐。","居人猶自掩關在，行客已愁驅馬遲。","身事不堪空感激，鬢毛看著欲凋衰。","青萍委匣休哮吼，未有恩讐擬報誰。"]', '["霜白山村月落时，一声雞後又登岐。","居人猶自掩关在，行客已愁驱马遲。","身事不堪空感激，鬢毛看著欲凋衰。","青萍委匣休哮吼，未有恩讐擬報誰。"]', '诗', 'shi', '', NULL, '早發宜陵即事 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('508074ec-f7cc-4ee4-8c53-fc230ba9c316', '鴛鴦', '鴛鴦', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["紅閑碧霽瑞煙開，錦翅雙飛去又迴。","一種鳥憐名字好，盡緣人恨別離來。","暖依牛渚汀莎媚，夕宿龍池禁漏催。","相對若教春女見，便須攜向鳳凰臺。"]', '["紅闲碧霽瑞煙开，錦翅雙飞去又迴。","一種鸟怜名字好，尽緣人恨別離来。","暖依牛渚汀莎媚，夕宿龙池禁漏催。","相对若教春女见，便須携向鳳凰台。"]', '诗', 'shi', '', NULL, '鴛鴦 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52d23303-c4b1-4969-b788-89235b2b768f', '春閨', '春閨', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["愁坐蘭閨日過遲，卷簾巢燕羨雙飛。","管弦樓上春應在，楊柳橋邊人未歸。","玉笛豈能留舞態，金河猶自浣戎衣。","梨花滿院東風急，惆悵無言倚錦機。"]', '["愁坐蘭閨日過遲，卷簾巢燕羨雙飞。","管弦楼上春應在，楊柳橋邊人未归。","玉笛豈能留舞態，金河猶自浣戎衣。","梨花满院东风急，惆悵無言倚錦機。"]', '诗', 'shi', '', NULL, '春閨 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('051c3516-1de6-4771-8530-9de30d651a34', '贈東川梓桐縣韋德孫長官', '贈东川梓桐縣韋德孫长官', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["前代高門今宰邑，懷才重義古來無。","笙歌厭聽吟清句，京洛思歸展畫圖。","蜀醞天寒留容醉，隴禽山曉隔簾呼。","何年期拜朱幡貴，馬上論詩在九衢。"]', '["前代高门今宰邑，懷才重義古来無。","笙歌厭听吟清句，京洛思归展畫圖。","蜀醞天寒留容醉，隴禽山晓隔簾呼。","何年期拜朱幡貴，马上論诗在九衢。"]', '诗', 'shi', '', NULL, '贈東川梓桐縣韋德孫長官 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de3347f1-b279-4097-bc9c-4477e2a6b225', '題水簾洞', '題水簾洞', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["亂泉飛下翠屏中，名共真珠巧綴同。","一片長垂今與古，半山遙聽水兼風。","雖無舒卷隨人意，自有潺湲濟物功。","每向暑天來往見，疑將仙子隔房櫳。"]', '["亂泉飞下翠屏中，名共真珠巧綴同。","一片长垂今與古，半山遙听水兼风。","雖無舒卷隨人意，自有潺湲濟物功。","每向暑天来往见，疑將仙子隔房櫳。"]', '诗', 'shi', '', NULL, '題水簾洞 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2beb0ae-77a2-4f57-a018-1e6a4f02a6ef', '野花', '野花', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["拂露叢開血色殷，枉無名字對空山。","時逢舞蝶尋香至，少有行人輟櫂攀。","若在侯門看不足，爲生江岸見如閑。","結根畢竟輸桃李，長近都城紫陌間。"]', '["拂露叢开血色殷，枉無名字对空山。","时逢舞蝶尋香至，少有行人輟櫂攀。","若在侯门看不足，爲生江岸见如闲。","結根畢竟輸桃李，长近都城紫陌间。"]', '诗', 'shi', '', NULL, '野花 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f18f909-a424-425e-9e2e-68e30efa8912', '蘆花', '蘆花', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["如練如霜乾復輕，西風處處拂江城。","長垂釣叟看不足，暫泊王孫愁亦生。","好傍翠樓裝月色，枉隨紅葉舞秋聲。","最宜羣鷺斜陽裏，閑捕纖鱗傍爾行。"]', '["如練如霜乾复轻，西风处处拂江城。","长垂釣叟看不足，暫泊王孫愁亦生。","好傍翠楼裝月色，枉隨紅葉舞秋声。","最宜羣鷺斜陽裏，闲捕纖鱗傍爾行。"]', '诗', 'shi', '', NULL, '蘆花 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a21e7d1b-c523-4074-b9b8-a6e347eabd15', '山陽貽友人', '山陽貽友人', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["性僻多將雲水便，山陽酒病動經年。","行遲暖陌花攔馬，睡重春江雨打船。","閑弄玉琴雙鶴舞，靜窺庭樹一猱懸。","結茅更莫期深隱，聲價如今滿日邊。"]', '["性僻多將云水便，山陽酒病动經年。","行遲暖陌花攔马，睡重春江雨打船。","闲弄玉琴雙鹤舞，静窺庭樹一猱懸。","結茅更莫期深隐，声價如今满日邊。"]', '诗', 'shi', '', NULL, '山陽貽友人 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed22ab2e-f86e-4ff2-a378-f32ac8b86455', '長安惜春', '长安惜春', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["千門共惜放春迴，半鎖樓臺半復開。","公子不能留落日，南山遮莫倚高臺。","殘紅似怨皇州雨，細綠猶藏畫蠟灰。","畢竟思量何足歎，明年時節又還來。"]', '["千门共惜放春迴，半鎖楼台半复开。","公子不能留落日，南山遮莫倚高台。","殘紅似怨皇州雨，細綠猶藏畫蠟灰。","畢竟思量何足歎，明年时節又還来。"]', '诗', 'shi', '', NULL, '長安惜春 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('705f361b-a16a-4d3b-bd14-ef5850c5f895', '謝友人遺華陽巾', '謝友人遺华陽巾', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["剪露[裁]煙勝角冠，來從玉洞五雲端。","醉宜薤葉欹斜影，穩稱菱花子細看。","野客愛留籠鶴髪，溪翁爭乞配漁竿。","真仙首飾勞相寄，塵土飜慙戴去難。"]', '["剪露[裁]煙勝角冠，来從玉洞五云端。","醉宜薤葉欹斜影，穩稱菱花子細看。","野客愛留籠鹤髪，溪翁爭乞配漁竿。","真仙首飾勞相寄，塵土飜慙戴去难。"]', '诗', 'shi', '', NULL, '謝友人遺華陽巾 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('334bb3ba-bab6-4664-9807-8329e569c0fd', '早梅', '早梅', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["綴雪枝條似有情，凌寒澹注笑妝成。","凍香飄處宜春早，素豔開時混月明。","遷客嶺頭悲褭褭，美人簾下妬盈盈。","滿園桃李雖堪賞，要且東風晚始生。"]', '["綴雪枝條似有情，凌寒澹注笑妝成。","凍香飄处宜春早，素豔开时混月明。","遷客嶺头悲褭褭，美人簾下妬盈盈。","满园桃李雖堪賞，要且东风晚始生。"]', '诗', 'shi', '', NULL, '早梅 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('646ec3e5-eb75-4908-8b58-6c0ecf4939db', '留題張逸人草堂', '留題張逸人草堂', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["長懸青紫與芳枝，塵路無因免別離。","馬上多於在家日，尊前堪惜少年時。","關河客夢還鄉後，雨雪山程出店遲。","却羨高人此中老，軒車過盡不知誰。"]', '["长懸青紫與芳枝，塵路無因免別離。","马上多於在家日，尊前堪惜少年时。","关河客梦還乡後，雨雪山程出店遲。","却羨高人此中老，軒车過尽不知誰。"]', '诗', 'shi', '', NULL, '留題張逸人草堂 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d295b8e6-7a12-490d-b8a1-ead122132a81', '鍾陵崔大夫罷鎮攀隨再經匡廬寺宿', '鍾陵崔大夫罷鎮攀隨再經匡廬寺宿', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["一拋文戰學從公，兩逐旌旗宿梵宮。","酒醒月移窗影畔，夜涼身在水聲中。","侯門聚散真如夢，花界登臨轉悟空。","明發不堪山下路，幾程愁雨又愁風。"]', '["一拋文戰学從公，兩逐旌旗宿梵宮。","酒醒月移窗影畔，夜涼身在水声中。","侯门聚散真如梦，花界登臨轉悟空。","明發不堪山下路，幾程愁雨又愁风。"]', '诗', 'shi', '', NULL, '鍾陵崔大夫罷鎮攀隨再經匡廬寺宿 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ab45f3c-d91a-4d66-893f-fa3b82009b9a', '留獻彭門郭常侍', '留獻彭门郭常侍', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["受得彭門擁信旗，一家將謂免羈離。","到來門館空歸去，羞向交親說受知。","層構尚無容足地，尺波寧有躍鱗時。","到頭忍恥求名是，須向青雲覓路岐。"]', '["受得彭门擁信旗，一家將謂免羈離。","到来门館空归去，羞向交親说受知。","層構尚無容足地，尺波寧有躍鱗时。","到头忍恥求名是，須向青云覓路岐。"]', '诗', 'shi', '', NULL, '留獻彭門郭常侍 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c24d2ba-ff1f-4ee7-884b-c055cbba1e9b', '洛水', '洛水', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["一道潺湲濺暖莎，年年惆悵是春過。","莫言行路聽如此，流[入]深宮悵更多。","橋畔月來清見底，柳邊風緊綠生波。","縱然滿眼添歸思，未把漁竿奈爾何。"]', '["一道潺湲濺暖莎，年年惆悵是春過。","莫言行路听如此，流[入]深宮悵更多。","橋畔月来清见底，柳邊风緊綠生波。","縱然满眼添归思，未把漁竿奈爾何。"]', '诗', 'shi', '', NULL, '洛水 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('005fcf66-fe23-4151-8082-b924a89a6f5a', '聞杜鵑', '闻杜鵑', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["花時一宿碧山前，明月東風呌杜鵑。","孤館覺來聽夜半，羸僮相對亦無眠。","汝身哀怨猶如此，我淚縱橫豈偶然。","爭得蒼蒼知有恨，汝身成鶴我成仙。"]', '["花时一宿碧山前，明月东风呌杜鵑。","孤館覺来听夜半，羸僮相对亦無眠。","汝身哀怨猶如此，我泪縱橫豈偶然。","爭得蒼蒼知有恨，汝身成鹤我成仙。"]', '诗', 'shi', '', NULL, '聞杜鵑 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c2b0437-c081-4c69-a75c-76fb9108a26c', '趂職單于留別闕下知己', '趂職單于留別闕下知己', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["職忝翩翩逐建牙，笈隨征騎入胡沙。","定將千里書憑雁，應看三春雪當花。","年長有心終報國，時清到處便營家。","逢秋不擬同張翰，爲憶鱸魚却歎嗟。"]', '["職忝翩翩逐建牙，笈隨征騎入胡沙。","定將千里书憑雁，應看三春雪當花。","年长有心終報国，时清到处便營家。","逢秋不擬同張翰，爲憶鱸鱼却歎嗟。"]', '诗', 'shi', '', NULL, '趂職單于留別闕下知己 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b52f4e3-1b6c-41d2-b6e0-31ce7cd4041b', '落第書懷寄友人', '落第书懷寄友人', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["清世誰能便陸沈，相逢休作憶山吟。","若教仙桂在平地，更有何人肯苦心。","去國漢妃還似玉，亡家石氏豈無金。","且安懷抱莫惆悵，瑤瑟調高尊酒深。"]', '["清世誰能便陸沈，相逢休作憶山吟。","若教仙桂在平地，更有何人肯苦心。","去国漢妃還似玉，亡家石氏豈無金。","且安懷抱莫惆悵，瑤瑟調高尊酒深。"]', '诗', 'shi', '', NULL, '落第書懷寄友人 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bccf5e6-9a50-4262-9fa2-253e7ba9b86c', '鸚鵡詠', '鸚鵡詠', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["玉檻瑤軒任所依，東風休憶嶺頭歸。","金[籠]共惜好毛羽，紅觜莫教多是非。","便向郄堂誇飲啄，還應禰筆發光輝。","乘時得路何須貴，燕雀鸞鳳各有機。"]', '["玉檻瑤軒任所依，东风休憶嶺头归。","金[籠]共惜好毛羽，紅觜莫教多是非。","便向郄堂誇饮啄，還應禰笔發光輝。","乘时得路何須貴，燕雀鸾鳳各有機。"]', '诗', 'shi', '', NULL, '鸚鵡詠 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64b3229d-9fd9-4b15-8ade-81af9424ccdb', '題滄浪峽', '題滄浪峽', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["門向紅塵日日開，入門襟袖遠塵埃。","暗香惹步澗花發，晚景逼簷溪鳥迴。","不爲市朝行路近，有誰車馬看山來。","可憐嚴子持竿處，雲水終年鎖綠苔。"]', '["门向紅塵日日开，入门襟袖远塵埃。","暗香惹步澗花發，晚景逼簷溪鸟迴。","不爲市朝行路近，有誰车马看山来。","可怜嚴子持竿处，云水終年鎖綠苔。"]', '诗', 'shi', '', NULL, '題滄浪峽 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f5c5d46-f2bc-4e38-867f-aef2a749b164', '白角簟', '白角簟', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["疊玉駢珪巧思長，露華煙魄讓清光。","休搖雉尾當三伏，似展龍鱗在一牀。","高價不唯標越絕，冷紋疑似臥瀟湘。","杜陵他日重歸去，偏稱醉眠松桂堂。"]', '["叠玉駢珪巧思长，露华煙魄讓清光。","休搖雉尾當三伏，似展龙鱗在一牀。","高價不唯標越絕，冷紋疑似臥瀟湘。","杜陵他日重归去，偏稱醉眠松桂堂。"]', '诗', 'shi', '', NULL, '白角簟 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cba2bb0-9c8d-46b5-a9aa-3cdd62e93638', '秋日懷江上友人', '秋日懷江上友人', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["行子豈知煙水勞，西風獨自泛征艘。","酒醒孤館秋簾卷，月滿寒江夜笛高。","黃葉夢餘歸朔塞，青山家在極波濤。","去年今日逢君處，雁下蘆花猨正號。"]', '["行子豈知煙水勞，西风独自泛征艘。","酒醒孤館秋簾卷，月满寒江夜笛高。","黄葉梦餘归朔塞，青山家在極波濤。","去年今日逢君处，雁下蘆花猨正號。"]', '诗', 'shi', '', NULL, '秋日懷江上友人 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96db5981-c596-4f11-b151-d5a989a4a391', '題笙', '題笙', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["筠管參差排鳳翅，月堂淒切勝龍吟。","最宜輕動纖纖玉，醉送當觀灩灩金。","緱嶺獨能徵妙曲，嬴臺相共吹清音。","好將宮徵陪歌扇，莫遣新聲鄭衛侵。"]', '["筠管參差排鳳翅，月堂淒切勝龙吟。","最宜轻动纖纖玉，醉送當观灩灩金。","緱嶺独能徵妙曲，嬴台相共吹清音。","好將宮徵陪歌扇，莫遣新声鄭衛侵。"]', '诗', 'shi', '', NULL, '題笙 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f4d21dc-5107-4aef-a92b-281d5bb8bb5b', '下第', '下第', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["謾把青春酒一杯，愁襟未信酒能開。","江邊依舊空歸去，帝里還如不到來。","門掩殘陽鳴鳥雀，花飛何處好池臺。","此時惆悵便堪老，何用人間歲月催。"]', '["謾把青春酒一杯，愁襟未信酒能开。","江邊依旧空归去，帝里還如不到来。","门掩殘陽鳴鸟雀，花飞何处好池台。","此时惆悵便堪老，何用人间歲月催。"]', '诗', 'shi', '', NULL, '下第 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('957e87f0-e303-4891-9c14-765e7a2dc7c4', '秋晚', '秋晚', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["殘星殘月一聲鐘，谷際巖隈爽氣濃。","不向碧臺驚醉夢，但來青鏡促愁容。","繁金露潔黃籠菊，獨翠煙凝遠澗松。","閑步幽林與苔徑，漸移栖鳥及鳴蛩。"]', '["殘星殘月一声鐘，谷際巖隈爽氣濃。","不向碧台驚醉梦，但来青镜促愁容。","繁金露潔黄籠菊，独翠煙凝远澗松。","闲步幽林與苔徑，漸移栖鸟及鳴蛩。"]', '诗', 'shi', '', NULL, '秋晚 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73948339-20a5-4f13-9bc7-8d1f600cb0e5', '長安春夕旅懷', '长安春夕旅懷', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["幾年栖旅寄西秦，不識花枝醉過春。","短艇閑思五湖浪，羸蹄愁伴九衢塵。","關河風雨迷歸夢，鐘鼓朝昏老此身。","忽向太平時節過，一竿持去老遺民。"]', '["幾年栖旅寄西秦，不識花枝醉過春。","短艇闲思五湖浪，羸蹄愁伴九衢塵。","关河风雨迷归梦，鐘鼓朝昏老此身。","忽向太平时節過，一竿持去老遺民。"]', '诗', 'shi', '', NULL, '長安春夕旅懷 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09145935-0a91-4b06-bc8d-38b09303fb62', '洛陽春望', '洛陽春望', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["洛陽春霽絕塵埃，嵩少煙嵐畫障開。","草色花光惹襟袖，簫聲歌響隔樓臺。","人心便覺閑多少，馬足方知倦往來。","愁上中橋橋上望，碧波東去夕陽催。"]', '["洛陽春霽絕塵埃，嵩少煙嵐畫障开。","草色花光惹襟袖，簫声歌响隔楼台。","人心便覺闲多少，马足方知倦往来。","愁上中橋橋上望，碧波东去夕陽催。"]', '诗', 'shi', '', NULL, '洛陽春望 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c87968f-becc-41e8-945a-59618dac60bb', '惜春', '惜春', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["燕歸巢後即離羣，吟倚東風恨日曛。","一別一年方見我，遊來遊去不禁君。","鶯花御苑看將盡，絲竹侯家亦少聞。","獨坐南樓正惆悵，柳塘花絮更紛紛。"]', '["燕归巢後即離羣，吟倚东风恨日曛。","一別一年方见我，游来游去不禁君。","鶯花御苑看將尽，絲竹侯家亦少闻。","独坐南楼正惆悵，柳塘花絮更紛紛。"]', '诗', 'shi', '', NULL, '惜春 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c129911-f342-445c-8e8d-acbbee0cd5a6', '冬日旅懷', '冬日旅懷', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["[烏]焰纔沈桂魄生，霜階擁褐暫吟行。","閑思江市白醪滿，靜憶僧窗綠綺橫。","塵土自憐長失計，雲帆尤覺有歸情。","幾多悵望無窮事，空畫爐灰坐到明。"]', '["[烏]焰纔沈桂魄生，霜階擁褐暫吟行。","闲思江市白醪满，静憶僧窗綠綺橫。","塵土自怜长失計，云帆尤覺有归情。","幾多悵望無窮事，空畫爐灰坐到明。"]', '诗', 'shi', '', NULL, '冬日旅懷 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e08b226-1b17-417b-96d8-e2d552b24efb', '春夕寄友人時有與歌者南北', '春夕寄友人时有與歌者南北', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["芳徑春歸花半開，碧山波暖雁初迴。","滿樓月色還依舊，昨夜歌聲自不來。","愁眼向誰零玉筯，征蹄何處駐紅埃？","中宵吟罷正惆悵，從此蘭堂鎖綠苔。"]', '["芳徑春归花半开，碧山波暖雁初迴。","满楼月色還依旧，昨夜歌声自不来。","愁眼向誰零玉筯，征蹄何处駐紅埃？","中宵吟罷正惆悵，從此蘭堂鎖綠苔。"]', '诗', 'shi', '', NULL, '春夕寄友人時有與歌者南北 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0da9bfac-e088-40d2-bec3-31c7948a0cba', '春夜赤水驛旅懷', '春夜赤水驛旅懷', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["一星殘燭照離堂，失計遊心歸渺茫。","不自尋思無道路，爲誰辛苦競時光。","九衢春色休回首，半夜溪聲正夢鄉。","却羨去年買山侶，月斜漁艇倚瀟湘。"]', '["一星殘燭照離堂，失計游心归渺茫。","不自尋思無道路，爲誰辛苦競时光。","九衢春色休回首，半夜溪声正梦乡。","却羨去年買山侶，月斜漁艇倚瀟湘。"]', '诗', 'shi', '', NULL, '春夜赤水驛旅懷 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0242bab9-b70e-4a92-9c2b-9bdeb42d5c56', '春山山館旅懷', '春山山館旅懷', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["山館吟餘山月斜，東風搖曳拂窗花。","豈知驅馬無閑日，長在他人後到家。","孤劒向誰開壯節，流年催我自堪嗟。","燈前結束又前去，曉出石林啼亂鴉。"]', '["山館吟餘山月斜，东风搖曳拂窗花。","豈知驱马無闲日，长在他人後到家。","孤劒向誰开壯節，流年催我自堪嗟。","灯前結束又前去，晓出石林啼亂鴉。"]', '诗', 'shi', '', NULL, '春山山館旅懷 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e6565e9-cbc3-46c8-9d6d-7e301a0369fa', '秋夕旅懷', '秋夕旅懷', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["階前月色與蛩聲，階上愁人坐復行。","秦谷入霜空有夢，越山無計可歸耕。","窮途若遣長堪慟，華髪無因肯晚生。","不似扁舟釣魚者，免將心事筭浮榮。"]', '["階前月色與蛩声，階上愁人坐复行。","秦谷入霜空有梦，越山無計可归耕。","窮途若遣长堪慟，华髪無因肯晚生。","不似扁舟釣鱼者，免將心事筭浮榮。"]', '诗', 'shi', '', NULL, '秋夕旅懷 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f2b0a52-7223-4099-b2cb-62a1e4a46af3', '春過白遙嶺', '春過白遙嶺', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["鳥道穿雲望峽遙，羸蹄經宿在岧嶤。","到來山下春將半，上得林端雪未消。","返駕王尊何足歎，哭途阮籍謾無聊。","未知遇此恓惶者，泣向東風鬢欲凋。"]', '["鸟道穿云望峽遙，羸蹄經宿在岧嶤。","到来山下春將半，上得林端雪未消。","返駕王尊何足歎，哭途阮籍謾無聊。","未知遇此恓惶者，泣向东风鬢欲凋。"]', '诗', 'shi', '', NULL, '春過白遙嶺 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ca559ff-b536-4ed0-967d-7f4f4e7723dc', '別夜', '別夜', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["秋入江天河漢清，迢迢鐘漏出孤城。","金波千里別來夜，玉筯兩行流到明。","若在人間須有恨，除非禪伴始無情。","人間誰有□□□，聚散自然惆悵生。"]', '["秋入江天河漢清，迢迢鐘漏出孤城。","金波千里別来夜，玉筯兩行流到明。","若在人间須有恨，除非禪伴始無情。","人间誰有□□□，聚散自然惆悵生。"]', '诗', 'shi', '', NULL, '別夜 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8dd8e601-a5a7-4b89-93d8-38e8823e2385', '費拾遺書堂', '費拾遺书堂', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["滿袖歸來天桂香，紫泥重降舊書堂。","自憐葦帶同巢許，不駕蒲輪佐禹湯。","怪石盡含千古秀，奇花多吐四時芳。","何人更肯追高躅，唯有樵童戲蘚牀。"]', '["满袖归来天桂香，紫泥重降旧书堂。","自怜葦带同巢許，不駕蒲輪佐禹湯。","怪石尽含千古秀，奇花多吐四时芳。","何人更肯追高躅，唯有樵童戲蘚牀。"]', '诗', 'shi', '', NULL, '費拾遺書堂 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80d9fadc-f398-48c0-8ce1-ff382746bdf5', '溪上春望', '溪上春望', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["無端溪上看蘭橈，又是東風斷柳條。","雙鬢多於愁裏鑷，四時須向醉中銷。","行人駿馬嘶香陌，獨我殘陽倚野橋。","吟水詠山心未已，可能終不勝漁樵。"]', '["無端溪上看蘭橈，又是东风斷柳條。","雙鬢多於愁裏鑷，四时須向醉中銷。","行人駿马嘶香陌，独我殘陽倚野橋。","吟水詠山心未已，可能終不勝漁樵。"]', '诗', 'shi', '', NULL, '溪上春望 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8af7baed-0611-45a6-97d6-af6ef63f2680', '獻池州庾員外', '獻池州庾員外', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["曾降瑤緘薦姓名，攀雲幾合到蓬瀛。","須存彭壽千年在，終見茅公九轉成。","鯤海已知勞鶴使，螢窗不那夢霓旌。","琪花玉蔓應相笑，未得歌吟從酒行。"]', '["曾降瑤緘薦姓名，攀云幾合到蓬瀛。","須存彭壽千年在，終见茅公九轉成。","鯤海已知勞鹤使，螢窗不那梦霓旌。","琪花玉蔓應相笑，未得歌吟從酒行。"]', '诗', 'shi', '', NULL, '獻池州庾員外 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36c3ee47-4465-4ac4-bc0d-f6de06e6ad55', '春風', '春风', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["每歲東來助發生，舞空悠颺徧寰瀛。","暗添芳草池塘色，遠遰高樓簫管聲。","簾透驪宮偏帶恨，花催上苑剩多情。","如何一瑞車書日，吹取青雲道路平。"]', '["每歲东来助發生，舞空悠颺徧寰瀛。","暗添芳草池塘色，远遰高楼簫管声。","簾透驪宮偏带恨，花催上苑剩多情。","如何一瑞车书日，吹取青云道路平。"]', '诗', 'shi', '', NULL, '春風 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89341c14-9073-4972-a1b4-d5f3fb6fbdb4', '冬日寄獻庾員外', '冬日寄獻庾員外', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["曾謁仙宮最上仙，西風許醉桂花前。","爭歡酒蟻浮金爵，從聽歌塵撲翠蟬。","秋霽捲簾凝錦席，夜闌吹笛稱江天。","却思紫陌觥籌地，兔缺烏沈欲半年。"]', '["曾謁仙宮最上仙，西风許醉桂花前。","爭歡酒蟻浮金爵，從听歌塵撲翠蟬。","秋霽捲簾凝錦席，夜闌吹笛稱江天。","却思紫陌觥籌地，兔缺烏沈欲半年。"]', '诗', 'shi', '', NULL, '冬日寄獻庾員外 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1af95f36-d4af-43a1-ac11-be247ce226c5', '釣翁', '釣翁', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["來往煙波非定居，生涯簑褐外無餘。","閑垂兩鬢任如鶴，只繫一竿時得魚。","月浦扣船歌皎潔，雨蓬隈岸臥蕭疎。","行人誤話金張貴，笑指北邙丘與墟。"]', '["来往煙波非定居，生涯簑褐外無餘。","闲垂兩鬢任如鹤，只繫一竿时得鱼。","月浦扣船歌皎潔，雨蓬隈岸臥蕭疎。","行人誤話金張貴，笑指北邙丘與墟。"]', '诗', 'shi', '', NULL, '釣翁 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c27daaf8-489e-4fdb-8d82-85a074f8fd2e', '聞友人入越幕因以詩贈', '闻友人入越幕因以诗贈', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["稽嶺春生酒凍銷，煙鬟紅袖恃嬌饒。","岸邊叢雪晴香老，波上長虹晚影遙。","正哭阮途歸未得，更聞江筆赴嘉招。","人間榮瘁真堪恨，坐想征軒鬢欲凋。"]', '["稽嶺春生酒凍銷，煙鬟紅袖恃嬌饒。","岸邊叢雪晴香老，波上长虹晚影遙。","正哭阮途归未得，更闻江笔赴嘉招。","人间榮瘁真堪恨，坐想征軒鬢欲凋。"]', '诗', 'shi', '', NULL, '聞友人入越幕因以詩贈 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e2f42f6-d672-416b-aca2-f19ec01f7c88', '東歸', '东归', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["日日唯憂行役遲，東歸可是有家歸。","都緣桂玉無門住，不算山川去路危。","秦樹夢愁黃鳥囀，吳江釣憶錦鱗肥。","桃夭李豔清明近，惆悵當年意盡違。"]', '["日日唯憂行役遲，东归可是有家归。","都緣桂玉無门住，不算山川去路危。","秦樹梦愁黄鸟囀，吳江釣憶錦鱗肥。","桃夭李豔清明近，惆悵當年意尽違。"]', '诗', 'shi', '', NULL, '東歸 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa0f7f6d-5791-4ef9-b33d-1ab0d0c1b526', '入關', '入关', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["古道槐花滿樹開，入關時節一蟬催。","出門唯恐不先到，當路有誰長待來。","似箭年光還可惜，如蓬生計更堪哀。","故園若有漁舟在，應掛雲帆早箇迴。"]', '["古道槐花满樹开，入关时節一蟬催。","出门唯恐不先到，當路有誰长待来。","似箭年光還可惜，如蓬生計更堪哀。","故园若有漁舟在，應掛云帆早箇迴。"]', '诗', 'shi', '', NULL, '入關 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8401c4e5-86da-40c8-9353-c55fcf4cbb0e', '覽陳丕卷', '覽陳丕卷', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["雪宮詞客燕宮遊，一軸煙花象外搜。","謾把蜀紋當晝展，徒誇湘碧帶春流。","吟時致我寒侵骨，得處疑君白盡頭。","從北南歸明月夜，嶺猨灘鳥更悠悠。"]', '["雪宮词客燕宮游，一軸煙花象外搜。","謾把蜀紋當晝展，徒誇湘碧带春流。","吟时致我寒侵骨，得处疑君白尽头。","從北南归明月夜，嶺猨灘鸟更悠悠。"]', '诗', 'shi', '', NULL, '覽陳丕卷 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b37dae24-1d6c-4f55-8862-1bfc0f2c0414', '巴南旅舍言懷', '巴南旅舍言懷', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["萬浪千巖首未回，無憀相倚上高臺。","家山如畫不歸去，客舍似讐誰遣來。","紅淚罷窺連曉燭，碧波休引向春盃。","後時若有青雲望，何事偏教羽冀摧。"]', '["万浪千巖首未回，無憀相倚上高台。","家山如畫不归去，客舍似讐誰遣来。","紅泪罷窺連晓燭，碧波休引向春盃。","後时若有青云望，何事偏教羽冀摧。"]', '诗', 'shi', '', NULL, '巴南旅舍言懷 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6b5bc84-561d-4080-b1a8-0a6595a4a676', '登凌歊臺', '登凌歊台', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["高臺今日竟長閑，因想興亡自慘顏。","四海已歸新雨露，六朝空認舊江山。","槎翹獨鳥沙汀畔，風遰連檣雪浪間。","好是輪蹄來往便，誰人不向此躋攀。"]', '["高台今日竟长闲，因想兴亡自慘顏。","四海已归新雨露，六朝空認旧江山。","槎翹独鸟沙汀畔，风遰連檣雪浪间。","好是輪蹄来往便，誰人不向此躋攀。"]', '诗', 'shi', '', NULL, '登凌歊臺 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dedd5f45-dcab-46d9-8c14-0b29e5f19c2c', '僕射陂晚望', '僕射陂晚望', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["離人到此倍堪傷，陂水蘆花似故鄉。","身事未知何日了，馬蹄唯覺到秋忙。","田園牢落東歸晚，道路辛勤北去長。","却羨無愁是沙鳥，雙雙相趂下斜陽。"]', '["離人到此倍堪傷，陂水蘆花似故乡。","身事未知何日了，马蹄唯覺到秋忙。","田园牢落东归晚，道路辛勤北去长。","却羨無愁是沙鸟，雙雙相趂下斜陽。"]', '诗', 'shi', '', NULL, '僕射陂晚望 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebde1812-899f-4fa6-8345-ddf561e71e56', '芳草', '芳草', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["廢苑牆南殘雨中，似袍顏色在蒙茸。","微香暗惹遊人步，遠綠纔分鬬雉蹤。","三楚渡頭長恨見，五侯門外却難逢。","年年縱有春風便，馬跡車輪一萬重。"]', '["廢苑牆南殘雨中，似袍顏色在蒙茸。","微香暗惹游人步，远綠纔分鬬雉蹤。","三楚渡头长恨见，五侯门外却难逢。","年年縱有春风便，马跡车輪一万重。"]', '诗', 'shi', '', NULL, '芳草 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2275de93-9ca8-4161-b871-382e33398f41', '秋日留題蔣亭', '秋日留題蔣亭', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["西風纔起一蟬鳴，便筭關河馬上程。","碧浪鷁舟從此別，丹霄鵠箭忍無成。","二年芳思隨雲雨，幾日離歌戀斾旌。","回首橫塘更東望，露荷煙菊倍傷情。"]', '["西风纔起一蟬鳴，便筭关河马上程。","碧浪鷁舟從此別，丹霄鵠箭忍無成。","二年芳思隨云雨，幾日離歌戀斾旌。","回首橫塘更东望，露荷煙菊倍傷情。"]', '诗', 'shi', '', NULL, '秋日留題蔣亭 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d295299f-31e4-4da1-bb0a-f42829fd8503', '早發', '早發', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["一點燈殘魯酒醒，已攜孤劒事離程。","愁看飛雪聞雞唱，獨向長空背雁行。","白草近關微有路，濁河連底凍無聲。","此中來往本迢遞，況是驅羸客塞城。"]', '["一点灯殘魯酒醒，已携孤劒事離程。","愁看飞雪闻雞唱，独向长空背雁行。","白草近关微有路，濁河連底凍無声。","此中来往本迢遞，況是驱羸客塞城。"]', '诗', 'shi', '', NULL, '早發 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ed58ce0-6658-4aa2-aaa8-618541648884', '雁二首 一', '雁二首 一', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["暮天新鴈起汀洲，紅蓼花開水國愁。","想得故園今夜月，幾人相憶在江樓。"]', '["暮天新鴈起汀洲，紅蓼花开水国愁。","想得故园今夜月，幾人相憶在江楼。"]', '诗', 'shi', '', NULL, '雁二首 一 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8252846-2511-4161-ba12-397de464c9d0', '雁二首 二', '雁二首 二', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["早背胡霜過戍樓，又隨寒日下汀洲。","江南江北多離別，忍報年年兩地愁。"]', '["早背胡霜過戍楼，又隨寒日下汀洲。","江南江北多離別，忍報年年兩地愁。"]', '诗', 'shi', '', NULL, '雁二首 二 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e9b0d61-33ac-463f-809e-66c9b47e75d1', '螢二首 一', '螢二首 一', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["水殿清風玉戶開，飛光千點去還來。","無風無月長門夜，偏到階前點綠苔。"]', '["水殿清风玉戶开，飞光千点去還来。","無风無月长门夜，偏到階前点綠苔。"]', '诗', 'shi', '', NULL, '螢二首 一 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffa018d6-b04a-4331-9bd2-c15cef111fcc', '螢二首 二', '螢二首 二', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["裴回無燭冷無煙，秋逕莎庭入夜天。","休向書窗來照字，近來紅蠟滿歌筵。"]', '["裴回無燭冷無煙，秋逕莎庭入夜天。","休向书窗来照字，近来紅蠟满歌筵。"]', '诗', 'shi', '', NULL, '螢二首 二 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb09f085-ca1f-412e-b42f-849fdc7aa583', '看花', '看花', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["花開只恐看來遲，及到愁如未看時。","家在楚鄉身在蜀，一年春色負歸期。"]', '["花开只恐看来遲，及到愁如未看时。","家在楚乡身在蜀，一年春色負归期。"]', '诗', 'shi', '', NULL, '看花 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96c6b703-07dc-4683-b51f-72ab5dbc65ae', '柳絮', '柳絮', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["處處東風撲晚陽，輕輕醉粉落無香。","就中堪恨隋堤上，曾惹龍舟舞鳳凰。"]', '["处处东风撲晚陽，轻轻醉粉落無香。","就中堪恨隋堤上，曾惹龙舟舞鳳凰。"]', '诗', 'shi', '', NULL, '柳絮 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21191040-9160-4209-9b71-8c3bc6d40ae7', '雲', '云', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["紛紛靄靄遍江湖，得路爲霖豈合無。","莫使悠颺只如此，帝鄉還更暖蒼梧。"]', '["紛紛靄靄遍江湖，得路爲霖豈合無。","莫使悠颺只如此，帝乡還更暖蒼梧。"]', '诗', 'shi', '', NULL, '雲 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb6afac5-da67-4bf6-9d68-3e5ac0657981', '芳草', '芳草', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["曲江岸上天街裏，兩地縱生車馬多。","不似萋萋南浦見，晚來煙雨半相和。"]', '["曲江岸上天街裏，兩地縱生车马多。","不似萋萋南浦见，晚来煙雨半相和。"]', '诗', 'shi', '', NULL, '芳草 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d373e8bf-69fb-4e7d-b813-ff4af3ea8eb2', '出都門', '出都门', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["青門春色一花開，長到花時把酒杯。","自覺無家似潮水，不知歸處去還來。"]', '["青门春色一花开，长到花时把酒杯。","自覺無家似潮水，不知归处去還来。"]', '诗', 'shi', '', NULL, '出都門 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd31fa64-9db7-4b44-9eb6-7ab77f6c5730', '宮中二首 一', '宮中二首 一', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["芳草長含玉輦塵，君王遊幸此中頻。","今朝別有承恩處，鸚鵡飛來說似人。"]', '["芳草长含玉輦塵，君王游幸此中頻。","今朝別有承恩处，鸚鵡飞来说似人。"]', '诗', 'shi', '', NULL, '宮中二首 一 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7a0a09f-5eb7-4058-a94e-6a97311e5bb0', '宮中二首 二', '宮中二首 二', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["雖然自小屬梨園，不識先皇玉殿門。"]', '["雖然自小屬梨园，不識先皇玉殿门。"]', '诗', 'shi', '', NULL, '宮中二首 二 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34595ff5-f069-470b-8b60-bb590bd30039', '河湟', '河湟', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["河湟何計絕烽煙，免使征人更戍邊。","盡放農桑無一事，遣教知有太平年。"]', '["河湟何計絕烽煙，免使征人更戍邊。","尽放農桑無一事，遣教知有太平年。"]', '诗', 'shi', '', NULL, '河湟 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7e5dfbb-f218-43ff-819b-802416b3ff11', '聞子規', '闻子規', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["蜀魄千年尚怨誰，聲聲啼血向花枝。","滿山明月東風夜，正是愁人不寐時。"]', '["蜀魄千年尚怨誰，声声啼血向花枝。","满山明月东风夜，正是愁人不寐时。"]', '诗', 'shi', '', NULL, '聞子規 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe0199b5-a409-41d8-9401-9f6dcb2c3510', '望仙', '望仙', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["千山壘土望三山，雲鶴無蹤羽衛還。","若說神仙求便得，茂陵何事在人間。"]', '["千山壘土望三山，云鹤無蹤羽衛還。","若说神仙求便得，茂陵何事在人间。"]', '诗', 'shi', '', NULL, '望仙 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2872cb01-a564-43af-8d21-0fec6cce7768', '放鷓鴣', '放鷓鴣', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["好傍青山與碧溪，刺桐毛竹待雙栖。","花時遷客傷離別，莫向相思樹上啼。"]', '["好傍青山與碧溪，刺桐毛竹待雙栖。","花时遷客傷離別，莫向相思樹上啼。"]', '诗', 'shi', '', NULL, '放鷓鴣 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b654b54-d1ab-4799-9a92-7eaf483749ad', '驪山', '驪山', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["風搖巖桂露聞香，白鹿驚時出繞牆。","不向驪山鎖宮殿，可知仙去是明皇。"]', '["风搖巖桂露闻香，白鹿驚时出繞牆。","不向驪山鎖宮殿，可知仙去是明皇。"]', '诗', 'shi', '', NULL, '驪山 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('546b15ae-fceb-40ec-8fc0-2120b3c7fa91', '梅花', '梅花', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["繁如瑞雪壓枝開，越嶺吳溪免用栽。","却是五侯家未識，春風不放過江來。"]', '["繁如瑞雪壓枝开，越嶺吳溪免用栽。","却是五侯家未識，春风不放過江来。"]', '诗', 'shi', '', NULL, '梅花 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2359cbed-80f6-45fb-a961-d6f6b7106ac3', '雞冠花', '雞冠花', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["一枝穠豔對秋光，露滴風搖倚砌傍。","曉景乍看何處似，謝家新染紫羅裳。"]', '["一枝穠豔对秋光，露滴风搖倚砌傍。","晓景乍看何处似，謝家新染紫羅裳。"]', '诗', 'shi', '', NULL, '雞冠花 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('616815d3-539f-4a58-ab6e-97dbe3b035e0', '汴河', '汴河', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["煬帝開河鬼亦悲，生民不獨力空疲。","至今嗚咽東流水，似向清平怨昔時。"]', '["煬帝开河鬼亦悲，生民不独力空疲。","至今嗚咽东流水，似向清平怨昔时。"]', '诗', 'shi', '', NULL, '汴河 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9eb4c63-9fc7-4d91-85ea-d1bb4b6a8b99', '渡江有感', '渡江有感', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["岸落殘紅錦雉飛，渡江船上夕陽微。","一枝猶負平生意，歸去何曾勝不歸。"]', '["岸落殘紅錦雉飞，渡江船上夕陽微。","一枝猶負平生意，归去何曾勝不归。"]', '诗', 'shi', '', NULL, '渡江有感 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef4fe546-b1eb-4315-8148-361756a12d45', '題終南山僧堂', '題終南山僧堂', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["九衢終日見南山，名利何人肯掩關。","唯有吾師達真理，坐看霜樹老雲間。"]', '["九衢終日见南山，名利何人肯掩关。","唯有吾師達真理，坐看霜樹老云间。"]', '诗', 'shi', '', NULL, '題終南山僧堂 羅鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e15e43d4-98d6-46e7-a6c2-b004d2e0a7f1', '大散嶺', '大散嶺', '7fe136db-b5eb-4b9a-b475-e47a46ca98dc', '唐', '["過往長逢日色稀，雪花如掌撲行衣。","嶺頭却望人來處，特地身疑是鳥飛。"]', '["過往长逢日色稀，雪花如掌撲行衣。","嶺头却望人来处，特地身疑是鸟飞。"]', '诗', 'shi', '', NULL, '大散嶺 羅鄴 shi');
